// ─── Gita Voice/Chat Model Test Suite ───────────────────────
// Usage: VOICE_URL=https://noisy-sheep-76.sravanku018.deno.net deno run --allow-net --allow-env test-voice.ts

const VOICE_URL = Deno.env.get("VOICE_URL") || "https://noisy-sheep-76.sravanku018.deno.net";

let passed = 0;
let failed = 0;
const failures: string[] = [];

// ─── HELPERS ─────────────────────────────────────────────────
async function chat(messages: { role: string; content: string }[]): Promise<any> {
  const res = await fetch(VOICE_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ messages }),
  });
  return res.json();
}

async function simpleChat(message: string): Promise<any> {
  const res = await fetch(VOICE_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ message }),
  });
  return res.json();
}

function assert(name: string, condition: boolean, detail = "") {
  if (condition) {
    console.log(`  ✅ ${name}`);
    passed++;
  } else {
    console.log(`  ❌ ${name}${detail ? ` — ${detail}` : ""}`);
    failed++;
    failures.push(`${name}${detail ? `: ${detail}` : ""}`);
  }
}

function section(name: string) {
  console.log(`\n─── ${name} ${"─".repeat(40 - name.length)}`);
}

function printReply(label: string, reply: string) {
  console.log(`\n  💬 ${label}:`);
  console.log(`     ${reply.slice(0, 200)}${reply.length > 200 ? "..." : ""}`);
}

// ═══════════════════════════════════════════════════════════════
// TESTS
// ═══════════════════════════════════════════════════════════════

// ─── 1. SERVER HEALTH ────────────────────────────────────────
section("SERVER HEALTH");
{
  const res = await fetch(VOICE_URL);
  const text = await res.text();
  assert("GET / — server alive", res.ok, text);
  console.log(`  ℹ️  Server: ${text}`);
}

// ─── 2. SIMPLE MESSAGE FORMAT ────────────────────────────────
section("SIMPLE MESSAGE FORMAT");
{
  const res = await simpleChat("What is the Bhagavad Gita?");
  assert("Simple message — has reply", typeof res.reply === "string", JSON.stringify(res));
  assert("Simple message — reply not empty", res.reply.length > 10);
  assert("Simple message — not silent", res.reply !== "The cards are silent...");
  printReply("Gita question", res.reply);
}

// ─── 3. MESSAGES ARRAY FORMAT ────────────────────────────────
section("MESSAGES ARRAY FORMAT");
{
  const res = await chat([
    { role: "user", content: "What is karma?" }
  ]);
  assert("Messages format — has reply", typeof res.reply === "string");
  assert("Messages format — reply not empty", res.reply.length > 10);
  printReply("Karma question", res.reply);
}

// ─── 4. GITA CONTENT QUESTIONS ───────────────────────────────
section("GITA CONTENT QUESTIONS");
{
  const questions = [
    "What does Krishna say about duty in Bhagavad Gita?",
    "Explain the concept of Dharma",
    "What is the meaning of Chapter 2 verse 47?",
    "How to achieve moksha according to Gita?",
  ];

  for (const q of questions) {
    const res = await simpleChat(q);
    const hasReply = typeof res.reply === "string" && res.reply.length > 20;
    assert(`Gita Q: "${q.slice(0, 40)}..."`, hasReply);
    if (hasReply) printReply("Reply", res.reply);
  }
}

// ─── 5. TELUGU QUESTIONS ─────────────────────────────────────
section("TELUGU LANGUAGE");
{
  const teluguQuestions = [
    "భగవద్గీత అంటే ఏమిటి?",
    "కర్మ యోగం గురించి చెప్పండి",
    "ధర్మం అంటే ఏమిటి?",
  ];

  for (const q of teluguQuestions) {
    const res = await simpleChat(q);
    const hasReply = typeof res.reply === "string" && res.reply.length > 10;
    assert(`Telugu Q: "${q}"`, hasReply);
    if (hasReply) printReply("Reply", res.reply);
  }
}

// ─── 6. MULTI-TURN CONVERSATION ──────────────────────────────
section("MULTI-TURN CONVERSATION");
{
  const res = await chat([
    { role: "user", content: "What is karma?" },
    { role: "assistant", content: "Karma refers to the law of cause and effect..." },
    { role: "user", content: "Can you give me an example from Gita?" },
  ]);
  assert("Multi-turn — has reply", typeof res.reply === "string" && res.reply.length > 10);
  assert("Multi-turn — context aware", !res.reply.includes("The cards are silent"));
  printReply("Multi-turn reply", res.reply);
}

// ─── 7. EDGE CASES ───────────────────────────────────────────
section("EDGE CASES");
{
  // Empty message
  const empty = await simpleChat("");
  assert("Empty message — no crash", typeof empty.reply === "string");

  // Very short message
  const short = await simpleChat("Hi");
  assert("Short message — responds", typeof short.reply === "string" && short.reply.length > 0);
  printReply("Hi reply", short.reply);

  // Very long message
  const long = await simpleChat("What does Krishna say about " + "karma ".repeat(50) + "in the Bhagavad Gita?");
  assert("Long message — responds", typeof long.reply === "string" && long.reply.length > 0);

  // Off-topic question
  const offTopic = await simpleChat("What is the capital of France?");
  assert("Off-topic — no crash", typeof offTopic.reply === "string");
  printReply("Off-topic reply", offTopic.reply);
}

// ─── 8. RESPONSE QUALITY ─────────────────────────────────────
section("RESPONSE QUALITY");
{
  const res = await simpleChat("What does Bhagavad Gita Chapter 2 Verse 47 say?");
  const reply = res.reply || "";

  // Check for Gita-related keywords
  const hasGitaContext = /karma|duty|action|result|fruit|कर्म|dharma|arjuna|krishna/i.test(reply);
  assert("Quality — Gita context in reply", hasGitaContext, `Reply: ${reply.slice(0, 100)}`);

  // Check reply is substantial
  assert("Quality — reply > 50 chars", reply.length > 50, `Length: ${reply.length}`);

  // Check not error message
  const isError = reply.includes("veil is thick") || reply.includes("cards are silent");
  assert("Quality — not error fallback", !isError);

  printReply("Chapter 2:47", reply);
}

// ─── 9. LATENCY CHECK ────────────────────────────────────────
section("LATENCY");
{
  const start = Date.now();
  await simpleChat("What is yoga?");
  const latency = Date.now() - start;

  assert("Latency — under 10s", latency < 10000, `${latency}ms`);
  console.log(`  ℹ️  Response time: ${latency}ms`);

  if (latency < 3000) console.log("  ⚡ Fast response!");
  else if (latency < 6000) console.log("  🟡 Acceptable response time");
  else console.log("  🔴 Slow — check Groq API or model");
}

// ─── 10. INVALID REQUEST ─────────────────────────────────────
section("INVALID REQUEST");
{
  // No body
  const res = await fetch(VOICE_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: "{}",
  });
  const data = await res.json();
  assert("Empty body — no 500 crash", res.status !== 500, `Status: ${res.status}`);
  assert("Empty body — has reply field", typeof data.reply === "string");
}

// ─── RESULTS ─────────────────────────────────────────────────
console.log("\n" + "═".repeat(50));
console.log(`RESULTS: ${passed} passed, ${failed} failed`);
if (failures.length > 0) {
  console.log("\nFailed tests:");
  failures.forEach(f => console.log(`  ❌ ${f}`));
}
console.log("═".repeat(50));

Deno.exit(failed > 0 ? 1 : 0);

package com.aipoweredgita.app.repository

import android.content.Context
import android.util.Log
import com.aipoweredgita.app.database.PendingSyncEvent
import com.aipoweredgita.app.network.CoinApi
import com.aipoweredgita.app.network.PendingEvent
import com.aipoweredgita.app.network.ReconcileRequest
import com.aipoweredgita.app.utils.AuthPreferences

/**
 * Coin reconciliation mechanism
 * Detects and corrects balance mismatches between client and server
 */
class CoinReconciliationManager(
    private val context: Context,
    private val pendingSyncEventDao: com.aipoweredgita.app.database.PendingSyncEventDao
) {
    companion object {
        private const val TAG = "CoinReconciliation"
    }

    /**
     * Reconcile client balance with server
     * Should be called on app startup or when balance seems wrong
     */
    suspend fun reconcile(): ReconciliationResult {
        val authPrefs = AuthPreferences.getInstance(context)

        // Skip for guest users
        if (authPrefs.isGuestUser) {
            return ReconciliationResult.Skip("Guest user - using local coins")
        }

        val userId = authPrefs.userId ?: return ReconciliationResult.Skip("No user ID")
        val localBalance = authPrefs.localCoins

        // Get pending events from local database
        val pendingEvents = pendingSyncEventDao.getPendingEvents(userId)
            .map { event ->
                PendingEvent(
                    idempotency_key = "${event.eventType}_${event.userId}_${event.timestamp}",
                    coinsToAdjust = event.coinsToAdjust
                )
            }

        return try {
            val response = CoinApi.retrofitService.reconcileBalance(
                ReconcileRequest(
                    user_id = userId,
                    local_balance = localBalance,
                    pending_events = pendingEvents
                )
            )

            if (response.needs_correction) {
                // Apply correction
                authPrefs.localCoins = response.expected_balance

                Log.w(TAG, "Balance corrected: $localBalance → ${response.expected_balance} (delta: ${response.correction_delta})")

                ReconciliationResult.Corrected(
                    oldBalance = localBalance,
                    newBalance = response.expected_balance,
                    delta = response.correction_delta,
                    unprocessedEvents = response.unprocessed_events.size
                )
            } else {
                Log.d(TAG, "Balance OK: $localBalance matches server")
                ReconciliationResult.OK(localBalance)
            }
        } catch (e: Exception) {
            Log.e(TAG, "Reconciliation failed: ${e.message}")
            ReconciliationResult.Error(e.message ?: "Unknown error")
        }
    }
}

sealed class ReconciliationResult {
    data class OK(val balance: Int) : ReconciliationResult()
    data class Corrected(
        val oldBalance: Int, 
        val newBalance: Int, 
        val delta: Int,
        val unprocessedEvents: Int
    ) : ReconciliationResult()
    data class Skip(val reason: String) : ReconciliationResult()
    data class Error(val message: String) : ReconciliationResult()
}

# Deno Backend - Original Version

This is the clean/original version of the Deno backend without the auto-reconciliation changes.

```typescript
import { createClient } from "https://esm.sh/@libsql/client/http";

const db = createClient({
  url: Deno.env.get("TURSO_URL")!,
  authToken: Deno.env.get("TURSO_TOKEN")!,
});

const cors = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization",
};

function json(data: unknown, status = 200) {
  return Response.json(data, { status, headers: cors });
}

async function hashPassword(password: string): Promise<string> {
  const encoder = new TextEncoder();
  const data = encoder.encode(password);
  const hashBuffer = await crypto.subtle.digest("SHA-256", data);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
}

function generateToken(): string {
  return crypto.randomUUID();
}

// ─── HANDLE DELETE ACCOUNT ─────────────────────────────────────
async function handleDeleteAccount(req: Request): Promise<Response> {
  const token = req.headers.get("Authorization")?.replace("Bearer ", "");
  if (!token) return json({ error: "Unauthorized" }, 401);

  const session = await db.execute({
    sql: `SELECT user_id FROM sessions WHERE token = ? AND expires_at > datetime('now')`,
    args: [token],
  });
  if (!session.rows.length) return json({ error: "Invalid or expired token" }, 401);

  const user_id = session.rows[0].user_id as string;

  await db.execute({ sql: `DELETE FROM sloka_shares WHERE user_id = ?`,      args: [user_id] });
  await db.execute({ sql: `DELETE FROM coin_transactions WHERE user_id = ?`, args: [user_id] });
  await db.execute({ sql: `DELETE FROM checkin_streaks WHERE user_id = ?`,   args: [user_id] });
  await db.execute({ sql: `DELETE FROM level_history WHERE user_id = ?`,     args: [user_id] });
  await db.execute({ sql: `DELETE FROM sessions WHERE user_id = ?`,          args: [user_id] });
  await db.execute({ sql: `DELETE FROM user_stats WHERE user_id = ?`,        args: [user_id] });
  await db.execute({ sql: `DELETE FROM users WHERE user_id = ?`,             args: [user_id] });

  return json({ success: true });
}

Deno.serve(async (req: Request) => {
  try {
    const url = new URL(req.url);
    const path = url.pathname;

    if (req.method === "OPTIONS") {
      return new Response(null, { headers: cors });
    }

    if (path === "/") {
      return json({
        status: "Gita App API running ✅",
        endpoints: [
          "POST /auth/register",
          "POST /auth/login",
          "GET  /auth/verify",
          "POST /auth/logout",
          "POST /auth/delete",
          "POST /guest/create",
          "POST /guest/claim",
          "POST /users/create",
          "GET  /coins/balance?user_id=",
          "POST /coins/award",
          "POST /coins/spend",
          "GET  /coins/history?user_id=",
          "GET  /coins/leaderboard",
          "POST /checkin",
          "POST /share",
          "GET  /yoga/stages",
        ],
      });
    }

    // ─── AUTH REGISTER ─────────────────────────────────────────────
    if (req.method === "POST" && path === "/auth/register") {
      const { user_id, password, name = "", email = "" } = await req.json();

      if (!user_id || !password) {
        return json({ error: "user_id and password required" }, 400);
      }

      const existing = await db.execute({
        sql: "SELECT user_id FROM users WHERE user_id = ?",
        args: [user_id],
      });

      if (existing.rows.length) {
        return json({ error: "User already exists" }, 400);
      }

      const passwordHash = await hashPassword(password);

      await db.execute({
        sql: `INSERT INTO users (user_id, name, email, password_hash, is_guest) VALUES (?, ?, ?, ?, 0)`,
        args: [user_id, name, email, passwordHash],
      });
      await db.execute({
        sql: `INSERT INTO user_stats (user_id, krishna_coins, days_active, yoga_level) VALUES (?, 200, 1, 1)`,
        args: [user_id],
      });
      await db.execute({
        sql: `INSERT OR IGNORE INTO checkin_streaks (user_id, current_day, current_week, share_day, share_week) VALUES (?, 0, 1, 0, 1)`,
        args: [user_id],
      });
      await db.execute({
        sql: `INSERT INTO coin_transactions (user_id, amount, type, source, description) VALUES (?, 200, 'EARN', 'signup', 'Welcome bonus — new seeker')`,
        args: [user_id],
      });

      const token = generateToken();
      await db.execute({
        sql: `INSERT INTO sessions (user_id, token, expires_at) VALUES (?, ?, datetime('now', '+30 days'))`,
        args: [user_id, token],
      });

      return json({ success: true, user_id, token, coins: 200 });
    }

    // ─── AUTH LOGIN ────────────────────────────────────────────────
    if (req.method === "POST" && path === "/auth/login") {
      const { user_id, password } = await req.json();

      if (!user_id || !password) {
        return json({ error: "user_id and password required" }, 400);
      }

      const user = await db.execute({
        sql: "SELECT user_id, password_hash FROM users WHERE user_id = ?",
        args: [user_id],
      });

      if (!user.rows.length) {
        return json({ error: "User not found" }, 404);
      }

      const passwordHash = await hashPassword(password);

      if (user.rows[0].password_hash !== passwordHash) {
        return json({ error: "Invalid password" }, 401);
      }

      const token = generateToken();
      await db.execute({
        sql: `INSERT INTO sessions (user_id, token, expires_at) VALUES (?, ?, datetime('now', '+30 days'))`,
        args: [user_id, token],
      });

      const stats = await db.execute({
        sql: `SELECT krishna_coins, yoga_level FROM user_stats WHERE user_id = ?`,
        args: [user_id],
      });

      return json({
        success: true,
        user_id,
        token,
        coins: stats.rows[0]?.krishna_coins ?? 0,
        yoga_level: stats.rows[0]?.yoga_level ?? 1,
      });
    }

    // ─── AUTH VERIFY ───────────────────────────────────────────────
    if (req.method === "GET" && path === "/auth/verify") {
      const token = req.headers.get("Authorization")?.replace("Bearer ", "");

      if (!token) {
        return json({ error: "No token provided" }, 401);
      }

      const session = await db.execute({
        sql: `SELECT user_id FROM sessions WHERE token = ? AND expires_at > datetime('now')`,
        args: [token],
      });

      if (!session.rows.length) {
        return json({ error: "Invalid or expired token" }, 401);
      }

      const stats = await db.execute({
        sql: `SELECT krishna_coins, yoga_level FROM user_stats WHERE user_id = ?`,
        args: [session.rows[0].user_id],
      });

      return json({
        valid: true,
        user_id: session.rows[0].user_id,
        coins: stats.rows[0]?.krishna_coins ?? 0,
        yoga_level: stats.rows[0]?.yoga_level ?? 1,
      });
    }

    // ─── AUTH LOGOUT ───────────────────────────────────────────────
    if (req.method === "POST" && path === "/auth/logout") {
      const token = req.headers.get("Authorization")?.replace("Bearer ", "");

      if (token) {
        await db.execute({
          sql: "DELETE FROM sessions WHERE token = ?",
          args: [token],
        });
      }

      return json({ success: true });
    }

    // ─── AUTH DELETE ───────────────────────────────────────────────
    if (req.method === "POST" && path === "/auth/delete") {
      return handleDeleteAccount(req);
    }

    // ─── GUEST CREATE ───────────────────────────────────────────────
    if (req.method === "POST" && path === "/guest/create") {
      const guest_id = `guest_${crypto.randomUUID()}`;
      await db.execute({ sql: `INSERT INTO users (user_id, name, email, is_guest) VALUES (?, 'Guest', '', 1)`, args: [guest_id] });
      await db.execute({ sql: `INSERT INTO user_stats (user_id, krishna_coins, days_active, yoga_level) VALUES (?, 50, 1, 1)`, args: [guest_id] });
      await db.execute({ sql: `INSERT OR IGNORE INTO checkin_streaks (user_id, current_day, current_week, share_day, share_week) VALUES (?, 0, 1, 0, 1)`, args: [guest_id] });
      await db.execute({ sql: `INSERT INTO coin_transactions (user_id, amount, type, source, description) VALUES (?, 50, 'EARN', 'signup', 'Guest welcome bonus')`, args: [guest_id] });

      const token = generateToken();
      await db.execute({
        sql: `INSERT INTO sessions (user_id, token, expires_at) VALUES (?, ?, datetime('now', '+30 days'))`,
        args: [guest_id, token],
      });

      return json({ guest_id, token, coins: 50 });
    }

    // ─── GUEST CLAIM ────────────────────────────────────────────────
    if (req.method === "POST" && path === "/guest/claim") {
      const { guest_id, real_user_id, name = "", email = "" } = await req.json();

      const guest = await db.execute({ sql: "SELECT * FROM user_stats WHERE user_id = ?", args: [guest_id] });
      if (!guest.rows.length) return json({ error: "Guest not found" }, 404);

      const guestCoins = guest.rows[0].krishna_coins as number;
      const guestDays  = guest.rows[0].days_active as number;
      const guestLevel = guest.rows[0].yoga_level as number;

      const SYNC_BONUS = 150;

      const existing = await db.execute({ sql: "SELECT user_id FROM users WHERE user_id = ?", args: [real_user_id] });

      if (existing.rows.length) {
        await db.execute({
          sql: `UPDATE user_stats
                SET krishna_coins = MIN(krishna_coins + ? + ?, 10000),
                    days_active   = days_active + ?,
                    yoga_level    = MAX(yoga_level, ?),
                    updated_at    = datetime('now')
                WHERE user_id = ?`,
          args: [guestCoins, SYNC_BONUS, guestDays, guestLevel, real_user_id],
        });
        await db.execute({ sql: `INSERT INTO coin_transactions (user_id, amount, type, source, description) VALUES (?, ?, 'EARN', 'guest_migration', 'Guest progress transferred')`, args: [real_user_id, guestCoins] });
        await db.execute({ sql: `INSERT INTO coin_transactions (user_id, amount, type, source, description) VALUES (?, ?, 'EARN', 'sync_bonus', 'Loyalty reward — guest journey synced ✦')`, args: [real_user_id, SYNC_BONUS] });
      } else {
        await db.execute({ sql: `INSERT INTO users (user_id, name, email, is_guest) VALUES (?, ?, ?, 0)`, args: [real_user_id, name, email] });
        await db.execute({ sql: `UPDATE user_stats SET user_id = ? WHERE user_id = ?`, args: [real_user_id, guest_id] });
        await db.execute({ sql: `UPDATE coin_transactions SET user_id = ? WHERE user_id = ?`, args: [real_user_id, guest_id] });
        await db.execute({ sql: `UPDATE checkin_streaks SET user_id = ? WHERE user_id = ?`, args: [real_user_id, guest_id] });
        await db.execute({ sql: `UPDATE sloka_shares SET user_id = ? WHERE user_id = ?`, args: [real_user_id, guest_id] });
        await db.execute({ sql: `UPDATE users SET name = ?, email = ?, is_guest = 0 WHERE user_id = ?`, args: [name, email, real_user_id] });
        await db.execute({ sql: `UPDATE user_stats SET krishna_coins = MIN(krishna_coins + ?, 10000), updated_at = datetime('now') WHERE user_id = ?`, args: [200 + SYNC_BONUS, real_user_id] });
        await db.execute({ sql: `INSERT INTO coin_transactions (user_id, amount, type, source, description) VALUES (?, 200, 'EARN', 'signup', 'Welcome bonus — new seeker')`, args: [real_user_id] });
        await db.execute({ sql: `INSERT INTO coin_transactions (user_id, amount, type, source, description) VALUES (?, ?, 'EARN', 'sync_bonus', 'Loyalty reward — guest journey synced ✦')`, args: [real_user_id, SYNC_BONUS] });
      }

      await db.execute({ sql: `DELETE FROM user_stats WHERE user_id = ?`,        args: [guest_id] });
      await db.execute({ sql: `DELETE FROM checkin_streaks WHERE user_id = ?`,   args: [guest_id] });
      await db.execute({ sql: `DELETE FROM coin_transactions WHERE user_id = ?`, args: [guest_id] });
      await db.execute({ sql: `DELETE FROM sessions WHERE user_id = ?`,          args: [guest_id] });
      await db.execute({ sql: `DELETE FROM users WHERE user_id = ?`,             args: [guest_id] });

      return json({ success: true, user_id: real_user_id, sync_bonus: SYNC_BONUS });
    }

    // ─── USERS CREATE ───────────────────────────────────────────────
    if (req.method === "POST" && path === "/users/create") {
      const { user_id, name = "", email = "" } = await req.json();
      await db.execute({ sql: `INSERT OR IGNORE INTO users (user_id, name, email, is_guest) VALUES (?, ?, ?, 0)`, args: [user_id, name, email] });
      await db.execute({ sql: `INSERT OR IGNORE INTO user_stats (user_id, krishna_coins, days_active, yoga_level) VALUES (?, 200, 1, 1)`, args: [user_id] });
      await db.execute({ sql: `INSERT OR IGNORE INTO checkin_streaks (user_id, current_day, current_week, share_day, share_week) VALUES (?, 0, 1, 0, 1)`, args: [user_id] });
      await db.execute({ sql: `INSERT INTO coin_transactions (user_id, amount, type, source, description) VALUES (?, 200, 'EARN', 'signup', 'Welcome bonus — new seeker')`, args: [user_id] });
      return json({ success: true, coins: 200 });
    }

    // ─── COINS BALANCE ──────────────────────────────────────────────
    if (req.method === "GET" && path === "/coins/balance") {
      const user_id = url.searchParams.get("user_id");
      const result = await db.execute({
        sql: `SELECT us.krishna_coins, us.days_active,
                yl.name as yoga_name, yl.multiplier,
                CASE WHEN us.krishna_coins >= 10000 THEN 1 ELSE 0 END as is_max
              FROM user_stats us
              JOIN yoga_levels yl ON yl.level = us.yoga_level
              WHERE us.user_id = ?`,
        args: [user_id],
      });
      if (!result.rows.length) return json({ error: "User not found" }, 404);
      return json(result.rows[0]);
    }

    // ─── COINS AWARD ────────────────────────────────────────────────
    if (req.method === "POST" && path === "/coins/award") {
      const { user_id, source, metadata } = await req.json();
      const rule = await db.execute({ sql: "SELECT base_coins, max_coins FROM coin_rules WHERE source = ?", args: [source] });
      if (!rule.rows.length) return json({ error: "Unknown source" }, 400);

      let coins = rule.rows[0].base_coins as number;
      const maxCoins = rule.rows[0].max_coins as number | null;

      if (source === "quiz_completion" && metadata?.accuracy != null) {
        const accuracy      = Math.max(0, Math.min(1, metadata.accuracy));
        const accuracyBonus = Math.floor(accuracy * accuracy * 6);
        const streakDays    = metadata.streakDays ?? 0;
        const streakBonus   = Math.min(Math.floor(streakDays / 5), 3);
        const checkinDay    = metadata.checkinDay ?? 0;
        const checkinBonus  = checkinDay >= 7 ? 3 : checkinDay >= 5 ? 2 : checkinDay >= 2 ? 1 : 0;
        coins = coins + accuracyBonus + streakBonus + checkinBonus;
        if (maxCoins != null) coins = Math.min(coins, maxCoins);
      }

      const userStats = await db.execute({
        sql: `SELECT yl.multiplier FROM user_stats us JOIN yoga_levels yl ON yl.level = us.yoga_level WHERE us.user_id = ?`,
        args: [user_id],
      });
      const multiplier = userStats.rows.length ? (userStats.rows[0].multiplier as number) : 1;
      coins = Math.floor(coins * multiplier);

      await db.execute({ sql: `INSERT INTO coin_transactions (user_id, amount, type, source, description) VALUES (?, ?, 'EARN', ?, ?)`, args: [user_id, coins, source, JSON.stringify(metadata ?? {})] });
      await db.execute({ sql: `UPDATE user_stats SET krishna_coins = MIN(krishna_coins + ?, 10000), updated_at = datetime('now') WHERE user_id = ?`, args: [coins, user_id] });

      const stats = await db.execute({ sql: `SELECT krishna_coins, yoga_level FROM user_stats WHERE user_id = ?`, args: [user_id] });
      const totalCoins   = stats.rows[0].krishna_coins as number;
      const currentLevel = stats.rows[0].yoga_level as number;
      const newLevel     = totalCoins >= 9000 ? 5 : totalCoins >= 6000 ? 4 : totalCoins >= 3000 ? 3 : totalCoins >= 1000 ? 2 : 1;

      if (newLevel > currentLevel) {
        await db.execute({ sql: `UPDATE user_stats SET yoga_level = ? WHERE user_id = ?`, args: [newLevel, user_id] });
        await db.execute({ sql: `INSERT INTO level_history (user_id, from_level, to_level, coins_at_levelup, bonus_coins) VALUES (?, ?, ?, ?, 10)`, args: [user_id, currentLevel, newLevel, totalCoins] });
        await db.execute({ sql: `UPDATE user_stats SET krishna_coins = MIN(krishna_coins + 10, 10000) WHERE user_id = ?`, args: [user_id] });
      }

      return json({ awarded: coins, total_coins: totalCoins, levelled_up: newLevel > currentLevel, new_level: newLevel, multiplier });
    }

    // ─── COINS SPEND ────────────────────────────────────────────────
    if (req.method === "POST" && path === "/coins/spend") {
      const { user_id, question } = await req.json();
      const length = question.length;
      const rule   = await db.execute({ sql: `SELECT coins, label FROM voice_chat_rules WHERE min_chars <= ? AND (max_chars IS NULL OR max_chars >= ?)`, args: [length, length] });
      const cost   = rule.rows[0].coins as number;
      const label  = rule.rows[0].label as string;
      const stats  = await db.execute({ sql: "SELECT krishna_coins FROM user_stats WHERE user_id = ?", args: [user_id] });
      const balance = stats.rows[0].krishna_coins as number;
      if (balance < cost) return json({ error: "Not enough coins", balance, required: cost }, 400);
      await db.execute({ sql: `UPDATE user_stats SET krishna_coins = MAX(krishna_coins - ?, 0), updated_at = datetime('now') WHERE user_id = ?`, args: [cost, user_id] });
      await db.execute({ sql: `INSERT INTO coin_transactions (user_id, amount, type, source, description) VALUES (?, ?, 'SPEND', 'voice_chat', ?)`, args: [user_id, -cost, `Voice chat - ${label} (${length} chars)`] });
      return json({ spent: cost, label, remaining_balance: balance - cost });
    }

    // ─── CHECKIN ────────────────────────────────────────────────────
    if (req.method === "POST" && path === "/checkin") {
      const { user_id } = await req.json();
      const streak = await db.execute({ sql: "SELECT * FROM checkin_streaks WHERE user_id = ?", args: [user_id] });
      if (streak.rows.length) {
        const last  = streak.rows[0].last_checkin as string;
        const today = new Date().toISOString().split("T")[0];
        if (last && last === today) return json({ error: "Already checked in today" }, 400);
      }
      const current_day  = streak.rows.length ? ((streak.rows[0].current_day as number) % 7) + 1 : 1;
      const current_week = streak.rows.length ? (streak.rows[0].current_week as number) : 1;
      const reward       = await db.execute({ sql: "SELECT coins FROM checkin_rewards WHERE day = ?", args: [current_day] });
      let coins = reward.rows[0].coins as number;
      let weekly_bonus = 0;
      if (current_day === 7) {
        const bonusRule = await db.execute({ sql: "SELECT coins FROM weekly_bonus_rules WHERE week = ?", args: [current_week] });
        weekly_bonus = bonusRule.rows[0].coins as number;
        coins += weekly_bonus;
      }
      const next_week = current_day === 7 ? (current_week % 4) + 1 : current_week;
      await db.execute({ sql: `INSERT INTO checkin_streaks (user_id, current_day, current_week, last_checkin) VALUES (?, ?, ?, date('now')) ON CONFLICT(user_id) DO UPDATE SET current_day = ?, current_week = ?, last_checkin = date('now')`, args: [user_id, current_day, next_week, current_day, next_week] });
      await db.execute({ sql: `UPDATE user_stats SET krishna_coins = MIN(krishna_coins + ?, 10000), days_active = days_active + 1, updated_at = datetime('now') WHERE user_id = ?`, args: [coins, user_id] });
      await db.execute({ sql: `INSERT INTO coin_transactions (user_id, amount, type, source, description) VALUES (?, ?, 'EARN', 'checkin_day', ?)`, args: [user_id, coins, `Day ${current_day} check-in`] });
      return json({ day: current_day, week: current_week, coins_awarded: coins, weekly_bonus });
    }

    // ─── SHARE ──────────────────────────────────────────────────────
    if (req.method === "POST" && path === "/share") {
      const { user_id, sloka_id = null, chapter = null, verse = null } = await req.json();
      const streak = await db.execute({ sql: "SELECT * FROM checkin_streaks WHERE user_id = ?", args: [user_id] });
      if (streak.rows.length) {
        const last  = streak.rows[0].last_share as string;
        const today = new Date().toISOString().split("T")[0];
        if (last && last === today) return json({ error: "Already shared today" }, 400);
      }
      const share_day  = streak.rows.length ? ((streak.rows[0].share_day as number) % 7) + 1 : 1;
      const share_week = streak.rows.length ? (streak.rows[0].share_week as number) : 1;
      const reward     = await db.execute({ sql: "SELECT coins FROM checkin_rewards WHERE day = ?", args: [share_day] });
      let coins = reward.rows[0].coins as number;
      let weekly_bonus = 0;
      if (share_day === 7) {
        const bonusRule = await db.execute({ sql: "SELECT coins FROM weekly_bonus_rules WHERE week = ?", args: [share_week] });
        weekly_bonus = bonusRule.rows[0].coins as number;
        coins += weekly_bonus;
      }
      const next_week = share_day === 7 ? (share_week % 4) + 1 : share_week;
      await db.execute({ sql: `UPDATE checkin_streaks SET share_day = ?, share_week = ?, last_share = date('now') WHERE user_id = ?`, args: [share_day, next_week, user_id] });
