      return c.json({ error: "user_id and password required" }, 400);
    }
    if (!email) email = `${user_id}@gita.com`;

    const existing = await db.execute({
      sql: "SELECT user_id FROM users WHERE user_id = ?",
      args: [user_id],
    });
