package com.aipoweredgita.app

import android.util.Log
import com.aipoweredgita.app.repository.CoinReconciliationManager
import com.aipoweredgita.app.repository.AutoReconciliationResult
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch

/**
 * Initialize coin reconciliation on app startup
 * Add this to your MainActivity or Application class
 */
fun initializeCoinReconciliation(context: android.content.Context) {
    CoroutineScope(Dispatchers.IO).launch {
        try {
            val reconciliationManager = CoinReconciliationManager(context)

            val result = reconciliationManager.autoReconcile()

            when (result) {
                is AutoReconciliationResult.OK -> {
                    Log.d("GitaApp", "Coin balance verified: ${result.balance}")
                }
                is AutoReconciliationResult.Corrected -> {
                    Log.w("GitaApp", "Coin balance corrected: ${result.oldBalance} → ${result.newBalance}")
                }
                is AutoReconciliationResult.Skip -> {
                    Log.d("GitaApp", "Reconciliation skipped: ${result.reason}")
                }
                is AutoReconciliationResult.Error -> {
                    Log.e("GitaApp", "Reconciliation error: ${result.message}")
                }
            }
        } catch (e: Exception) {
            Log.e("GitaApp", "Failed to initialize reconciliation: ${e.message}")
        }
    }
}

