class FakePendingSyncEventDao : PendingSyncEventDao {
    private val list = mutableListOf<PendingSyncEvent>()

    override suspend fun insert(event: PendingSyncEvent) {
        list.add(event)
    }

    override suspend fun getPendingEvents(userId: String): List<PendingSyncEvent> {
        return list.filter { it.userId == userId }
    }

    override suspend fun delete(event: PendingSyncEvent) {
        list.remove(event)
    }

    override suspend fun deleteById(id: Int) {
        list.removeAll { it.id == id }
    }
}

@RunWith(RobolectricTestRunner::class)
@Config(sdk = [33])
class StatsStreakTest {
    @Test
    fun testStreakUpdates() = runBlocking {
        val dao = FakeUserStatsDao()
        val pendingDao = FakePendingSyncEventDao()
        val repo = StatsRepository(
            userStatsDao = dao,
            appContext = RuntimeEnvironment.getApplication(),
            pendingSyncEventDao = pendingDao
        )

        // First update sets streak to 1
        repo.trackModeTime(60, ModeType.NORMAL)
        var s = dao.stats!!
        assertEquals(1, s.currentStreak)
        assertEquals(1, s.longestStreak)

        // Same day again: streak unchanged
        repo.trackModeTime(30, ModeType.QUIZ)
        s = dao.stats!!
        assertEquals(1, s.currentStreak)

        // Simulate yesterday by setting lastActiveDate to yesterday
        val yesterday = java.time.LocalDate.now().minusDays(1).toString()
        dao.stats = s.copy(lastActiveDate = yesterday)

        // Next update increments streak
        repo.trackModeTime(15, ModeType.QUIZ)
        s = dao.stats!!
        assertEquals(2, s.currentStreak)
        assertEquals(2, s.longestStreak)
    }
}

package com.aipoweredgita.app

import org.junit.Test
import org.junit.Assert.*

/**
 * Example local unit tests
 * These tests verify core business logic without needing Android context
 */
class ExampleUnitTest {
    @Test
    fun addition_isCorrect() {
        assertEquals(4, 2 + 2)
    }

    @Test
    fun quizScoreCalculation() {
        // Test score calculation: correct answers only
        val correctAnswers = 8
        val totalQuestions = 10
        val score = (correctAnswers * 100) / totalQuestions
        assertEquals(80, score)
    }

    @Test
    fun difficultyAdjustment_increase() {
        // Difficulty increases when answer is correct
        var difficulty = 5
        difficulty = if (true) difficulty + 1 else difficulty - 1
        assertEquals(6, difficulty)
    }

    @Test
    fun difficultyAdjustment_decrease() {
        // Difficulty decreases when answer is wrong
        var difficulty = 5
        difficulty = if (false) difficulty + 1 else difficulty - 1
        assertEquals(4, difficulty)
    }

    @Test
    fun difficultyBounds_maximum() {
        // Difficulty should not exceed 10
        var difficulty = 9
        difficulty = if (true) difficulty + 1 else difficulty - 1
        difficulty = minOf(difficulty, 10)
        assertEquals(10, difficulty)
    }

    @Test
    fun difficultyBounds_minimum() {
        // Difficulty should not go below 1
        var difficulty = 2
        difficulty = if (false) difficulty + 1 else difficulty - 1
        difficulty = maxOf(difficulty, 1)
        assertEquals(1, difficulty)
    }

    @Test
    fun timeSpentCalculation() {
        // Calculate time spent (in seconds)
