@AndroidEntryPoint
class MainActivity : ComponentActivity() {

    // Notification permission launcher (Android 13+)
    private val notificationPermissionLauncher = registerForActivityResult(
        ActivityResultContracts.RequestPermission()
    ) { isGranted ->
        if (isGranted) {
            android.util.Log.d("MainActivity", "Notification permission granted")
        } else {
            android.util.Log.d("MainActivity", "Notification permission denied")
        }
    }

    @OptIn(ExperimentalMaterial3Api::class)
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()

        // Create notification channels
        createNotificationChannels()

        // Request notification permission for Android 13+ (API 33+)
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            notificationPermissionLauncher.launch(Manifest.permission.POST_NOTIFICATIONS)
        }

        // Initialize database and schedule workers on background thread (non-blocking)
        // This prevents ANR during app startup
        CoroutineScope(Dispatchers.Default).launch {
            try {
                // Initialize database and ensure UserStats record exists
                val database = GitaDatabase.getDatabase(applicationContext)
                database.userStatsDao().initializeStatsIfNeeded()

                // User sync to cloud happens lazily via ensureUserSynced() on first coin API call
                val stats = database.userStatsDao().getUserStatsOnce()
                if (stats != null) {
                    android.util.Log.d("MainActivity", "User ID: ${stats.userId}")
                }

                // Reconcile coin balance with server
                try {
                    val reconciliationManager = CoinReconciliationManager(applicationContext)
                    val result = reconciliationManager.autoReconcile()
                    when (result) {
                        is com.aipoweredgita.app.repository.AutoReconciliationResult.Corrected -> {
                            android.util.Log.w("MainActivity", "Coin balance corrected: ${result.oldBalance} → ${result.newBalance}")
                        }
                        is com.aipoweredgita.app.repository.AutoReconciliationResult.Error -> {
                            android.util.Log.e("MainActivity", "Reconciliation error: ${result.message}")
                        }
                        is com.aipoweredgita.app.repository.AutoReconciliationResult.Skip -> {
                            android.util.Log.d("MainActivity", "Reconciliation skipped: ${result.reason}")
                        }
                        is com.aipoweredgita.app.repository.AutoReconciliationResult.OK -> {
                            android.util.Log.d("MainActivity", "Balance OK")
                        }
                    }
                } catch (e: Exception) {
                    android.util.Log.e("MainActivity", "Reconciliation failed: ${e.message}")
                }

                // Check and apply yoga progression decay for inactivity
                val yogaProgressionRepository = com.aipoweredgita.app.repository.YogaProgressionRepository(database.yogaProgressionDao())
                val (didLevelDecrease, oldLevel, newLevel) = yogaProgressionRepository.checkAndApplyDecay()

                // Show notification if level decreased
                if (didLevelDecrease && oldLevel != null && newLevel != null) {
                    val lastDate = try {
                        val progression = yogaProgressionRepository.getProgression()
                        java.time.LocalDate.parse(progression.lastActivityDate)
                    } catch (e: Exception) {
                        java.time.LocalDate.now()
                    }
                    val daysInactive = java.time.temporal.ChronoUnit.DAYS.between(lastDate, java.time.LocalDate.now()).toInt()

                    com.aipoweredgita.app.notifications.YogaLevelUpNotificationManager.showLevelDecreaseNotification(
                        applicationContext,
                        oldLevel,
                        newLevel,
                        daysInactive
                    )
                }

                // Schedule daily verse notification worker (once; it survives app restarts)
                // Switch back to main thread for WorkManager
                CoroutineScope(Dispatchers.Main).launch {
                    scheduleDailyVerseWorker()

                    // Automatically schedule model downloads and question ingestion on first run
                    // Gemma 4 (Flagship only) download is disabled automatically per user request, wait for user instruction
                    // GemmaDownloadWorker.scheduleBackgroundDownload(applicationContext)
                    QwenDownloadWorker.scheduleBackgroundDownload(applicationContext, "Qwen3 0.6B")
                    QuestionIngestionWorker.schedule(applicationContext)
                    com.aipoweredgita.app.services.OfflineVerseDownloadWorker.scheduleBackgroundDownload(applicationContext)
                }
            } catch (e: Exception) {
                android.util.Log.e("MainActivity", "Error initializing database: ${e.message}", e)
            }
        }

        val themePreferences = ThemePreferences(applicationContext)

        setContent {
            var showSplash by remember { mutableStateOf(true) }
            var showExitDialog by remember { mutableStateOf(false) }

            // Collect theme preferences
            val themeMode by themePreferences.themeMode.collectAsStateWithLifecycle(initialValue = com.aipoweredgita.app.utils.ThemeMode.SYSTEM)
            val accent by themePreferences.accent.collectAsStateWithLifecycle(initialValue = "Sacred")
            val dynamicColor by themePreferences.isDynamicColor.collectAsStateWithLifecycle(initialValue = true)

            // Determine actual dark theme state
            val darkTheme = when (themeMode) {
                com.aipoweredgita.app.utils.ThemeMode.SYSTEM -> androidx.compose.foundation.isSystemInDarkTheme()
                com.aipoweredgita.app.utils.ThemeMode.LIGHT -> false
                com.aipoweredgita.app.utils.ThemeMode.DARK -> true
            }

            val scope = rememberCoroutineScope()

            LaunchedEffect(Unit) {
                // Initialize modelsReady based on actual download state to avoid flicker
                try {
                    val manager = ModelDownloadManager(applicationContext)
                    val ready = manager.areAllModelsDownloaded()
                    ModelStateManager.setModelsReady(ready)
                } catch (_: Exception) {
                    ModelStateManager.setModelsReady(false)
                }
            }

            GitaLearningTheme(
                darkTheme = darkTheme, 
                dynamicColor = dynamicColor, 
                accentName = accent
            ) {
                UiConfigProvider {
                // Global Coin Animation Overlay
                CoinOverlay()

                when {
                    showSplash -> {
                        SplashScreen(onSplashFinished = { showSplash = false })
                    }
                    showExitDialog -> {
                        ExitScreen(
                            onConfirmExit = { finish() },
                            onCancelExit = { showExitDialog = false }
                        )
                    }
                    else -> {
                        val launchRoute = intent.getStringExtra("NAVIGATE_TO")
                        val launchChapter = intent.getIntExtra("CHAPTER", 0)
                        val launchVerse = intent.getIntExtra("VERSE", 0)
                        MainContent(
                            onRequestExit = { showExitDialog = true },
                            isDarkTheme = darkTheme,
                            onThemeToggle = { isDark ->
                                scope.launch {
                                    themePreferences.setThemeMode(
                                        if (isDark) com.aipoweredgita.app.utils.ThemeMode.DARK 
                                        else com.aipoweredgita.app.utils.ThemeMode.LIGHT
                                    )
                                }
                            },
                            launchRoute = launchRoute,
                            launchChapter = launchChapter,
                            launchVerse = launchVerse
                        )
                    }
                }
                }
            }
        }
    }

    @OptIn(ExperimentalMaterial3Api::class)
    @Composable
    fun MainContent(
        onRequestExit: () -> Unit,
        isDarkTheme: Boolean,
        onThemeToggle: (Boolean) -> Unit,

        launchRoute: String? = null,
        launchChapter: Int = 0,
        launchVerse: Int = 0
    ) {
        val navController = rememberNavController()

        // Handle deep linking
        LaunchedEffect(launchRoute) {
            if (launchRoute == "random_sloka") {
                if (launchChapter > 0 && launchVerse > 0) {
                    navController.navigate("random_sloka?chapter=$launchChapter&verse=$launchVerse")
                } else {
                    navController.navigate(Screen.RandomSloka.route)
                }
            }
        }

        val navBackStackEntry by navController.currentBackStackEntryAsState()
        val currentRoute = navBackStackEntry?.destination?.route

        // Handle back button on home screen
        BackHandler(enabled = currentRoute == Screen.Home.route) {
            onRequestExit()
        }

        MainScreen(
            navController = navController,
            isDarkTheme = isDarkTheme,
            onThemeToggle = onThemeToggle
        )
    }
}

private fun ComponentActivity.scheduleDailyVerseWorker() {
    val work = PeriodicWorkRequestBuilder<
        com.aipoweredgita.app.notifications.DailyVerseWorker
    >(24, TimeUnit.HOURS)
        .build()
    WorkManager.getInstance(this).enqueueUniquePeriodicWork(
        "daily_verse",
        ExistingPeriodicWorkPolicy.KEEP,
        work
    )

    // Also schedule daily reflection prompt
    val reflection = PeriodicWorkRequestBuilder<DailyReflectionWorker>(24, TimeUnit.HOURS).build()
    WorkManager.getInstance(this).enqueueUniquePeriodicWork(
        "daily_reflection_work",
        ExistingPeriodicWorkPolicy.KEEP,
        reflection
    )
}

