import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map

private val Context.quizDataStore: DataStore<Preferences> by preferencesDataStore(name = "quiz_preferences")

class QuizPreferences(private val context: Context) {

    companion object {
        private val QUIZ_SCORE_KEY = intPreferencesKey("quiz_score")
        private val QUIZ_TOTAL_QUESTIONS_KEY = intPreferencesKey("quiz_total_questions")
        private val QUIZ_MAX_QUESTIONS_KEY = intPreferencesKey("quiz_max_questions")
        private val QUIZ_START_TIME_KEY = longPreferencesKey("quiz_start_time")
        private val USED_QUESTIONS_KEY = stringPreferencesKey("used_questions")
    }

    val quizState: Flow<SavedQuizState?> = context.quizDataStore.data
        .map { preferences ->
            val totalQuestions = preferences[QUIZ_TOTAL_QUESTIONS_KEY] ?: 0
            if (totalQuestions > 0) {
                SavedQuizState(
                    score = preferences[QUIZ_SCORE_KEY] ?: 0,
                    totalQuestions = totalQuestions,
                    maxQuestions = preferences[QUIZ_MAX_QUESTIONS_KEY] ?: 10,
                    startTime = preferences[QUIZ_START_TIME_KEY] ?: 0L,
                    usedQuestions = preferences[USED_QUESTIONS_KEY]?.split(",")?.toSet() ?: emptySet()
                )
            } else {
                null
            }
        }

    suspend fun saveQuizState(
        score: Int,
        totalQuestions: Int,
        maxQuestions: Int,
        startTime: Long,
        usedQuestions: Set<String>
    ) {
        context.quizDataStore.edit { preferences ->
            preferences[QUIZ_SCORE_KEY] = score
            preferences[QUIZ_TOTAL_QUESTIONS_KEY] = totalQuestions
            preferences[QUIZ_MAX_QUESTIONS_KEY] = maxQuestions
            preferences[QUIZ_START_TIME_KEY] = startTime
            preferences[USED_QUESTIONS_KEY] = usedQuestions.joinToString(",")
        }
    }

    suspend fun clearQuizState() {
        context.quizDataStore.edit { preferences ->
            preferences.remove(QUIZ_SCORE_KEY)
            preferences.remove(QUIZ_TOTAL_QUESTIONS_KEY)
            preferences.remove(QUIZ_MAX_QUESTIONS_KEY)
            preferences.remove(QUIZ_START_TIME_KEY)
            preferences.remove(USED_QUESTIONS_KEY)
        }
    }
}

data class SavedQuizState(
    val score: Int,
    val totalQuestions: Int,
    val maxQuestions: Int,
    val startTime: Long,
    val usedQuestions: Set<String>
)

package com.aipoweredgita.app.utils

import android.app.ActivityManager
import android.content.Context
import android.os.Build
import android.util.Log

enum class DeviceTier(val label: String) {
    FLAGSHIP("Flagship"),
    HIGH_MID("High-Mid"),
    MID("Mid"),
    LOW_MID("Low-Mid"),
    LOW("Low")
}

/**
 * Device tier detector using four independent axes:
 *
 *  **CPU**    — core count, peak frequency, ARM ISA version, cluster topology
 *  **GPU**    — Vulkan API level, OpenCL availability
 *  **RAM**    — total memory capacity
 *  **AnTuTu** — v10 benchmark (SoC name lookup or HW-based estimation)
 *
 *  No blocking micro-benchmarks or GL context creation.
 *  Every signal is available synchronously without blocking the calling thread.
 */
object DeviceTierDetector {

    private const val TAG = "DeviceTier"
    @Volatile private var cached: DeviceTier? = null

    fun invalidate() { cached = null }

    /**
     * Synchronous detection. Safe to call on any thread — no blocking I/O or
     * micro-benchmarks. Returns a cached result on subsequent calls.
     */
    fun detect(context: Context): DeviceTier {
        cached?.let { return it }
        val signals = collectSignals(context)
        return classify(signals).also { cached = it }
    }

    // ─── signal types ───────────────────────────────────────────────

    data class CpuSignals(
        val coreCount: Int,
        val bigCoreFreq: Int,    // MHz
        val armVersion: Int,     // 8 or 9
        val clusterCount: Int    // 1, 2, or 3
    )

    data class GpuSignals(
        val vulkanTier: Int,   // 0–4
        val hasOpenCL: Boolean
    )

    data class HardwareSignals(
        val ramGb: Float,
        val cpu: CpuSignals,
        val gpu: GpuSignals,
        val antutuScore: Int     // AnTuTu v10 benchmark score (0–2_000_000+)
    )

    // ─── collection ─────────────────────────────────────────────────

    private fun collectSignals(context: Context): HardwareSignals {
        val ram = totalRamGb(context)
        val cpu = collectCpuSignals()
        val gpu = collectGpuSignals(context)
        return HardwareSignals(
            ramGb = ram,
            cpu   = cpu,
            gpu   = gpu,
            antutuScore = resolveAntutuScore(cpu, gpu, ram)
        )
    }

    // ─── RAM ────────────────────────────────────────────────────────

    private fun totalRamGb(context: Context): Float {
        val mi = ActivityManager.MemoryInfo()
        (context.getSystemService(Context.ACTIVITY_SERVICE) as ActivityManager)
            .getMemoryInfo(mi)
        return mi.totalMem / 1_073_741_824f
    }

    // ─── CPU axis ───────────────────────────────────────────────────

    private fun collectCpuSignals(): CpuSignals {
        val freqs = allCoreFreqsMhz()
        val cores = Runtime.getRuntime().availableProcessors()
        return CpuSignals(
            coreCount    = cores,
            bigCoreFreq  = freqs.maxOrNull() ?: 0,
            armVersion   = armVersion(),
            clusterCount = detectClusterCount(freqs)
        )
    }

    private fun allCoreFreqsMhz(): List<Int> =
        java.io.File("/sys/devices/system/cpu")
            .listFiles { f -> f.name.matches(Regex("cpu\\d+")) }
            ?.mapNotNull { core ->
                runCatching {
                    java.io.File("${core.path}/cpufreq/cpuinfo_max_freq")
                        .readText().trim().toLong() / 1000
                }.getOrNull()?.toInt()
            }
            ?.sorted()
            ?: emptyList()

    private fun detectClusterCount(freqs: List<Int>): Int {
        val distinct = freqs.toSortedSet()
        if (distinct.size <= 1) return 1
        var clusters = 1
        var prev = distinct.first()
        for (f in distinct.drop(1)) {
            if (f - prev > 300) clusters++
            prev = f
        }
        return clusters
    }

    private fun armVersion(): Int = runCatching {
        val info = java.io.File("/proc/cpuinfo").readText()
        if (info.contains("ARMv9", ignoreCase = true) ||
            info.contains("Cortex-X4", ignoreCase = true) ||
            info.contains("Cortex-X3", ignoreCase = true) ||
            info.contains("Cortex-A720", ignoreCase = true) ||
            info.contains("Cortex-A520", ignoreCase = true) ||
            Build.VERSION.SDK_INT >= 34) 9 else 8
    }.getOrDefault(8)

    // ─── GPU axis ───────────────────────────────────────────────────

    private fun collectGpuSignals(context: Context) = GpuSignals(
        vulkanTier = vulkanTier(context),
        hasOpenCL  = openCLAvailable()
    )

    /**
     * Vulkan version is the best single GPU generation proxy available
     * without requiring an EGL/GL context:
     *   1.3 → Adreno 7xx / Immortalis-G925  (flagship)
     *   1.2 → Adreno 6xx / Mali-G710+       (high-mid)
     *   1.1 → Adreno 5xx / Mali-G57+         (mid)
     *   1.0 → older GPUs                     (low-mid)
     *   0   → no Vulkan                      (budget)
     */
    private fun vulkanTier(context: Context): Int {
        if (Build.VERSION.SDK_INT < 24) return 0
        val pm = context.packageManager
        return when {
            pm.hasSystemFeature("android.hardware.vulkan.version", 0x403000) -> 4  // 1.3
            pm.hasSystemFeature("android.hardware.vulkan.version", 0x402000) -> 3  // 1.2
            pm.hasSystemFeature("android.hardware.vulkan.version", 0x401000) -> 2  // 1.1
            pm.hasSystemFeature("android.hardware.vulkan.level",   1)        -> 1  // 1.0
            pm.hasSystemFeature("android.hardware.vulkan.compute")           -> 1
            else -> 0
        }
    }

    /** OpenCL availability — critical for LiteRT GPU delegate on many SoCs. */
    private fun openCLAvailable(): Boolean = try {
        java.io.File("/system/lib64/libOpenCL.so").exists() ||
        java.io.File("/vendor/lib64/libOpenCL.so").exists() ||
        java.io.File("/system/lib/libOpenCL.so").exists() ||
        java.io.File("/vendor/lib/libOpenCL.so").exists()
    } catch (_: Exception) { false }

    // ─── AnTuTu v10 score ──────────────────────────────────────────

    /**
     * Resolves AnTuTu v10 score in two ways:
     *  1. SoC name lookup (Build.SOC_MODEL on API 31+ or sysfs fallback)
     *  2. CPU/GPU characteristic estimation if SoC is unknown
     *
     * Every device gets a score — no device left at zero unless truly entry-level.
     */
    private fun resolveAntutuScore(cpu: CpuSignals, gpu: GpuSignals, ramGb: Float): Int {
        val soc = detectSocName()
        if (soc != null) {
            // Exact match first
            ANTUTU_DATABASE[soc]?.let { return it }
            // Then partial match (e.g. "Snapdragon 7+ Gen 3" matches "Snapdragon 7+ Gen 3")
            ANTUTU_DATABASE.entries.firstOrNull { (key) ->
                soc.contains(key, ignoreCase = true)
            }?.let { return it.value }
        }
        return estimateScore(cpu, gpu, ramGb)
    }

    /** Detect SoC model name from system properties or sysfs. */
    private fun detectSocName(): String? {
        if (Build.VERSION.SDK_INT >= 31) {
            @Suppress("InlinedApi")
            val soc = Build.SOC_MODEL
            if (!soc.isNullOrBlank()) return soc.trim()
        }
        return readSocFromSys()
    }

    /** Read SoC identifier from sysfs (common on Qualcomm, MediaTek, Exynos). */
    private fun readSocFromSys(): String? {
        val paths = listOf(
            "/sys/devices/soc0/machine",
            "/sys/devices/soc0/family",
            "/sys/devices/system/soc/soc0/machine"
        )
        for (path in paths) {
            try {
                val name = java.io.File(path).readText().trim()
                if (name.isNotBlank()) return name
            } catch (_: Exception) { /* try next path */ }
        }
        return null
    }

    /**
     * Estimate AnTuTu v10 score from CPU/GPU capability when SoC is unknown.
     * Used for devices not in the lookup database or running on older Android.
     */
    private fun estimateScore(cpu: CpuSignals, gpu: GpuSignals, ramGb: Float): Int {
        var score = 0
        // ARM v9 ISA → modern cores (Cortex-X4/A720/A520)
        score += if (cpu.armVersion >= 9) 250_000 else 100_000
        // Peak CPU frequency → higher = faster single-thread
        score += (cpu.bigCoreFreq * 200).coerceAtMost(400_000)
        // Core count → more = better multi-thread
        score += (cpu.coreCount * 50_000).coerceAtMost(400_000)
        // Cluster topology → 3 clusters = prime+mid+LITTLE
        score += when (cpu.clusterCount) {
            3    -> 200_000
            2    -> 100_000
            else -> 0
        }
        // GPU capability
        score += when (gpu.vulkanTier) {
            4    -> 300_000  // Vulkan 1.3 = modern GPU
            3    -> 200_000  // Vulkan 1.2 = capable
            2    -> 100_000  // Vulkan 1.1 = moderate
            else -> 50_000
        }
        if (gpu.hasOpenCL) score += 100_000
        // RAM capacity proxy
        score += (ramGb * 30_000).toInt()
        // Clamp to realistic range
        return score.coerceIn(0, 2_000_000)
    }

    /**
     * AnTuTu v10 estimated scores for common mobile SoCs.
     * Keys match Build.SOC_MODEL output (API 31+) and common sysfs identifiers.
     * Values are realistic average AnTuTu v10 scores.
     */
    private val ANTUTU_DATABASE = mapOf(
            // ── Qualcomm Snapdragon 8-series (flagship) ──────────────
            "Snapdragon 8 Elite"            to 2_200_000,
            "Snapdragon 8 Gen 3"            to 1_900_000,
            "Snapdragon 8 Gen 2"            to 1_550_000,
            "Snapdragon 8+ Gen 1"           to 1_350_000,
            "Snapdragon 8 Gen 1"            to 1_050_000,
            "Snapdragon 888"                to   800_000,
            "Snapdragon 870"                to   700_000,
            "Snapdragon 865"                to   640_000,
            "Snapdragon 855"                to   540_000,
            "Snapdragon 845"                to   380_000,
            "Snapdragon 835"                to   240_000,

            // ── Qualcomm Snapdragon 7-series (upper-mid) ────────────
            "Snapdragon 7+ Gen 3"           to 1_150_000,  // OnePlus Nord 4
            "Snapdragon 7 Gen 3"            to   780_000,
            "Snapdragon 7+ Gen 2"           to 1_050_000,
            "Snapdragon 7 Gen 1"            to   650_000,
            "Snapdragon 778G"               to   560_000,
            "Snapdragon 782G"               to   600_000,
            "Snapdragon 7s Gen 2"           to   610_000,

            // ── Qualcomm Snapdragon 6-series (mid) ──────────────────
            "Snapdragon 6 Gen 1"            to   520_000,
            "Snapdragon 695"                to   410_000,
            "Snapdragon 680"                to   340_000,
            "Snapdragon 678"                to   330_000,
            "Snapdragon 675"                to   310_000,
            "Snapdragon 665"                to   280_000,

            // ── MediaTek Dimensity ───────────────────────────────────
            "Dimensity 9400"                to 2_400_000,
            "Dimensity 9300"                to 1_950_000,
            "Dimensity 9200"                to 1_250_000,
            "Dimensity 8300"                to 1_350_000,
            "Dimensity 8200"                to   900_000,
            "Dimensity 8100"                to   850_000,
            "Dimensity 8050"                to   750_000,
            "Dimensity 7300"                to   620_000,
            "Dimensity 7200"                to   600_000,
            "Dimensity 7000"                to   500_000,
            "Dimensity 1080"                to   550_000,
            "Dimensity 900"                 to   500_000,
            "Dimensity 810"                 to   420_000,
            "Dimensity 700"                 to   320_000,

            // ── MediaTek Helio ───────────────────────────────────────
            "Helio G99"                     to   410_000,
            "Helio G96"                     to   380_000,
            "Helio G95"                     to   370_000,
            "Helio G88"                     to   280_000,
            "Helio G85"                     to   270_000,
            "Helio G80"                     to   260_000,
            "Helio G70"                     to   250_000,
            "Helio P65"                     to   200_000,

            // ── Samsung Exynos ───────────────────────────────────────
            "Exynos 2400"                   to 1_720_000,
            "Exynos 2200"                   to 1_020_000,
            "Exynos 2100"                   to   780_000,
            "Exynos 1480"                   to   650_000,
            "Exynos 1380"                   to   550_000,
            "Exynos 1280"                   to   450_000,
            "Exynos 990"                    to   520_000,
            "Exynos 9820"                   to   450_000,
            "Exynos 9611"                   to   280_000,
            "Exynos 850"                    to   200_000,

            // ── Google Tensor ────────────────────────────────────────
            "Tensor G4"                     to 1_600_000,
            "Tensor G3"                     to 1_450_000,
            "Tensor G2"                     to 1_050_000,
            "Tensor"                        to   800_000,

            // ── Huawei Kirin ─────────────────────────────────────────
            "Kirin 9000"                    to   750_000,
            "Kirin 990"                     to   480_000,
            "Kirin 810"                     to   330_000,

            // ── UNISOC ───────────────────────────────────────────────
            "T760"                          to   420_000,
            "T616"                          to   260_000,
            "T612"                          to   240_000,
            "T610"                          to   230_000,
            "T606"                          to   220_000
        )

    // ─── classification ─────────────────────────────────────────────

    /**
     * Four-axis scoring:
     *
     *  **CPU** (max 10):    core count (0-2) + peak freq (0-3) + ARM ISA (0-2) + clusters (0-3)
     *  **GPU** (max 6):     vulkan tier (0-4) + OpenCL (0-2)
     *  **RAM** (max 3):     capacity gate for on-device LLM
     *  **AnTuTu** (max 5):  v10 benchmark — lookup or HW-estimated score
     *
     *  Total max = 24.
     */
    private fun classify(s: HardwareSignals): DeviceTier {
        // ── CPU score ──────────────────────────────────────────────
        val corePts = when {
            s.cpu.coreCount >= 8 -> 2
            s.cpu.coreCount >= 6 -> 1
            else                 -> 0
        }
        val freqPts = when {
            s.cpu.bigCoreFreq >= 3000 -> 3
            s.cpu.bigCoreFreq >= 2500 -> 2
            s.cpu.bigCoreFreq >= 2000 -> 1
            else                      -> 0
        }
        val armPts     = if (s.cpu.armVersion >= 9) 2 else 0
        val clusterPts = when (s.cpu.clusterCount) {
            3    -> 3   // tri-cluster = flagship CPU topology
            2    -> 1   // big.LITTLE = mainstream
            else -> 0
        }
        val cpuScore = corePts + freqPts + armPts + clusterPts

        // ── GPU score ──────────────────────────────────────────────
        val gpuScore = s.gpu.vulkanTier + (if (s.gpu.hasOpenCL) 2 else 0)

        // ── RAM score ──────────────────────────────────────────────
        val ramPts = when {
            s.ramGb >= 11.5f -> 3   // 12 GB+
            s.ramGb >=  7.5f -> 2   // 8 GB
            s.ramGb >=  5.5f -> 1   // 6 GB
            else             -> 0
        }

        // ── AnTuTu score ───────────────────────────────────────────
        val antutuPts = when {
            s.antutuScore >= 1_500_000 -> 5   // true flagship (8 Gen 3, D9300+)
            s.antutuScore >= 1_000_000 -> 4   // upper-mid flagship (7+ Gen 3, D8300)
            s.antutuScore >=   600_000 -> 3   // solid mid-range
            s.antutuScore >=   350_000 -> 2   // lower-mid
            s.antutuScore >=   200_000 -> 1   // entry
            else                       -> 0
        }

        val total = cpuScore + gpuScore + ramPts + antutuPts

        Log.d(TAG, buildString {
            append("cores=${s.cpu.coreCount} freq=${s.cpu.bigCoreFreq}MHz ")
            append("ARMv${s.cpu.armVersion} clusters=${s.cpu.clusterCount} ")
            append("vulkan=${s.gpu.vulkanTier} openCL=${s.gpu.hasOpenCL} ")
            append("ram=%.1fGB ".format(s.ramGb))
            append("antutu=${s.antutuScore} ")
            append("→ CPU=$cpuScore GPU=$gpuScore RAM=$ramPts NTU=$antutuPts total=$total/24")
        })

        return when {
            total >= 19 -> DeviceTier.FLAGSHIP
            total >= 14 -> DeviceTier.HIGH_MID
            total >=  9 -> DeviceTier.MID
            total >=  5 -> DeviceTier.LOW_MID
            else        -> DeviceTier.LOW
        }
    }
}

package com.aipoweredgita.app.utils

import android.content.Context
import android.content.SharedPreferences
import androidx.security.crypto.EncryptedSharedPreferences
import androidx.security.crypto.MasterKey

/**
 * Manages authentication state and credential storage.
 * Thread-safe: coin mutations use commit() + synchronized to prevent race conditions.
 * Security: password and token are stored in EncryptedSharedPreferences.
 */
class AuthPreferences(context: Context) {

    private val prefs: SharedPreferences = context.getSharedPreferences(
        "auth_prefs",
        Context.MODE_PRIVATE
    )

    /** Encrypted prefs for sensitive data (password, auth token). */
    private val securePrefs: SharedPreferences by lazy {
        val masterKey = MasterKey.Builder(context.applicationContext)
            .setKeyScheme(MasterKey.KeyScheme.AES256_GCM)
            .build()
        EncryptedSharedPreferences.create(
            context.applicationContext,
            "auth_secure_prefs",
            masterKey,
            EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
            EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
        )
    }

    companion object {
        private const val KEY_USER_ID = "user_id"
        private const val KEY_IS_LOGGED_IN = "is_logged_in"
        private const val KEY_IS_GUEST = "is_guest"
        private const val KEY_GUEST_ID = "guest_id"
        private const val KEY_LOGIN_METHOD = "login_method"
        private const val KEY_PHONE = "phone"
        private const val KEY_EMAIL = "email"
        private const val KEY_NAME = "name"
        private const val KEY_PASSWORD = "password"
        private const val KEY_REMEMBER_ME = "remember_me"
        private const val KEY_LAST_LOGIN = "last_login"
        private const val KEY_TOKEN = "auth_token"

        @Volatile
        private var INSTANCE: AuthPreferences? = null

        fun getInstance(context: Context): AuthPreferences {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: AuthPreferences(context.applicationContext).also { INSTANCE = it }
            }
        }
    }

    // ── User State ─────────────────────────────────────────────────────

    var userId: String?
        get() = prefs.getString(KEY_USER_ID, null)
        set(value) = prefs.edit().putString(KEY_USER_ID, value).apply()

    var isLoggedIn: Boolean
        get() = prefs.getBoolean(KEY_IS_LOGGED_IN, false)
        set(value) = prefs.edit().putBoolean(KEY_IS_LOGGED_IN, value).apply()

    var isGuest: Boolean
        get() = prefs.getBoolean(KEY_IS_GUEST, false)
        set(value) = prefs.edit().putBoolean(KEY_IS_GUEST, value).apply()

    var guestId: String?
        get() = prefs.getString(KEY_GUEST_ID, null)
        set(value) = prefs.edit().putString(KEY_GUEST_ID, value).apply()

    // ── Credentials ────────────────────────────────────────────────────

    var loginMethod: String?
        get() = prefs.getString(KEY_LOGIN_METHOD, null) // "phone" or "email"
        set(value) = prefs.edit().putString(KEY_LOGIN_METHOD, value).apply()

    var phone: String?
        get() = prefs.getString(KEY_PHONE, null)
        set(value) = prefs.edit().putString(KEY_PHONE, value).apply()

    var email: String?
        get() = prefs.getString(KEY_EMAIL, null)
        set(value) = prefs.edit().putString(KEY_EMAIL, value).apply()

    var name: String?
        get() = prefs.getString(KEY_NAME, null)
        set(value) = prefs.edit().putString(KEY_NAME, value).apply()

    /** Password stored in EncryptedSharedPreferences (not plaintext). */
    var savedPassword: String?
        get() = securePrefs.getString(KEY_PASSWORD, null)
        set(value) = securePrefs.edit().putString(KEY_PASSWORD, value).apply()

    var rememberMe: Boolean
        get() = prefs.getBoolean(KEY_REMEMBER_ME, true)
        set(value) = prefs.edit().putBoolean(KEY_REMEMBER_ME, value).apply()

    var lastLogin: Long
        get() = prefs.getLong(KEY_LAST_LOGIN, 0)
        set(value) = prefs.edit().putLong(KEY_LAST_LOGIN, value).apply()

    /** Auth token stored in EncryptedSharedPreferences (not plaintext). */
    var token: String?
        get() = securePrefs.getString(KEY_TOKEN, null)
        set(value) = securePrefs.edit().putString(KEY_TOKEN, value).apply()

    // ── Guest Local Coins ──────────────────────────────────────────────
    // Guests earn coins locally since /guest/create is broken on server

    var guestWelcomeAwarded: Boolean
        get() = prefs.getBoolean("guest_welcome_awarded", false)
        set(value) = prefs.edit().putBoolean("guest_welcome_awarded", value).apply()

    /** Convenience: true if this is a guest user or not logged in. */
    val isGuestUser: Boolean get() = !isLoggedIn || isGuest

    // ── Helper Methods ─────────────────────────────────────────────────

    /**
     * Save login state after successful authentication.
     * Passwords and tokens are stored in EncryptedSharedPreferences.
     */
    fun saveLoginState(
        userId: String,
        name: String = "",
        loginMethod: String,
        token: String? = null,
        phone: String? = null,
        email: String? = null,
        password: String? = null
    ) {
        // Use commit() (synchronous) so that isLoggedIn, userId, and token are immediately
        // readable after login — async apply() can cause stale reads in the UI right after login
        prefs.edit().apply {
            putString(KEY_USER_ID, userId)
            putBoolean(KEY_IS_LOGGED_IN, true)
            putBoolean(KEY_IS_GUEST, false)
            putString(KEY_LOGIN_METHOD, loginMethod)
            putString(KEY_NAME, name)
            phone?.let { putString(KEY_PHONE, it) }
            email?.let { putString(KEY_EMAIL, it) }
            putLong(KEY_LAST_LOGIN, System.currentTimeMillis())
            remove("guest_welcome_awarded") // Reset guest flag
            commit() // synchronous — ensures values are written before onLoginSuccess navigates
        }
        // Store sensitive data in encrypted prefs — also synchronous
        securePrefs.edit().apply {
            token?.let { putString(KEY_TOKEN, it) }
            password?.let { putString(KEY_PASSWORD, it) }
            commit() // synchronous — token must be readable immediately after login
        }
    }

    /**
     * Save guest state
     */
    fun saveGuestState(guestId: String) {
        prefs.edit().apply {
            putString(KEY_GUEST_ID, guestId)
            putBoolean(KEY_IS_LOGGED_IN, true)
            putBoolean(KEY_IS_GUEST, true)
            putString(KEY_USER_ID, guestId)
            putString(KEY_LOGIN_METHOD, "guest")
            putLong(KEY_LAST_LOGIN, System.currentTimeMillis())
            apply()
        }
    }

    /**
     * Get saved credentials for auto-fill
     */
    fun getSavedCredentials(): Triple<String?, String?, String?> {
        return when (loginMethod) {
            "phone" -> Triple(phone, null, savedPassword)
            "email" -> Triple(email, null, savedPassword)
            else -> Triple(null, null, savedPassword)
        }
    }

    /**
     * Check if user has a previous guest session
     */
    fun hasGuestSession(): Boolean {
        return guestId != null && isGuest
    }

    /**
     * Clear login state (logout)
     * Credentials (email/phone/name) are always preserved for quick re-login.
     * Token and password are cleared from encrypted storage.
     */
    fun clearLoginState() {
        prefs.edit().apply {
            remove(KEY_USER_ID)
            remove(KEY_IS_LOGGED_IN)
            remove(KEY_IS_GUEST)
            remove(KEY_GUEST_ID)
            remove(KEY_LOGIN_METHOD)
            remove(KEY_LAST_LOGIN)
            // Reset guest welcome flag on logout to start fresh
            remove("guest_welcome_awarded")
            // Always preserve email/phone/name for quick re-login
            apply()
        }
        // Clear sensitive data from encrypted storage
        securePrefs.edit().clear().apply()
    }

    /**
     * Clear all data including credentials
     */
    fun clearAll() {
        prefs.edit().clear().apply()
        securePrefs.edit().clear().apply()
    }
}

package com.aipoweredgita.app.recommendation

import android.content.Context
import android.util.Log
import com.aipoweredgita.app.database.GitaDatabase
import com.aipoweredgita.app.database.RecommendationData
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

class RecommendationEngine(private val context: Context) {
    private val TAG = "RecommendationEngine"

    suspend fun generateRecommendations() = withContext(Dispatchers.IO) {
        try {
            val db = GitaDatabase.getDatabase(context)
            val stats = db.userStatsDao().getUserStatsOnce()
            val prefs = db.userPreferencesDao().getPreferencesSync(1)

            // Basic heuristics from question performance
            val weakTopics = mutableListOf<String>()
            val perfDao = db.questionPerformanceDao()

            // Collect a few weak areas by topic (requires app to have logged performance)
            listOf("karma", "bhakti", "gyana", "dharma", "yoga").forEach { topic ->
                val items = try { perfDao.getWeakTopics(topic) } catch (_: Exception) { null }
                // Flow is not available off main; skip here; rely on saved insights later
                if (items == null) {
                    // Seed topics by preference or generic
                    if (prefs?.showOnlyWeakAreas == true) weakTopics.add(topic)
                }
            }

            val recDao = db.recommendationDataDao()

            // Recommend practice session in preferred study mode
            recDao.insert(
                RecommendationData(
                    recommendationType = "study_mode",
                    recommendationId = prefs?.preferredStudyMode ?: "quiz",
                    recommendationTitle = "Continue in ${prefs?.preferredStudyMode ?: "Quiz"} Mode",
                    priority = 8,
                    confidenceScore = 80f,
                    relevanceScore = 85f,
                    reason = "Matches your preferred study mode and recent activity",
                    baseReason = "preference",
                    expectedBenefit = 70f,
                    urgencyLevel = "medium"
                )
            )

            // Recommend chapter or verses based on favorites or recent reads
            val recentChapter = (stats?.chaptersCompleted ?: 0).coerceAtLeast(1)
            recDao.insert(
                RecommendationData(
                    recommendationType = "chapter",
                    recommendationId = recentChapter.toString(),
                    recommendationTitle = "Review Chapter $recentChapter",
                    priority = 7,
                    confidenceScore = 60f,
                    relevanceScore = 75f,
                    reason = "Spaced repetition to strengthen memory",
                    baseReason = "review",
                    expectedBenefit = 65f,
                    urgencyLevel = "low"
                )
            )

            // Recommend yoga level focus based on Yoga level
            val yogaLevelInfo = com.aipoweredgita.app.ui.components.YogaLevelManager.yogaLevelInfo(stats)
            recDao.insert(
                RecommendationData(
                    recommendationType = "yogalevel",
                    recommendationId = yogaLevelInfo.level.toString(),
                    recommendationTitle = "Focus on Yoga Level ${yogaLevelInfo.level}",
                    priority = 9,
                    confidenceScore = 75f,
                    relevanceScore = 80f,
                    reason = "Progress towards next yoga level",
                    baseReason = "progression",
                    expectedBenefit = 80f,
                    urgencyLevel = "high"
                )
            )

            // Weak topics recommendations (seeded)
            weakTopics.take(3).forEach { topic ->
                recDao.insert(
                    RecommendationData(
                        recommendationType = "topic",
                        recommendationId = topic,
                        recommendationTitle = "Strengthen $topic",
                        priority = 6,
                        confidenceScore = 55f,
                        relevanceScore = 70f,
                        reason = "Improve success rate in $topic",
                        baseReason = "weak_area",
                        expectedBenefit = 60f,
                        urgencyLevel = "medium"
                    )
                )
            }

            Log.d(TAG, "Recommendations generated")
        } catch (e: Exception) {
            Log.e(TAG, "Error generating recommendations: ${e.message}")
        }
    }
}

package com.aipoweredgita.app.recommendation

import com.aipoweredgita.app.database.GitaDatabase
import com.aipoweredgita.app.database.DailyActivity
import java.time.LocalDate
import java.time.format.DateTimeFormatter
import java.util.Calendar
import java.util.Locale

data class NextSuggestion(
    val nextStep: String, // "Read", "Studio", or "Quiz"
    val nextLevel: Int,   // 1..10 difficulty suggestion
    val reason: String
)

suspend fun predictNext(db: GitaDatabase): NextSuggestion {
    val dateFormatter = DateTimeFormatter.ISO_LOCAL_DATE
    val today = LocalDate.now().format(dateFormatter)
    val dailyDao = db.dailyActivityDao()

    // Gather last 7 days activity
    val cal = Calendar.getInstance()
    val last7 = mutableListOf<DailyActivity?>()
    repeat(7) {
        val d = LocalDate.now().minusDays(it.toLong()).format(dateFormatter)
        val row = try { dailyDao.getByDate(d) } catch (_: Exception) { null }
        last7.add(row)
    }

    val totals = last7.map { r ->
        Triple(r?.normalSeconds ?: 0L, r?.quizSeconds ?: 0L, r?.voiceStudioTimeSeconds ?: 0L)
    }
    val totalNormal = totals.sumOf { it.first }
    val totalQuiz = totals.sumOf { it.second }
    val totalStudio = totals.sumOf { it.third }

    // Choose next step: prioritize the least-engaged mode to balance learning
    val minMode = listOf(
        "Read" to totalNormal,
        "Quiz" to totalQuiz,
        "Studio" to totalStudio
    ).minByOrNull { it.second }?.first ?: "Read"

    // Use the actual streak from user_stats instead of recalculating from daily_activity
    val streak = try {
        db.userStatsDao().getUserStatsOnce()?.currentStreak ?: 0
    } catch (_: Exception) { 0 }

    // Difficulty heuristic based on streak and recent activity
    val recentActivity = totals.take(3).sumOf { it.first + it.second + it.third }
    val level = when {
        streak >= 10 || recentActivity >= 3600L -> 8
        streak >= 5 || recentActivity >= 1800L -> 6
        streak >= 2 || recentActivity >= 600L -> 4
        else -> 3
    }

    val readMin = (totalNormal / 60)
    val quizMin = (totalQuiz / 60)
    val studioMin = (totalStudio / 60)
    val reason = "Balancing modes: Read ${readMin}m, Quiz ${quizMin}m, Studio ${studioMin}m. Streak: ${streak} day" + if (streak == 1) "" else "s"
    return NextSuggestion(nextStep = minMode, nextLevel = level, reason = reason)
}

package com.aipoweredgita.app.recommendation

import com.aipoweredgita.app.database.UserStats

data class YogaAdvice(
    val currentLevel: Int,
    val nextFocusLevels: List<Int>,
    val tips: List<String>
)

object YogaAdvisor {
    fun suggest(stats: UserStats?): YogaAdvice {
        val level = com.aipoweredgita.app.ui.components.YogaLevelManager.levelFor(stats)
        val next = listOf((level + 1).coerceAtMost(5), level) // keep current and next
        val tips = listOf(
            "Practice detachment (Vairagya) while performing duties",
            "Deepen Bhakti through daily devotion and gratitude",
            "Balance action (Karma Yoga) with meditation (Dhyana)"
        )
        return YogaAdvice(currentLevel = level, nextFocusLevels = next.distinct(), tips = tips)
    }
}

package com.aipoweredgita.app.notifications

import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.os.Build
import androidx.core.app.NotificationCompat
import androidx.core.app.NotificationManagerCompat
import androidx.work.CoroutineWorker
import androidx.work.WorkerParameters
import com.aipoweredgita.app.R
import com.aipoweredgita.app.database.GitaDatabase

class DailyReflectionWorker(appContext: Context, params: WorkerParameters) : CoroutineWorker(appContext, params) {

    override suspend fun doWork(): Result {
        return try {
            val context = applicationContext
            createNotificationChannel(context)

            val db = GitaDatabase.getDatabase(context)
            val stats = db.userStatsDao().getUserStatsOnce()
            val level = com.aipoweredgita.app.ui.components.YogaLevelManager.levelFor(stats)

            val prompt = when (level) {
                in 0..1 -> "What duty can you perform today without attachment to the result?"
                2 -> "Recall a moment you practiced devotion. How did it change your day?"
                3 -> "What truth have you learned recently, and how will you apply it?"
                else -> "How will you balance action, devotion, and knowledge today?"
            }

            // Create intent to open app when notification is tapped
            val intent = Intent(context, com.aipoweredgita.app.MainActivity::class.java).apply {
                flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
            }
            val pendingIntent = PendingIntent.getActivity(
                context,
                0,
                intent,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )

            val notification = NotificationCompat.Builder(context, CHANNEL_ID)
                .setSmallIcon(R.drawable.ic_menu_book)
                .setContentTitle("Daily Reflection")
                .setContentText(prompt)
                .setStyle(NotificationCompat.BigTextStyle().bigText(prompt))
                .setPriority(NotificationCompat.PRIORITY_DEFAULT)
                .setContentIntent(pendingIntent)
                .setAutoCancel(true)
                .build()

            // Show notification with permission handling
            try {
                NotificationManagerCompat.from(context).notify(NOTIF_ID, notification)
            } catch (e: SecurityException) {
                // Permission not granted or other security issue, skip notification
                return Result.success()
            }
            Result.success()
        } catch (e: Exception) {
            Result.retry()
        }
    }

    private fun createNotificationChannel(context: Context) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val channel = NotificationChannel(CHANNEL_ID, "Daily Reflection", NotificationManager.IMPORTANCE_DEFAULT)
            channel.description = "Daily spiritual reflection prompts"
            val nm = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
            nm.createNotificationChannel(channel)
        }
    }

    companion object {
        const val CHANNEL_ID = "daily_reflection_channel"
        const val NOTIF_ID = 2002
    }
}

package com.aipoweredgita.app.notifications

import android.content.Context
import com.aipoweredgita.app.database.DailyActivity
import com.aipoweredgita.app.database.DailyActivityDao
import com.aipoweredgita.app.database.GitaDatabase
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map
import java.util.Calendar
import java.util.Date

/**
 * ML-powered predictor for optimal notification timing
 * Analyzes user's daily activity patterns to predict best send times
 */
class SmartTimingPredictor(
    private val context: Context,
    private val dailyActivityDao: DailyActivityDao
) {

    /**
     * Analyzes user's activity patterns over the last N days
     * Returns hourly engagement scores (0-1)
     */
    suspend fun analyzeEngagementPatterns(days: Int = 14): Map<Int, Float> {
        val endDate = Calendar.getInstance().time
        val startDate = Calendar.getInstance().apply {
            time = endDate
            add(Calendar.DAY_OF_MONTH, -days)
        }.time

        // Get activities by iterating through date range
        val calendar = Calendar.getInstance().apply { time = startDate }
        val activities = mutableListOf<com.aipoweredgita.app.database.DailyActivity>()

        while (calendar.time <= endDate) {
            val dateString = "%04d-%02d-%02d".format(
                calendar.get(Calendar.YEAR),
                calendar.get(Calendar.MONTH) + 1,
                calendar.get(Calendar.DAY_OF_MONTH)
            )
            val activity = dailyActivityDao.getByDate(dateString)
            if (activity != null) {
                activities.add(activity)
            }
            calendar.add(Calendar.DAY_OF_MONTH, 1)
        }

        // Hourly engagement scores
        val hourlyScores = mutableMapOf<Int, MutableList<Float>>()
        (0..23).forEach { hour ->
            hourlyScores[hour] = mutableListOf()
        }

        // Calculate engagement for each hour based on activity
        activities.forEach { activity ->
            val totalSeconds = activity.normalSeconds + activity.quizSeconds
            if (totalSeconds <= 0) return@forEach
            val dailyEngagement = totalSeconds.toFloat() / 3600f

            // Distribute engagement across hours based on activity level
            // Higher engagement days contribute more to pattern detection
            val weight = (dailyEngagement / 2f).coerceIn(0.1f, 1.0f)
            // Spread activity across common study hours (morning + evening)
            val studyHours = listOf(6, 7, 8, 9, 10, 17, 18, 19, 20, 21, 22)
            studyHours.forEach { hour ->
                val engagementScore = weight * if (hour in 7..9 || hour in 19..22) 1.0f else 0.5f
                hourlyScores[hour]?.add(engagementScore.coerceIn(0f, 1f))
            }
        }

        // Calculate average engagement per hour
        return hourlyScores.mapValues { (_, scores) ->
            if (scores.isEmpty()) 0.3f else scores.average().toFloat()
        }
    }

    /**
     * Predicts the next optimal notification time based on:
     * 1. User's daily patterns
     * 2. Current day of week
     * 3. Time since last notification
     * 4. User's current streak status
     */
    suspend fun predictOptimalTime(
        minGapHours: Int = 4,
        streakDays: Int = 0
    ): Date {
        val patterns = analyzeEngagementPatterns()
        val calendar = Calendar.getInstance()

        // If no patterns, use default time
        if (patterns.isEmpty()) {
            calendar.add(Calendar.HOUR, minGapHours)
            return calendar.time
        }

        // Find top 3 engagement hours
        val topHours = patterns.entries
            .sortedByDescending { it.value }
            .take(3)
            .map { it.key }

        // Adjust for streak preservation
        val adjustedHours = if (streakDays > 0) {
            // If user has streak, prioritize morning notifications
            listOf(7, 8, 9, 19, 20)
        } else {
            topHours
        }

        // Find next occurrence of high-engagement hour
        val now = Calendar.getInstance()
        adjustedHours.forEach { hour ->
            val candidate = Calendar.getInstance().apply {
                set(Calendar.HOUR_OF_DAY, hour)
                set(Calendar.MINUTE, (0..59).random())
                set(Calendar.SECOND, 0)
            }

            // If candidate time is in the future, use it
            if (candidate.timeInMillis > now.timeInMillis + (minGapHours * 60 * 60 * 1000)) {
                return candidate.time
            }
        }

        // If all else fails, schedule for next day at best hour
        val bestHour = topHours.firstOrNull() ?: 9
        calendar.add(Calendar.DAY_OF_MONTH, 1)
        calendar.set(Calendar.HOUR_OF_DAY, bestHour)
        calendar.set(Calendar.MINUTE, (0..59).random())
        calendar.set(Calendar.SECOND, 0)

        return calendar.time
    }

    /**
     * Gets user's most active hours for today
     */
    suspend fun getTodaysActiveHours(): List<Int> {
        val patterns = analyzeEngagementPatterns(7) // Last 7 days
        return patterns.entries
            .sortedByDescending { it.value }
            .take(3)
            .map { it.key }
    }

    /**
     * Calculates notification probability based on user's recent activity
     * Returns value 0-1, where 1 means high probability of engagement
     */
    suspend fun calculateEngagementProbability(): Float {
        val today = Calendar.getInstance()
        val todayString = "%04d-%02d-%02d".format(
            today.get(Calendar.YEAR),
            today.get(Calendar.MONTH) + 1,
            today.get(Calendar.DAY_OF_MONTH)
        )
        val todayActivity = dailyActivityDao.getByDate(todayString)

        if (todayActivity == null) return 0.5f

        val totalActivity = todayActivity.normalSeconds + todayActivity.quizSeconds

        // Normalize activity time (more activity = higher engagement probability)
        val activityScore = (totalActivity.toFloat() / 3600f).coerceIn(0f, 8f) / 8f
        return activityScore
    }
}

package com.aipoweredgita.app.notifications

import android.content.Context
import com.aipoweredgita.app.database.DailyActivity
import com.aipoweredgita.app.database.GitaDatabase
import com.aipoweredgita.app.database.UserStats
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONObject
import java.net.HttpURLConnection
import java.net.URL
import java.time.LocalDate
import java.time.format.DateTimeFormatter

data class WeeklyInsight(
    val summary: String,
    val focusArea: String,
    val accuracyChange: Float,
    val krishnaMessage: String
)

object WeeklyInsightsEngine {

    private const val GROQ_API_URL = "https://api.groq.com/openai/v1/chat/completions"

    suspend fun generateWeeklyInsight(context: Context): WeeklyInsight? = withContext(Dispatchers.IO) {
        try {
            val db = GitaDatabase.getDatabase(context)
            val statsDao = db.userStatsDao()
            val activityDao = db.dailyActivityDao()

            val stats = statsDao.getUserStatsOnce() ?: return@withContext null
            val endDate = LocalDate.now()
            val startDate = endDate.minusDays(7)
            val dates = (0..6).map { startDate.plusDays(it.toLong()).format(DateTimeFormatter.ISO_LOCAL_DATE) }
            val activities = activityDao.getByDates(dates)

            if (activities.isEmpty()) return@withContext null

            val totalVerses = activities.sumOf { a: DailyActivity -> a.versesRead }
            val totalQuizTime = activities.sumOf { a: DailyActivity -> a.quizSeconds }
            val totalNormalTime = activities.sumOf { a: DailyActivity -> a.normalSeconds }
            val activeDays = activities.count { a: DailyActivity -> a.versesRead > 0 || a.quizSeconds > 0 }

            val prompt = buildString {
                appendLine("You are a wise Gita teacher. Generate a brief weekly learning insight.")
                appendLine()
                appendLine("Student stats this week:")
                appendLine("- Verses read: $totalVerses")
                appendLine("- Quiz time: ${totalQuizTime / 60} minutes")
                appendLine("- Reading time: ${totalNormalTime / 60} minutes")
                appendLine("- Active days: $activeDays / 7")
                appendLine("- Current streak: ${stats.currentStreak} days")
                appendLine("- Total accuracy: ${stats.accuracyPercentage}%")
                appendLine()
                appendLine("Respond in JSON format:")
                appendLine("""{"summary":"2-3 sentence summary","focusArea":"main topic studied","accuracyChange":0.0,"krishnaMessage":"1 line Krishna teaching"}""")
            }

            val response = callGroq(prompt) ?: return@withContext null
            parseInsight(response)
        } catch (e: Exception) {
            null
        }
    }

    private fun callGroq(prompt: String): String? {
        return try {
            val apiKey = "gsk_placeholder" // Replace with actual Groq API key
            val url = URL(GROQ_API_URL)
            val conn = url.openConnection() as HttpURLConnection
            conn.requestMethod = "POST"
            conn.setRequestProperty("Authorization", "Bearer $apiKey")
            conn.setRequestProperty("Content-Type", "application/json")
            conn.doOutput = true
            conn.connectTimeout = 10000
            conn.readTimeout = 15000

            val body = JSONObject().apply {
                put("model", "llama-3.1-8b-instant")
                put("messages", listOf(
                    JSONObject().put("role", "user").put("content", prompt)
                ))
                put("temperature", 0.7)
                put("max_tokens", 300)
            }

            conn.outputStream.use { it.write(body.toString().toByteArray()) }

            if (conn.responseCode == 200) {
                val json = JSONObject(conn.inputStream.bufferedReader().readText())
                json.getJSONArray("choices")
                    .getJSONObject(0)
                    .getJSONObject("message")
                    .getString("content")
            } else null
        } catch (e: Exception) {
            null
        }
    }

    private fun parseInsight(response: String): WeeklyInsight? {
        return try {
            val jsonStr = response.let { s ->
                val start = s.indexOf("{")
                val end = s.lastIndexOf("}") + 1
                if (start >= 0 && end > start) s.substring(start, end) else s
            }
            val json = JSONObject(jsonStr)
            WeeklyInsight(
                summary = json.optString("summary", "Keep up your Gita practice!"),
                focusArea = json.optString("focusArea", "General Study"),
                accuracyChange = json.optDouble("accuracyChange", 0.0).toFloat(),
                krishnaMessage = json.optString("krishnaMessage", "You have the right to work, but never to the fruit of work.")
            )
        } catch (e: Exception) {
            WeeklyInsight(
                summary = "Keep practicing the Gita daily!",
                focusArea = "General Study",
                accuracyChange = 0f,
                krishnaMessage = "You have the right to work, but never to the fruit of work."
            )
        }
    }
}

package com.aipoweredgita.app.notifications

import android.content.Context
import com.aipoweredgita.app.database.DailyActivityDao
import com.aipoweredgita.app.database.GitaDatabase
import com.aipoweredgita.app.database.UserStats
import com.aipoweredgita.app.database.UserStatsDao
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlin.math.round

/**
 * ML-powered notification priority classifier
 * Determines urgency level based on user data, learning patterns, and context
 */
enum class NotificationPriority(val level: Int, val androidPriority: Int, val channelImportance: Int) {
    CRITICAL(4, android.app.NotificationManager.IMPORTANCE_HIGH, 4),
    HIGH(3, android.app.NotificationManager.IMPORTANCE_HIGH, 3),
    MEDIUM(2, android.app.NotificationManager.IMPORTANCE_DEFAULT, 2),
    LOW(1, android.app.NotificationManager.IMPORTANCE_LOW, 1);

    companion object {
        fun fromLevel(level: Int): NotificationPriority {
            return when {
                level >= 4 -> CRITICAL
                level >= 3 -> HIGH
                level >= 2 -> MEDIUM
                else -> LOW
            }
        }
    }
}

enum class NotificationType {
    DAILY_REMINDER,
    STREAK_ALERT,
    ACHIEVEMENT,
    RECOMMENDATION,
    MILESTONE,
    WEAK_AREA_FOCUS,
    STREAK_RECOVERY,
    QUIZ_READY,
    CHAPTER_COMPLETE
}

data class NotificationContext(
    val type: NotificationType,
    val currentStreak: Int,
    val longestStreak: Int,
    val daysSinceLastActive: Int,
    val accuracy: Float,
    val versesRead: Int,
    val totalQuizzes: Int,
    val chapterProgress: Int,
    val weakAreas: List<String>,
    val userLevel: Int
)

/**
 * Classifies notification priority using ML-like scoring algorithm
 */
class NotificationPriorityClassifier(
    private val context: Context,
    private val userStatsDao: UserStatsDao,
    private val dailyActivityDao: DailyActivityDao
) {

    /**
     * Classifies priority based on comprehensive user context
     */
    suspend fun classifyPriority(notificationContext: NotificationContext): NotificationPriority {
        val userStats = userStatsDao.getUserStatsOnce() ?: return NotificationPriority.LOW

        val score = withContext(Dispatchers.IO) {
            calculatePriorityScore(notificationContext, userStats)
        }

        return NotificationPriority.fromLevel(score)
    }

    /**
     * Calculates priority score (1-4) based on multiple factors
     */
    private suspend fun calculatePriorityScore(
        context: NotificationContext,
        userStats: UserStats
    ): Int {
        val weightedScore = 1.0 +
            (calculateStreakScore(context, userStats) * 0.4) +
            (calculateMomentumScore(context) * 0.3) +
            (calculateAchievementScore(context) * 0.2) +
            (calculatePersonalizationScore(context) * 0.1)

        // Clamp to valid range (1-4)
        return round(weightedScore).toInt().coerceIn(1, 4)
    }

    /**
     * Calculates streak-related priority
     */
    private fun calculateStreakScore(context: NotificationContext, userStats: UserStats): Int {
        return when {
            // Critical: Streak at risk
            context.currentStreak > 0 && context.daysSinceLastActive >= 1 -> 4
            context.currentStreak >= 7 && context.daysSinceLastActive >= 1 -> 3
            context.currentStreak >= 3 && context.daysSinceLastActive == 1 -> 2
            // High: Streak milestone
            context.currentStreak in listOf(7, 30, 100, 365) -> 3
            // Medium: Building streak
            context.currentStreak > 0 -> 2
            else -> 1
        }
    }

    /**
     * Calculates learning momentum priority
     */
    private fun calculateMomentumScore(context: NotificationContext): Int {
        return when {
            // User is active and making progress
            context.daysSinceLastActive == 0 && context.versesRead > 0 -> 2
            // User was active recently
            context.daysSinceLastActive <= 2 -> 2
            // User has been inactive
            context.daysSinceLastActive > 7 -> 1
            else -> 2
        }
    }

    /**
     * Calculates achievement-related priority
     */
    private fun calculateAchievementScore(context: NotificationContext): Int {
        return when (context.type) {
            NotificationType.ACHIEVEMENT,
            NotificationType.MILESTONE,
            NotificationType.CHAPTER_COMPLETE -> 3
            NotificationType.STREAK_ALERT,
            NotificationType.STREAK_RECOVERY -> 4
            NotificationType.WEAK_AREA_FOCUS -> 2
            NotificationType.RECOMMENDATION,
            NotificationType.QUIZ_READY -> 2
            NotificationType.DAILY_REMINDER -> 1
        }
    }

    /**
     * Calculates personalization relevance
     */
    private fun calculatePersonalizationScore(context: NotificationContext): Int {
        var score = 1

        // Score based on weak areas
        if (context.weakAreas.isNotEmpty()) {
            score += 1
        }

        // Score based on accuracy (lower accuracy = higher priority for help)
        if (context.accuracy < 60f) {
            score += 1
        }

        // Score based on user level (newer users get higher priority)
        if (context.userLevel < 5) {
            score += 1
        }

        return score.coerceIn(1, 4)
    }

    /**
     * Gets recommended action for notification based on priority
     */
    fun getRecommendedAction(priority: NotificationPriority, type: NotificationType): String {
        return when (priority) {
            NotificationPriority.CRITICAL -> when (type) {
                NotificationType.STREAK_ALERT -> "Show immediately, with vibration"
                NotificationType.ACHIEVEMENT -> "Show immediately with celebration"
                else -> "Show immediately"
            }
            NotificationPriority.HIGH -> "Show within 15 minutes"
            NotificationPriority.MEDIUM -> "Show within 1 hour"
            NotificationPriority.LOW -> "Show during next batch"
        }
    }

    /**
     * Determines if notification should be sent now based on priority and timing
     */
    suspend fun shouldSendNow(priority: NotificationPriority, type: NotificationType): Boolean {
        // Critical notifications are always sent
        if (priority == NotificationPriority.CRITICAL) return true

        // High priority: send during active hours
        if (priority == NotificationPriority.HIGH) {
            val predictor = SmartTimingPredictor(context, dailyActivityDao)
            val probability = predictor.calculateEngagementProbability()
            return probability > 0.6
        }

        // Medium/Low: batch send during optimal times
        return false
    }
}

package com.aipoweredgita.app.notifications

import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.os.Build
import androidx.core.app.NotificationCompat
import androidx.core.app.NotificationManagerCompat
import androidx.work.CoroutineWorker
import androidx.work.WorkerParameters
import com.aipoweredgita.app.R
import com.aipoweredgita.app.database.GitaDatabase
import com.aipoweredgita.app.network.GitaApi
import com.aipoweredgita.app.util.GitaConstants

class DailyVerseWorker(appContext: Context, params: WorkerParameters) : CoroutineWorker(appContext, params) {

    override suspend fun doWork(): Result {
        try {
            val context = applicationContext
            createNotificationChannel(context)

            val database = GitaDatabase.getDatabase(context)

            // Get a meaningful random verse that hasn't been shown
            var verseData = database.cachedVerseDao().getRandomVerse()

            // If we ran out of verses, clear history and try again
            if (verseData == null && database.cachedVerseDao().getCachedCount() > 0) {
                 database.randomVerseHistoryDao().clearHistory()
                 verseData = database.cachedVerseDao().getRandomVerse()
            }

            val (chapter, verse) = if (verseData != null) {
                // Record history
                database.randomVerseHistoryDao().insertShownVerse(
                    com.aipoweredgita.app.database.RandomVerseHistory(
                        chapterNo = verseData.chapterNo,
                        verseNo = verseData.verseNo
                    )
                )
                verseData.chapterNo to verseData.verseNo
            } else {
                // Fallback if DB completely empty
                (2 to 47) 
            }

            // Try network first (optional, but we have text in DB usually)
            // Actually, if we got it from DB, use that text!
            val verseText: String = verseData?.verse?.replace("\\n", " ")?.replace("\n", " ")
                ?: try {
                    val v = GitaApi.retrofitService.getVerse(GitaConstants.DEFAULT_LANGUAGE, chapter, verse)
                    v.verse.replace("\\n", " ").replace("\n", " ")
                } catch (e: Exception) {
                    "Open app to read verse $chapter:$verse"
                }

            val content = if (verseText.length > 140) verseText.take(137) + "..." else verseText

            // Create intent to open app when notification is tapped
            val intent = Intent(context, com.aipoweredgita.app.MainActivity::class.java).apply {
                flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
                putExtra("NAVIGATE_TO", "random_sloka")
                putExtra("CHAPTER", chapter)
                putExtra("VERSE", verse)
            }
            val pendingIntent = PendingIntent.getActivity(
                context,
                0,
                intent,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )

            val notification = NotificationCompat.Builder(context, CHANNEL_ID)
                .setSmallIcon(R.drawable.ic_menu_book)
                .setContentTitle("Daily Gita Verse: $chapter:$verse")
                .setContentText(content)
                .setStyle(NotificationCompat.BigTextStyle().bigText(content))
                .setPriority(NotificationCompat.PRIORITY_DEFAULT)
                .setContentIntent(pendingIntent)
                .setAutoCancel(true)
                .build()

            // Show notification with permission handling
            try {
                NotificationManagerCompat.from(context).notify(NOTIF_ID, notification)
            } catch (e: SecurityException) {
                // Permission not granted or other security issue, skip notification
                return Result.success()
            }

            return Result.success()
        } catch (e: Exception) {
            return Result.retry()
        }
    }



    private fun createNotificationChannel(context: Context) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val name = "Daily Verse"
            val descriptionText = "Daily Bhagavad Gita verse notifications"
            val importance = NotificationManager.IMPORTANCE_DEFAULT
            val channel = NotificationChannel(CHANNEL_ID, name, importance).apply {
                description = descriptionText
            }
            val notificationManager: NotificationManager =
                context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
            notificationManager.createNotificationChannel(channel)
        }
    }

    companion object {
        const val CHANNEL_ID = "daily_verse_channel"
        const val NOTIF_ID = 1001
    }
}

package com.aipoweredgita.app.notifications

import android.content.Context
import androidx.work.*
import com.aipoweredgita.app.database.GitaDatabase
import com.aipoweredgita.app.database.UserStats
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

/**
 * ML-powered notification worker
 * Replaces basic DailyVerseWorker with intelligent notification scheduling
 *
 * Features:
 * - Smart timing based on user patterns
 * - Priority-based notification classification
 * - Personalized content generation
 * - Batch notification support
 */
class MLNotificationWorker(
    appContext: Context,
    params: WorkerParameters
) : CoroutineWorker(appContext, params) {

    override suspend fun doWork(): Result = withContext(Dispatchers.IO) {
        try {
            val database = GitaDatabase.getDatabase(applicationContext)
            val notificationManager = MLNotificationManager(
                applicationContext,
                database.userStatsDao(),
                database.dailyActivityDao()
            )
            val userStats = database.userStatsDao().getUserStatsOnce()
                ?: return@withContext Result.failure()

            // Determine what type of notification to send based on user state
            val notificationsToSend = determineOptimalNotifications(userStats)

            if (notificationsToSend.isEmpty()) {
                // No notifications needed, reschedule for next day
                return@withContext Result.success()
            }

            // Send notifications with ML optimization
            val results = notificationManager.sendBatchNotifications(notificationsToSend)

            val sentCount = results.count { it.sent }
            val failedCount = results.size - sentCount

            android.util.Log.d(
                "MLNotificationWorker",
                "Sent $sentCount notifications, failed $failedCount"
            )

            // If critical notifications failed, retry
            if (failedCount > 0 && hasCriticalNotifications(results)) {
                return@withContext Result.retry()
            }

            return@withContext Result.success()
        } catch (e: Exception) {
            android.util.Log.e("MLNotificationWorker", "Error in ML notification worker", e)
            return@withContext Result.retry()
        }
    }

    /**
     * Determines which notifications to send based on user's current state
     */
    private suspend fun determineOptimalNotifications(userStats: UserStats): List<NotificationType> = withContext(Dispatchers.IO) {
        val notifications = mutableListOf<NotificationType>()

        // 1. Daily Reminder (if user hasn't read today)
        val todayActivities = getTodaysActivities()
        if (todayActivities.isEmpty()) {
            notifications.add(NotificationType.DAILY_REMINDER)
        }

        // 2. Streak Alert (if streak is at risk)
        if (userStats.currentStreak > 0) {
            val daysSinceLastActive = calculateDaysSinceLastActive()
            if (daysSinceLastActive >= 1) {
                notifications.add(NotificationType.STREAK_ALERT)
            }
        }

        // 3. Achievement notification (randomly, based on milestones)
        val shouldSendAchievement = checkMilestoneAchievements(userStats)
        if (shouldSendAchievement) {
            notifications.add(NotificationType.ACHIEVEMENT)
        }

        // 4. Weak area focus (if user has low accuracy)
        if (userStats.accuracyPercentage < 70f) {
            notifications.add(NotificationType.WEAK_AREA_FOCUS)
        }

        // 5. Quiz ready notification (based on recent activity)
        val hasRecentActivity = todayActivities.sumOf { it.versesRead } > 0
        if (hasRecentActivity && userStats.totalQuizzesTaken < userStats.distinctVersesRead / 5) {
            notifications.add(NotificationType.QUIZ_READY)
        }

        // 6. Recommendation (personalized learning path)
        if (shouldSendRecommendation(userStats)) {
            notifications.add(NotificationType.RECOMMENDATION)
        }

        // Limit to max 3 notifications per day
        return@withContext notifications.take(3)
    }

    /**
     * Checks for milestone achievements
     */
    private fun checkMilestoneAchievements(userStats: UserStats): Boolean {
        val milestones = listOf(10, 25, 50, 75, 100, 200, 300, 400, 500, 700)
        val recentMilestones = milestones.filter { milestone ->
            userStats.distinctVersesRead >= milestone &&
                    userStats.distinctVersesRead < milestone + 5
        }
        return recentMilestones.isNotEmpty()
    }

    /**
     * Determines if recommendation should be sent
     */
    private fun shouldSendRecommendation(userStats: UserStats): Boolean {
        // Send recommendation if:
        // - User has been active but needs guidance
        // - Low accuracy (needs improvement focus)
        // - High accuracy (ready for next challenge)
        return when {
            userStats.accuracyPercentage < 60f -> true
            userStats.accuracyPercentage > 85f && userStats.currentStreak > 3 -> true
            userStats.totalQuizzesTaken % 10 == 0 -> true // Every 10 quizzes
            else -> false
        }
    }

    /**
     * Gets today's activities
     */
    private suspend fun getTodaysActivities(): List<com.aipoweredgita.app.database.DailyActivity> {
        val database = GitaDatabase.getDatabase(applicationContext)
        val today = getTodaysDateString()
        val activity = database.dailyActivityDao().getByDate(today)
        return if (activity != null) listOf(activity) else emptyList()
    }

    /**
     * Calculates days since last active
     */
    private fun calculateDaysSinceLastActive(): Int {
        // Simplified implementation
        // In real app, query database for last activity
        val calendar = java.util.Calendar.getInstance()
        return calendar.get(java.util.Calendar.DAY_OF_YEAR)
    }

    /**
     * Gets today's date string in YYYY-MM-DD format
     */
    private fun getTodaysDateString(): String {
        val calendar = java.util.Calendar.getInstance()
        val year = calendar.get(java.util.Calendar.YEAR)
        val month = calendar.get(java.util.Calendar.MONTH) + 1
        val day = calendar.get(java.util.Calendar.DAY_OF_MONTH)
        return "%04d-%02d-%02d".format(year, month, day)
    }

    /**
     * Checks if results contain critical notifications
     */
    private fun hasCriticalNotifications(results: List<NotificationResult>): Boolean {
        return results.any { result ->
            // In a real implementation, you'd track which notifications were critical
            // For now, assume streak alerts are critical
            result.type == NotificationType.STREAK_ALERT && !result.sent
        }
    }

    companion object {
        /**
         * Schedules the ML notification worker
         */
        fun scheduleMLNotifications(context: Context) {
            val workRequest = PeriodicWorkRequestBuilder<MLNotificationWorker>(
                24,
                java.util.concurrent.TimeUnit.HOURS
            )
                .setConstraints(
                    Constraints.Builder()
                        .setRequiredNetworkType(NetworkType.NOT_REQUIRED)
                        .build()
                )
                .build()

            WorkManager.getInstance(context).enqueueUniquePeriodicWork(
                "ml_notification_work",
                ExistingPeriodicWorkPolicy.KEEP,
                workRequest
            )
        }

        /**
         * Schedules one-time notification
         */
        fun scheduleOneTimeNotification(
            context: Context,
            notificationType: NotificationType,
            delayMinutes: Long = 0
        ) {
            val delay = java.util.concurrent.TimeUnit.MINUTES.toMillis(delayMinutes)

            val workRequest = OneTimeWorkRequestBuilder<MLNotificationWorker>()
                .setInitialDelay(delay, java.util.concurrent.TimeUnit.MILLISECONDS)
                .setInputData(workDataOf("notification_type" to notificationType.name))
                .build()

            WorkManager.getInstance(context).enqueueUniqueWork(
                "one_time_${notificationType.name}",
                ExistingWorkPolicy.REPLACE,
                workRequest
            )
        }

        /**
         * Cancels all notification workers
         */
        fun cancelNotifications(context: Context) {
            WorkManager.getInstance(context).cancelAllWorkByTag("ml_notification_work")
        }
    }
}

