import com.aipoweredgita.app.network.CoinSpendRequest
import com.aipoweredgita.app.network.ShareSlokaRequest
import com.aipoweredgita.app.utils.AuthPreferences
import com.google.gson.Gson
import java.util.concurrent.TimeUnit

class SyncWorker(
    context: Context,
    params: WorkerParameters
) : CoroutineWorker(context, params) {

    companion object {
        private const val TAG = "SyncWorker"
        private const val WORK_NAME = "offline_coin_sync"

        fun schedule(context: Context) {
            val constraints = Constraints.Builder()
                .setRequiredNetworkType(NetworkType.CONNECTED)
                .build()

            val request = OneTimeWorkRequestBuilder<SyncWorker>()
                .setConstraints(constraints)
                .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 30, TimeUnit.SECONDS)
                .build()

            WorkManager.getInstance(context).enqueueUniqueWork(
                WORK_NAME,
                ExistingWorkPolicy.KEEP,
                request
            )
            Log.d(TAG, "Offline coin synchronization scheduled")
        }
    }

    override suspend fun doWork(): Result {
        val authPrefs = AuthPreferences.getInstance(applicationContext)
        val currentUserId = authPrefs.userId

        Log.d(TAG, "doWork() called. UserId: $currentUserId, isGuest: ${authPrefs.isGuestUser}")

        if (currentUserId.isNullOrEmpty() || authPrefs.isGuestUser) {
            Log.d(TAG, "No logged-in user or guest active, skipping background sync")
            return Result.success()
        }

        val database = GitaDatabase.getDatabase(applicationContext)
        val dao = database.pendingSyncEventDao()
        val userStatsDao = database.userStatsDao()

        val statsRepository = com.aipoweredgita.app.repository.StatsRepository(
            userStatsDao = userStatsDao,
            dailyActivityDao = database.dailyActivityDao(),
            appContext = applicationContext
        )

        val events = dao.getPendingEvents(currentUserId)

        if (events.isEmpty()) {
            Log.d(TAG, "No pending sync events found for user: $currentUserId")
            return Result.success()
        }

        Log.d(TAG, "Found ${events.size} pending sync events for user: $currentUserId")
        val gson = Gson()

        for (event in events) {
            try {
                Log.d(TAG, "Processing event ID: ${event.id}, type: ${event.eventType}, idempotencyKey: ${event.idempotencyKey}")
                when (event.eventType) {
                    "QUIZ" -> {
                        val jsonObject = gson.fromJson(event.payload, com.google.gson.JsonObject::class.java)
                        val score = jsonObject.get("score")?.asInt ?: 0
                        val totalQuestions = jsonObject.get("totalQuestions")?.asInt ?: 0
                        val accuracy = jsonObject.get("accuracy")?.asFloat ?: 0f
                        val streakDays = jsonObject.get("streakDays")?.asInt ?: 0
                        val checkinDay = jsonObject.get("checkinDay")?.asInt ?: 0
                        val quizType = jsonObject.get("quizType")?.asString ?: "general"

                        Log.d(TAG, "Syncing QUIZ: score=$score, total=$totalQuestions, accuracy=$accuracy, type=$quizType")
                        val response = CoinApi.retrofitService.awardCoins(
                            CoinAwardRequest(
                                user_id = event.userId,
                                source = "quiz_completion",
                                metadata = mapOf(
                                    "accuracy" to accuracy,
                                    "score" to score,
                                    "totalQuestions" to totalQuestions,
                                    "streakDays" to streakDays,
                                    "checkinDay" to checkinDay,
                                    "quizType" to quizType
                                )
                            )
                        )
                        userStatsDao.updateKrishnaCoins(response.total_coins)
                        Log.d(TAG, "Quiz sync success. New server balance: ${response.total_coins}")
                    }
                    "CHAPTER" -> {
                        Log.d(TAG, "Syncing CHAPTER completion")
                        val response = CoinApi.retrofitService.awardCoins(
                            CoinAwardRequest(
                                user_id = event.userId,
                                source = "chapter_completion"
                            )
                        )
                        userStatsDao.updateKrishnaCoins(response.total_coins)
                        Log.d(TAG, "Chapter sync success. New server balance: ${response.total_coins}")
                    }
                    "BATTLE" -> {
                        val jsonObject = gson.fromJson(event.payload, com.google.gson.JsonObject::class.java)
                        val battleCoins = jsonObject.get("battleCoins")?.asInt ?: event.coinsToAdjust
                        val score = jsonObject.get("score")?.asInt ?: 0

                        Log.d(TAG, "Syncing BATTLE: battleCoins=$battleCoins, score=$score")
                        val response = CoinApi.retrofitService.awardCoins(
                            CoinAwardRequest(
                                user_id = event.userId,
                                source = "battle_quiz",
                                metadata = mapOf(
                                    "battleCoins" to battleCoins,
                                    "score" to score
                                )
                            )
                        )
                        userStatsDao.updateKrishnaCoins(response.total_coins)
                        Log.d(TAG, "Battle sync success. New server balance: ${response.total_coins}")
                    }
                    "SPEND" -> {
                        val jsonObject = gson.fromJson(event.payload, com.google.gson.JsonObject::class.java)
                        val question = jsonObject.get("question")?.asString ?: ""

                        Log.d(TAG, "Syncing SPEND: question=${question.take(50)}, idempotencyKey=${event.idempotencyKey}")
                        val response = CoinApi.retrofitService.spendCoins(
                            CoinSpendRequest(
                                user_id = event.userId,
                                question = question,
                                idempotency_key = event.idempotencyKey
                            )
                        )

                        if (response.duplicate == true) {
                            Log.w(TAG, "Spend sync: Duplicate detected on server, updating local balance to: ${response.remaining_balance}")
                        } else {
                            Log.d(TAG, "Spend sync success. Spent: ${response.spent}, remaining: ${response.remaining_balance}")
                        }
                        userStatsDao.updateKrishnaCoins(response.remaining_balance)
                    }
                    "CHECKIN" -> {
                        Log.d(TAG, "Syncing CHECKIN for user: ${event.userId}")
                        val response = CoinApi.retrofitService.checkin(mapOf("user_id" to event.userId))
                        if (response.duplicate == true) {
                            Log.w(TAG, "Checkin sync: Duplicate detected on server")
                        } else {
                            Log.d(TAG, "Checkin sync success. Coins awarded: ${response.coins_awarded}")
                            if (event.userId == authPrefs.userId && response.day > 0) {
                                DailyRewardsTracker.getInstance(applicationContext).syncWithServer(response.day, response.week)
                            }
                        }
                        if (event.userId == authPrefs.userId) {
                            DailyRewardsTracker.getInstance(applicationContext).isCheckinSynced = true
                        }
                    }
                    "SHARE" -> {
                        val jsonObject = gson.fromJson(event.payload, com.google.gson.JsonObject::class.java)
                        val chapter = if (jsonObject.has("chapter") && !jsonObject.get("chapter").isJsonNull) jsonObject.get("chapter").asInt else null
                        val verse = if (jsonObject.has("verse") && !jsonObject.get("verse").isJsonNull) jsonObject.get("verse").asInt else null
                        val slokaId = if (jsonObject.has("slokaId") && !jsonObject.get("slokaId").isJsonNull) jsonObject.get("slokaId").asString else null

                        Log.d(TAG, "Syncing SHARE: chapter=$chapter, verse=$verse, slokaId=$slokaId")
                        val response = CoinApi.retrofitService.share(
                            ShareSlokaRequest(
                                user_id = event.userId,
                                sloka_id = slokaId,
                                chapter = chapter,
                                verse = verse
                            )
                        )
                        if (response.duplicate == true) {
                            Log.w(TAG, "Share sync: Duplicate detected on server")
                        } else {
                            Log.d(TAG, "Share sync success. Coins awarded: ${response.coins_awarded}")
                            if (event.userId == authPrefs.userId && response.share_day > 0) {
                                DailyRewardsTracker.getInstance(applicationContext).syncShareWithServer(response.share_day, response.share_week)
                            }
                        }
                        if (event.userId == authPrefs.userId) {
                            DailyRewardsTracker.getInstance(applicationContext).isShareSynced = true
                        }
                    }
                    "STATS_SYNC" -> {
                        Log.d(TAG, "Syncing STATS_SYNC for user: ${event.userId}")
                        val token = authPrefs.token
                        val latestStats = userStatsDao.getUserStatsOnce()
                        if (!token.isNullOrEmpty() && latestStats != null) {
                            val response = CoinApi.retrofitService.syncUserStats(
                                token = "Bearer $token",
                                request = com.aipoweredgita.app.network.UserStatsSyncRequest(
                                    user_id = event.userId,
                                    current_streak = latestStats.currentStreak,
                                    longest_streak = latestStats.longestStreak,
                                    total_quizzes_taken = latestStats.totalQuizzesTaken,
                                    total_questions_answered = latestStats.totalQuestionsAnswered,
                                    verses_read = latestStats.versesRead,
                                    chapters_completed = latestStats.chaptersCompleted,
                                    last_activity_date = latestStats.lastActiveDate
                                )
                            )
                            if (response.success && response.stats != null) {
                                userStatsDao.syncRemoteStats(
                                    currentStreak = response.stats.current_streak,
                                    longestStreak = response.stats.longest_streak,
                                    totalQuizzesTaken = response.stats.total_quizzes_taken,
                                    totalQuestionsAnswered = response.stats.total_questions_answered,
                                    versesRead = response.stats.verses_read,
                                    chaptersCompleted = response.stats.chapters_completed,
                                    daysActive = userStatsDao.getUserStatsOnce()?.daysActive ?: 1,
                                    lastActiveDate = response.stats.last_activity_date
                                )
                                Log.d(TAG, "Stats sync success. Server streak: ${response.stats.current_streak}")
                            }
                        } else {
                            Log.w(TAG, "No token available for stats sync, skipping")
                        }
                    }
                    else -> {
                        Log.w(TAG, "Unknown event type: ${event.eventType}, deleting event")
                    }
                }
                // Successful processing: delete event
                dao.delete(event)
                Log.d(TAG, "Successfully processed and deleted event ID: ${event.id}")
            } catch (e: java.io.IOException) {
                Log.e(TAG, "Network failure syncing event ID: ${event.id}: ${e.message}")
                return Result.retry()
            } catch (e: retrofit2.HttpException) {
                Log.e(TAG, "HTTP server error syncing event ID: ${event.id}: ${e.code()} ${e.message()}")
                val errorBody = try { e.response()?.errorBody()?.string() } catch (_: Exception) { null }
                Log.e(TAG, "Error body: $errorBody")

                if (e.code() in 400..499) {
                    // For SPEND events, don't delete on 400 - might be duplicate idempotency
                    if (event.eventType == "SPEND") {
                        if (errorBody?.contains("duplicate") == true) {
                            dao.delete(event)
                            Log.w(TAG, "Deleted duplicate spend event ID: ${event.id}")
                        } else {
                            Log.w(TAG, "Keeping spend event ID: ${event.id} for retry")
                        }
                    } else {
                        // Non-SPEND events: delete on client error
                        dao.delete(event)
                        Log.w(TAG, "Deleted invalid event ID: ${event.id} due to Client Error ${e.code()}")
                    }
                } else {
                    // Server error (500+): retry
                    return Result.retry()
                }
            } catch (e: Exception) {
                Log.e(TAG, "Unexpected error syncing event ID: ${event.id}: ${e.message}", e)
                // Don't delete on unexpected errors - might be transient
                return Result.retry()
            }
        }

        Log.d(TAG, "All events processed successfully")

        // TOP-TO-BOTTOM SYNC: Fetch authoritative state from server after all offline events are processed
        Log.d(TAG, "Fetching latest authoritative state from server for $currentUserId")
        statsRepository.refreshUserState(currentUserId)

        return Result.success()
    }
}

package com.aipoweredgita.app.services

import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.os.Build
import androidx.core.app.NotificationCompat
import com.aipoweredgita.app.MainActivity
import com.aipoweredgita.app.R

/**
 * Manages notification for offline verse download completion.
 */
class OfflineDownloadNotificationManager(private val context: Context) {

    private val CHANNEL_ID = "offline_download_channel"
    private val NOTIFICATION_ID = 7001
    private val INCOMPLETE_NOTIFICATION_ID = 7002
    private val IN_PROGRESS_NOTIFICATION_ID = 7003

    init {
        createNotificationChannel()
    }

    private fun createNotificationChannel() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val channel = NotificationChannel(
                CHANNEL_ID,
                "Offline Downloads",
                NotificationManager.IMPORTANCE_DEFAULT
            ).apply {
                description = "Notifications for verse downloads"
            }
            val nm = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
            nm.createNotificationChannel(channel)
        }
    }

    fun showCompletionNotification() {
        val intent = Intent(context, MainActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP
        }
        val pendingIntent = PendingIntent.getActivity(
            context,
            0,
            intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        val notification = NotificationCompat.Builder(context, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_menu_book)
            .setContentTitle("All verses downloaded")
            .setContentText("You can read offline now")
            .setContentIntent(pendingIntent)
            .setAutoCancel(true)
            .setPriority(NotificationCompat.PRIORITY_DEFAULT)
            .build()

        val nm = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        nm.notify(NOTIFICATION_ID, notification)
    }

    fun showIncompleteNotification(missingCount: Int) {
        val intent = Intent(context, MainActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP
        }
        val pendingIntent = PendingIntent.getActivity(
            context,
            0,
            intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        // Action: Retry missing via WorkManager
        val retryIntent = Intent(OfflineRetryReceiver.ACTION_RETRY_MISSING).apply {
            `package` = context.packageName
        }
        val retryPending = PendingIntent.getBroadcast(
            context,
            1,
            retryIntent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        val title = if (missingCount > 0) "Incomplete offline download" else "Offline download status"
        val body = if (missingCount > 0) {
            "$missingCount verses missing. Tap to resume."
        } else {
            "Some verses may be missing."
        }

        val notification = NotificationCompat.Builder(context, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_menu_book)
            .setContentTitle(title)
            .setContentText(body)
            .setContentIntent(pendingIntent)
            .addAction(R.drawable.ic_menu_book, context.getString(R.string.generic_retry), retryPending)
            .setAutoCancel(true)
            .setPriority(NotificationCompat.PRIORITY_DEFAULT)
            .build()

        val nm = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        nm.notify(INCOMPLETE_NOTIFICATION_ID, notification)
    }

    fun showInProgressNotification() {
        val intent = Intent(context, MainActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP
        }
        val pendingIntent = PendingIntent.getActivity(
            context,
            0,
            intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        val notification = NotificationCompat.Builder(context, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_menu_book)
            .setContentTitle("Downloading verses")
            .setContentText("Download is running in background")
            .setOngoing(true)
            .setOnlyAlertOnce(true)
            .setContentIntent(pendingIntent)
            .setPriority(NotificationCompat.PRIORITY_LOW)
            .build()

        val nm = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        nm.notify(IN_PROGRESS_NOTIFICATION_ID, notification)
    }

    fun cancelInProgressNotification() {
        val nm = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        nm.cancel(IN_PROGRESS_NOTIFICATION_ID)
    }
}

package com.aipoweredgita.app.services

import android.content.Context
import android.util.Log
import androidx.work.*
import com.aipoweredgita.app.database.GitaDatabase
import com.aipoweredgita.app.ml.BhagavadGitaQAImporter
import java.util.concurrent.TimeUnit

class QuestionIngestionWorker(
    context: Context,
    params: WorkerParameters
) : CoroutineWorker(context, params) {

    companion object {
        private const val TAG = "QuestionIngestionWorker"
        private const val WORK_NAME = "question_ingestion"

        fun schedule(context: Context) {
            val constraints = Constraints.Builder()
                .setRequiredNetworkType(NetworkType.CONNECTED)
                .setRequiresDeviceIdle(false)
                .setRequiresCharging(false)
                .setRequiresBatteryNotLow(false)
                .build()

            val request = OneTimeWorkRequestBuilder<QuestionIngestionWorker>()
                .setConstraints(constraints)
                .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 30, TimeUnit.SECONDS)
                .build()

            WorkManager.getInstance(context).enqueueUniqueWork(
                WORK_NAME,
                ExistingWorkPolicy.KEEP,
                request
            )
            Log.d(TAG, "Question ingestion scheduled")
        }
    }

    override suspend fun doWork(): Result {
        return try {
            val database = GitaDatabase.getDatabase(applicationContext)
            val dao = database.quizQuestionBankDao()

            // Check if questions already exist
            val existingCount = dao.getTotalCount()
            if (existingCount > 50) {
                Log.d(TAG, "Questions already exist ($existingCount), skipping ingestion")
                return Result.success()
            }

            Log.d(TAG, "Starting automatic question ingestion from dataset...")
            val importer = BhagavadGitaQAImporter(applicationContext, dao)

            val imported = importer.importDataset(
                language = "english",
                batchSize = 500
            ) { count, total ->
                Log.d(TAG, "Importing: $count / $total")
            }

            Log.d(TAG, "✓ Auto-ingestion complete: $imported questions saved")
            Result.success()
        } catch (e: Exception) {
            Log.e(TAG, "Auto-ingestion failed: ${e.message}", e)
            Result.retry()
        }
    }
}

package com.aipoweredgita.app.services

import android.app.NotificationChannel
import android.app.NotificationManager
import android.content.Context
import android.os.Build
import android.util.Log
import androidx.core.app.NotificationCompat
import androidx.work.*
import java.io.File
import java.util.concurrent.TimeUnit

class QwenDownloadWorker(
    context: Context,
    params: WorkerParameters
) : CoroutineWorker(context, params) {

    companion object {
        private const val TAG = "QwenDownloadWorker"
        private const val WORK_NAME_QWEN = "qwen_download"

        fun scheduleImmediateDownload(context: Context, modelName: String = "Qwen3 0.6B") {
            val constraints = Constraints.Builder()
                .setRequiredNetworkType(NetworkType.CONNECTED)
                .setRequiresDeviceIdle(false)
                .setRequiresCharging(false)
                .setRequiresBatteryNotLow(false)
                .build()

            val request = OneTimeWorkRequestBuilder<QwenDownloadWorker>()
                .setConstraints(constraints)
                .setInputData(workDataOf("model_name" to modelName))
                .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 30, TimeUnit.SECONDS)
                .build()

            WorkManager.getInstance(context).enqueueUniqueWork(
                WORK_NAME_QWEN + "_" + modelName.replace(" ", "_"),
                ExistingWorkPolicy.REPLACE,
                request
            )
            Log.d(TAG, "Scheduled immediate Qwen download for $modelName")
        }

        fun scheduleBackgroundDownload(context: Context, modelName: String = "Qwen3 0.6B") {
            val constraints = Constraints.Builder()
                .setRequiredNetworkType(NetworkType.UNMETERED)
                .setRequiresDeviceIdle(false)
                .setRequiresCharging(false)
                .setRequiresBatteryNotLow(false)
                .build()

            val request = OneTimeWorkRequestBuilder<QwenDownloadWorker>()
                .setConstraints(constraints)
                .setInputData(workDataOf("model_name" to modelName))
                .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 15, TimeUnit.MINUTES)
                .build()

            WorkManager.getInstance(context).enqueueUniqueWork(
                WORK_NAME_QWEN + "_" + modelName.replace(" ", "_"),
                ExistingWorkPolicy.KEEP,
                request
            )
            Log.d(TAG, "Scheduled background Qwen download for $modelName (WiFi)")
        }

        fun cancelDownload(context: Context, modelName: String = "Qwen3 0.6B") {
            WorkManager.getInstance(context).cancelUniqueWork(WORK_NAME_QWEN + "_" + modelName.replace(" ", "_"))
            val notificationManager = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
            notificationManager.cancel(7020)
            notificationManager.cancel(7021)
            Log.d(TAG, "Cancelled Qwen download")
        }

        fun getDownloadStatusLive(context: Context, modelName: String = "Qwen3 0.6B"): androidx.lifecycle.LiveData<WorkInfo?> {
            val live = WorkManager.getInstance(context)
                .getWorkInfosForUniqueWorkLiveData(WORK_NAME_QWEN + "_" + modelName.replace(" ", "_"))
            val out = androidx.lifecycle.MediatorLiveData<WorkInfo?>()
            out.addSource(live) { list -> out.value = list.firstOrNull() }
            return out
        }

        fun isDownloading(context: Context, modelName: String = "Qwen3 0.6B"): Boolean {
            val workInfos = WorkManager.getInstance(context)
                .getWorkInfosForUniqueWork(WORK_NAME_QWEN + "_" + modelName.replace(" ", "_"))
                .get()
            return workInfos?.any {
                it.state == WorkInfo.State.RUNNING || it.state == WorkInfo.State.ENQUEUED
            } == true
        }
    }

    override suspend fun doWork(): Result {
        return try {
            val modelName = inputData.getString("model_name") ?: "Qwen3 0.6B"
            Log.d(TAG, "QwenDownloadWorker started (attempt ${runAttemptCount + 1}) for $modelName")

            val manager = com.aipoweredgita.app.ml.ModelDownloadManager(applicationContext)
            val modelInfo = manager.getModelInfo(modelName) ?: return Result.failure()
            val qwenFile = File(applicationContext.filesDir, "ml_models/${modelInfo.fileName}")
            val minSize = (modelInfo.expectedBytes * 0.9).toLong()

            if (qwenFile.exists() && qwenFile.length() >= minSize) {
                Log.d(TAG, "Qwen already downloaded (${qwenFile.length() / (1024 * 1024)} MB), skipping")
                setProgressAsync(workDataOf("overallProgress" to 100))
                return Result.success()
            }

            val displayName = "${modelInfo.name} (${modelInfo.size})"
            startForegroundNotification(displayName)

            val success = manager.downloadModel(modelInfo.name) { prog ->
                setProgressAsync(workDataOf(
                    "currentModel" to prog.fileName,
                    "modelProgress" to prog.percent,
                    "overallProgress" to prog.percent
                ))
                updateForegroundNotification(displayName, prog.percent)
            }

            if (!success) {
                Log.w(TAG, "Qwen download incomplete or failed (attempt ${runAttemptCount + 1})")
                return if (runAttemptCount < 5) Result.retry() else Result.failure()
            }

            if (qwenFile.exists() && qwenFile.length() >= minSize) {
                Log.d(TAG, "Qwen downloaded successfully (${qwenFile.length() / (1024 * 1024)} MB)")
                setProgressAsync(workDataOf("overallProgress" to 100))
                showCompletionNotification(displayName)
                Result.success()
            } else {
                Log.w(TAG, "Qwen file validation failed after download")
                if (runAttemptCount < 5) Result.retry() else Result.failure()
            }

        } catch (e: Exception) {
            Log.e(TAG, "Error downloading Qwen: ${e.message}", e)
            if (runAttemptCount < 5) Result.retry() else Result.failure()
        }
    }

    private suspend fun startForegroundNotification(displayName: String) {
        val channelId = "qwen_download_channel"

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val notificationManager = applicationContext.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
            val channel = NotificationChannel(
                channelId,
                "Model Downloads",
                NotificationManager.IMPORTANCE_LOW
            ).apply {
                description = "Shows progress of Qwen AI model download"
                setShowBadge(false)
            }
            notificationManager.createNotificationChannel(channel)
        }

        val notification = NotificationCompat.Builder(applicationContext, channelId)
            .setSmallIcon(android.R.drawable.stat_sys_download)
            .setContentTitle("Downloading Qwen AI Engine")
            .setContentText("$displayName - Starting...")
            .setPriority(NotificationCompat.PRIORITY_LOW)
            .setOngoing(true)
            .setOnlyAlertOnce(true)
            .setProgress(100, 0, true)
            .build()

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            setForeground(ForegroundInfo(
                7020,
                notification,
                android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_DATA_SYNC
            ))
        } else {
            setForeground(ForegroundInfo(7020, notification))
        }
    }

    private fun updateForegroundNotification(displayName: String, progress: Int) {
        val channelId = "qwen_download_channel"
        val notification = NotificationCompat.Builder(applicationContext, channelId)
            .setSmallIcon(android.R.drawable.stat_sys_download)
            .setContentTitle("Downloading Qwen AI Engine")
            .setContentText("$displayName - $progress% complete")
            .setPriority(NotificationCompat.PRIORITY_LOW)
            .setOngoing(true)
            .setOnlyAlertOnce(true)
            .setProgress(100, progress, false)
