package com.aipoweredgita.app.services

import android.app.NotificationChannel
import android.app.NotificationManager
import android.content.Context
import android.os.Build
import android.util.Log
import androidx.core.app.NotificationCompat
import androidx.work.*
import java.io.File
import java.util.concurrent.TimeUnit

class GemmaDownloadWorker(
    context: Context,
    params: WorkerParameters
) : CoroutineWorker(context, params) {

    companion object {
        private const val TAG = "GemmaDownloadWorker"
        private const val WORK_NAME_GEMMA = "gemma_download"

        fun scheduleImmediateDownload(context: Context) {
            val tier = com.aipoweredgita.app.utils.DeviceTierDetector.detect(context)
            val isHighEnd = tier == com.aipoweredgita.app.utils.DeviceTier.FLAGSHIP || 
                            tier == com.aipoweredgita.app.utils.DeviceTier.HIGH_MID

            if (!isHighEnd) {
                Log.d(TAG, "Skipping Gemma download: Device tier too low (detected: ${tier.label})")
                return
            }

            val constraints = Constraints.Builder()
                .setRequiredNetworkType(NetworkType.CONNECTED)
                .setRequiresDeviceIdle(false)
                .setRequiresCharging(false)
                .setRequiresBatteryNotLow(false)
                .build()

            val request = OneTimeWorkRequestBuilder<GemmaDownloadWorker>()
                .setConstraints(constraints)
                .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 30, TimeUnit.SECONDS)
                .build()

            WorkManager.getInstance(context).enqueueUniqueWork(
                WORK_NAME_GEMMA,
                ExistingWorkPolicy.REPLACE,
                request
            )
            Log.d(TAG, "Scheduled immediate Gemma download")
        }

        fun scheduleBackgroundDownload(context: Context) {
            val tier = com.aipoweredgita.app.utils.DeviceTierDetector.detect(context)
            val isHighEnd = tier == com.aipoweredgita.app.utils.DeviceTier.FLAGSHIP || 
                            tier == com.aipoweredgita.app.utils.DeviceTier.HIGH_MID

            if (!isHighEnd) {
                Log.d(TAG, "Skipping background Gemma download: Device tier too low (detected: ${tier.label})")
                return
            }

            val constraints = Constraints.Builder()
                .setRequiredNetworkType(NetworkType.UNMETERED)
                .setRequiresDeviceIdle(false)
                .setRequiresCharging(false)
                .setRequiresBatteryNotLow(false)
                .build()

            val request = OneTimeWorkRequestBuilder<GemmaDownloadWorker>()
                .setConstraints(constraints)
                .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 15, TimeUnit.MINUTES)
                .build()

            WorkManager.getInstance(context).enqueueUniqueWork(
                WORK_NAME_GEMMA,
                ExistingWorkPolicy.KEEP,
                request
            )
            Log.d(TAG, "Scheduled background Gemma download (WiFi)")
        }

        fun cancelDownload(context: Context) {
            WorkManager.getInstance(context).cancelUniqueWork(WORK_NAME_GEMMA)
            val notificationManager = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
            notificationManager.cancel(7010)
            notificationManager.cancel(7011)
            Log.d(TAG, "Cancelled Gemma download")
        }

        fun getDownloadStatusLive(context: Context): androidx.lifecycle.LiveData<WorkInfo?> {
            val live = WorkManager.getInstance(context)
                .getWorkInfosForUniqueWorkLiveData(WORK_NAME_GEMMA)
            val out = androidx.lifecycle.MediatorLiveData<WorkInfo?>()
            out.addSource(live) { list -> out.value = list.firstOrNull() }
            return out
        }

        fun isDownloading(context: Context): Boolean {
            val workInfos = WorkManager.getInstance(context)
                .getWorkInfosForUniqueWork(WORK_NAME_GEMMA)
                .get()
            return workInfos?.any {
                it.state == WorkInfo.State.RUNNING || it.state == WorkInfo.State.ENQUEUED
            } == true
        }
    }

    override suspend fun doWork(): Result {
        val tier = com.aipoweredgita.app.utils.DeviceTierDetector.detect(applicationContext)
        val isHighEnd = tier == com.aipoweredgita.app.utils.DeviceTier.FLAGSHIP || 
                        tier == com.aipoweredgita.app.utils.DeviceTier.HIGH_MID

        if (!isHighEnd) {
            Log.w(TAG, "GemmaDownloadWorker aborting: Device tier too low (detected: ${tier.label}) during execution")
            return Result.success() // Success because we don't want to retry
        }

        return try {
            Log.d(TAG, "GemmaDownloadWorker started (attempt ${runAttemptCount + 1})")

            val manager = com.aipoweredgita.app.ml.ModelDownloadManager(applicationContext)
            val modelInfo = manager.getModelInfo("Gemma 4 2B") ?: return Result.failure()
            val gemmaFile = File(applicationContext.filesDir, "ml_models/${modelInfo.fileName}")
            val minSize = (modelInfo.expectedBytes * 0.9).toLong()

            if (gemmaFile.exists() && gemmaFile.length() >= minSize) {
                Log.d(TAG, "Gemma already downloaded (${gemmaFile.length() / (1024 * 1024)} MB), skipping")
                setProgressAsync(workDataOf("overallProgress" to 100))
                return Result.success()
            }

            val displayName = "${modelInfo.name} (${modelInfo.size})"
            startForegroundNotification(displayName)

            val success = manager.downloadModel(modelInfo.name) { prog ->
                setProgressAsync(workDataOf(
                    "currentModel" to prog.fileName,
                    "modelProgress" to prog.percent,
                    "overallProgress" to prog.percent
                ))
                updateForegroundNotification(displayName, prog.percent)
            }

            if (!success) {
                Log.w(TAG, "Gemma download incomplete or failed (attempt ${runAttemptCount + 1})")
                return if (runAttemptCount < 5) Result.retry() else Result.failure()
            }

            if (gemmaFile.exists() && gemmaFile.length() >= minSize) {
                Log.d(TAG, "Gemma downloaded successfully (${gemmaFile.length() / (1024 * 1024)} MB)")
                setProgressAsync(workDataOf("overallProgress" to 100))
                showCompletionNotification(displayName)
                Result.success()
            } else {
                Log.w(TAG, "Gemma file validation failed after download")
                if (runAttemptCount < 5) Result.retry() else Result.failure()
            }

        } catch (e: Exception) {
            Log.e(TAG, "Error downloading Gemma: ${e.message}", e)
            if (runAttemptCount < 5) Result.retry() else Result.failure()
        }
    }

    private suspend fun startForegroundNotification(displayName: String) {
        val channelId = "gemma_download_channel"

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val notificationManager = applicationContext.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
            val channel = NotificationChannel(
                channelId,
                "Model Downloads",
                NotificationManager.IMPORTANCE_LOW
            ).apply {
                description = "Shows progress of AI model download"
                setShowBadge(false)
            }
            notificationManager.createNotificationChannel(channel)
        }

        val notification = NotificationCompat.Builder(applicationContext, channelId)
            .setSmallIcon(android.R.drawable.stat_sys_download)
            .setContentTitle("Downloading AI Engine")
            .setContentText("$displayName - Starting...")
            .setPriority(NotificationCompat.PRIORITY_LOW)
            .setOngoing(true)
            .setOnlyAlertOnce(true)
            .setProgress(100, 0, true)
            .build()

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            setForeground(ForegroundInfo(
                7010,
                notification,
                android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_DATA_SYNC
            ))
        } else {
            setForeground(ForegroundInfo(7010, notification))
        }
    }

    private fun updateForegroundNotification(displayName: String, progress: Int) {
        val channelId = "gemma_download_channel"
        val notification = NotificationCompat.Builder(applicationContext, channelId)
            .setSmallIcon(android.R.drawable.stat_sys_download)
            .setContentTitle("Downloading AI Engine")
            .setContentText("$displayName - $progress% complete")
            .setPriority(NotificationCompat.PRIORITY_LOW)
            .setOngoing(true)
            .setOnlyAlertOnce(true)
            .setProgress(100, progress, false)
            .build()

        val notificationManager = applicationContext.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        notificationManager.notify(7010, notification)
    }

    private fun showCompletionNotification(displayName: String) {
        val channelId = "gemma_download_channel"
        val notification = NotificationCompat.Builder(applicationContext, channelId)
            .setSmallIcon(android.R.drawable.stat_sys_download_done)
            .setContentTitle("AI Engine Ready")
            .setContentText("$displayName downloaded successfully. Features are now available.")
            .setPriority(NotificationCompat.PRIORITY_DEFAULT)
            .setAutoCancel(true)
            .build()

        val notificationManager = applicationContext.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        notificationManager.notify(7011, notification)
    }
}

package com.aipoweredgita.app.services

import android.app.Service
import android.content.Intent
import android.os.Binder
import android.os.IBinder
import android.util.Log
import kotlinx.coroutines.*
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import java.io.File

data class ModelDownloadProgress(
    val modelName: String = "",
    val currentBytes: Long = 0,
    val totalBytes: Long = 0,
    val percentage: Int = 0,
    val status: ModelDownloadStatus = ModelDownloadStatus.IDLE,
    val message: String = "",
    val error: String? = null
)

enum class ModelDownloadStatus {
    IDLE,
    DOWNLOADING,
    PROCESSING,
    COMPLETED,
    FAILED
}

class ModelDownloadService : Service() {
    private val TAG = "ModelDownloadService"
    private val binder = ModelDownloadBinder()
    private val serviceScope = CoroutineScope(Dispatchers.IO + Job())

    private val _downloadProgress = MutableStateFlow(ModelDownloadProgress())
    val downloadProgress: StateFlow<ModelDownloadProgress> = _downloadProgress.asStateFlow()

    private val _overallProgress = MutableStateFlow(0) // 0-100%
    val overallProgress: StateFlow<Int> = _overallProgress.asStateFlow()

    // Gemma models are handled by ModelDownloadManager and GemmaDownloadWorker.
    // This service is kept for legacy ServiceConnection compatibility only.
    private val models = emptyList<Pair<String, Long>>()

    inner class ModelDownloadBinder : Binder() {
        fun getService(): ModelDownloadService = this@ModelDownloadService
    }

    override fun onCreate() {
        super.onCreate()
        Log.d(TAG, "ModelDownloadService created")
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        Log.d(TAG, "onStartCommand called")
        return START_STICKY
    }

    override fun onBind(intent: Intent?): IBinder {
        return binder
    }

    /**
     * Start downloading all ML models in background
     * Non-blocking - returns immediately while downloads happen in background
     */
    fun startBackgroundDownload() {
        serviceScope.launch {
            try {
                downloadAllModels()
            } catch (e: Exception) {
                Log.e(TAG, "Error during background download: ${e.message}", e)
                _downloadProgress.value = _downloadProgress.value.copy(
                    status = ModelDownloadStatus.FAILED,
                    error = e.message ?: "Unknown error"
                )
            }
        }
    }

    /**
     * Download all models sequentially with progress tracking
     */
    private suspend fun downloadAllModels() {
        Log.d(TAG, "Starting downloadAllModels with ${models.size} models")

        _downloadProgress.value = _downloadProgress.value.copy(
            status = ModelDownloadStatus.DOWNLOADING,
            message = "Initializing model downloads..."
        )

        val modelDir = File(filesDir, "ml_models")
        if (!modelDir.exists()) {
            modelDir.mkdirs()
        }

        models.forEachIndexed { index, (modelName, estimatedSize) ->
            try {
                Log.d(TAG, "Starting download of model ${index + 1}/${models.size}: $modelName")

                _downloadProgress.value = _downloadProgress.value.copy(
                    modelName = modelName,
                    status = ModelDownloadStatus.DOWNLOADING,
                    message = "Downloading $modelName (${index + 1}/${models.size})...",
                    percentage = 0
                )

                downloadModel(modelDir, modelName, estimatedSize)
                Log.d(TAG, "Completed download of $modelName")

                // Update overall progress
                val overallPercent = ((index + 1) * 100) / models.size
                _overallProgress.value = overallPercent

                _downloadProgress.value = _downloadProgress.value.copy(
                    message = "Completed $modelName (${index + 1}/${models.size})",
                    percentage = overallPercent
                )
            } catch (e: Exception) {
                Log.e(TAG, "Error downloading $modelName: ${e.message}", e)
                // Continue with next model even if one fails
            }
        }

        _downloadProgress.value = _downloadProgress.value.copy(
            status = ModelDownloadStatus.COMPLETED,
            message = "All models downloaded successfully",
            percentage = 100
        )
        _overallProgress.value = 100

        Log.d(TAG, "All models downloaded successfully")
    }

    /**
     * Download single model with simulated progress
     * In production, replace with actual network download
     */
    private suspend fun downloadModel(
        modelDir: File,
        modelName: String,
        estimatedSize: Long
    ) = withContext(Dispatchers.IO) {
        val modelFile = File(modelDir, modelName)

        // Check if already downloaded
        if (modelFile.exists() && modelFile.length() > 0) {
            Log.d(TAG, "$modelName already exists, skipping download")
            _downloadProgress.value = _downloadProgress.value.copy(
                currentBytes = modelFile.length(),
                totalBytes = modelFile.length(),
                percentage = 100
            )
            return@withContext
        }

        // Simulate download with progress updates
        // In production: use OkHttp/Retrofit for real downloads
        val chunkSize = 1_000_000L  // 1MB chunks
        var downloadedBytes = 0L

        while (downloadedBytes < estimatedSize) {
            delay(100)  // Simulate network delay

            downloadedBytes += chunkSize
            if (downloadedBytes > estimatedSize) downloadedBytes = estimatedSize

            val percentage = ((downloadedBytes * 100) / estimatedSize).toInt()
            _downloadProgress.value = _downloadProgress.value.copy(
                currentBytes = downloadedBytes,
                totalBytes = estimatedSize,
                percentage = percentage
            )

            Log.d(TAG, "Downloaded $modelName: $percentage%")
        }

        // Log final percentage for this model
        Log.d(TAG, "Model download complete: $modelName at 100%")

        // Create the file after download completes
        if (!modelFile.exists()) {
            modelFile.createNewFile()
            // Write placeholder data in chunks to avoid OutOfMemory
            // (in production: actual model data would be streamed)
            try {
                modelFile.outputStream().use { output ->
                    val chunkSize = 1_000_000  // 1MB chunks
                    var bytesWritten = 0L
                    while (bytesWritten < estimatedSize) {
                        val remainingBytes = estimatedSize - bytesWritten
                        val currentChunk = if (remainingBytes < chunkSize) remainingBytes.toInt() else chunkSize
                        output.write(ByteArray(currentChunk))
                        bytesWritten += currentChunk
                    }
                }
                Log.d(TAG, "Successfully downloaded $modelName (${estimatedSize / (1024 * 1024)}MB written)")
            } catch (e: Exception) {
                Log.e(TAG, "Error writing $modelName to disk: ${e.message}", e)
                throw e
            }
        } else {
            Log.d(TAG, "Successfully downloaded $modelName")
        }
    }

    /**
     * Cancel ongoing downloads
     */
    fun cancelDownload() {
        serviceScope.coroutineContext.cancelChildren()
        _downloadProgress.value = _downloadProgress.value.copy(
            status = ModelDownloadStatus.IDLE,
            message = "Download cancelled"
        )
        Log.d(TAG, "Download cancelled")
    }

    /**
     * Check if models are already downloaded
     */
    fun areModelsDownloaded(): Boolean {
        val modelDir = File(filesDir, "ml_models")
        return models.all { (modelName, _) ->
            File(modelDir, modelName).exists()
        }
    }

    /**
     * Get total size of all models
     */
    fun getTotalModelSize(): Long {
        return models.sumOf { it.second }
    }

    /**
     * Get downloaded model size
     */
    fun getDownloadedModelSize(): Long {
        val modelDir = File(filesDir, "ml_models")
        return models.sumOf { (modelName, _) ->
            File(modelDir, modelName).length()
        }
    }

    override fun onDestroy() {
        super.onDestroy()
        serviceScope.cancel()
        Log.d(TAG, "ModelDownloadService destroyed")
    }
}

package com.aipoweredgita.app.services

import android.content.Context
import android.os.Build
import android.util.Log
import androidx.annotation.RequiresApi
import androidx.core.app.NotificationCompat
import android.content.pm.ServiceInfo
import androidx.work.*
import com.aipoweredgita.app.database.GitaDatabase
import com.aipoweredgita.app.repository.OfflineCacheRepository
import kotlinx.coroutines.flow.collect
import java.util.concurrent.TimeUnit

class OfflineVerseDownloadWorker(
    appContext: Context,
    params: WorkerParameters
) : CoroutineWorker(appContext, params) {

    private val tag = "OfflineVerseWorker"

    override suspend fun doWork(): Result {
        return try {
            val db = GitaDatabase.getDatabase(applicationContext)
            val repo = OfflineCacheRepository(db.cachedVerseDao())
            val notifications = OfflineDownloadNotificationManager(applicationContext)

            // Show background in-progress notification
            try { notifications.showInProgressNotification() } catch (_: Exception) {}

            // Promote to foreground for long-running work (Android 12+ requirements)
            try {
                val notification = NotificationCompat.Builder(applicationContext, "offline_download_channel")
                    .setSmallIcon(com.aipoweredgita.app.R.drawable.ic_menu_book)
                    .setContentTitle("Downloading verses")
                    .setContentText("Download is running in background")
                    .setOngoing(true)
                    .setOnlyAlertOnce(true)
                    .build()
                // Modern approach for foreground service compatibility
                // For Android 12+ (S+) use setForeground(), for older versions use setForegroundAsync()
                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
                    setForeground(ForegroundInfo(7003, notification, ServiceInfo.FOREGROUND_SERVICE_TYPE_DATA_SYNC))
                } else {
                    setForegroundAsync(ForegroundInfo(7003, notification))  // For backward compatibility with older Android versions
                }
            } catch (_: Exception) { }

            // Collect progress until completion
            repo.downloadAllVerses().collect { progress ->
                setProgressAsync(
                    workDataOf(
                        "current" to progress.current,
                        "total" to progress.total,
                        "percentage" to progress.percentage,
                        "status" to progress.status.name
                    )
                )
            }

            // Cancel in-progress and show completion/incomplete notifications
            try { notifications.cancelInProgressNotification() } catch (_: Exception) {}

            return if (repo.isFullyCached()) {
                try { notifications.showCompletionNotification() } catch (_: Exception) {}
                Result.success()
            } else {
                val missing = try { repo.getMissingVerses() } catch (_: Exception) { emptyList() }
                try { notifications.showIncompleteNotification(missing.size) } catch (_: Exception) {}
                // Succeed but notify incomplete to let user retry
                Result.success()
            }
        } catch (e: Exception) {
            Log.e(tag, "Offline verse download failed: ${e.message}", e)
            if (runAttemptCount < 3) Result.retry() else Result.failure()
        }
    }

    companion object {
        private const val WORK_NAME = "offline_verse_download"

        fun scheduleBackgroundDownload(context: Context) {
            val constraints = Constraints.Builder()
                .setRequiredNetworkType(
                    if (com.aipoweredgita.app.util.FeatureFlags.DOWNLOADS_REQUIRE_UNMETERED)
                        NetworkType.UNMETERED else NetworkType.CONNECTED
                )
                .setRequiresCharging(com.aipoweredgita.app.util.FeatureFlags.DOWNLOADS_REQUIRE_CHARGING)
                .setRequiresBatteryNotLow(com.aipoweredgita.app.util.FeatureFlags.DOWNLOADS_REQUIRE_BATTERY_NOT_LOW)
                .build()

            val request = OneTimeWorkRequestBuilder<OfflineVerseDownloadWorker>()
                .setConstraints(constraints)
                .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 15, TimeUnit.MINUTES)
                .build()

            WorkManager.getInstance(context).enqueueUniqueWork(
                WORK_NAME,
                ExistingWorkPolicy.KEEP,
                request
            )
        }

        fun cancel(context: Context) {
            WorkManager.getInstance(context).cancelUniqueWork(WORK_NAME)
        }
    }
}

