        targetValue = timerColor,
        animationSpec = com.aipoweredgita.app.ui.theme.MotionTokens.springSmooth<androidx.compose.ui.graphics.Color>(),
        label = "timer_color"
    )

    Surface(
        modifier = Modifier.fillMaxWidth(),
