sealed class OptionVisualState {
    object Idle : OptionVisualState()
    object Selected : OptionVisualState()
    object Correct : OptionVisualState()
    object Wrong : OptionVisualState()
}

@Composable
fun AnimatedOptionCard(
    text: String,
    state: OptionVisualState,
    enabled: Boolean,
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
) {
    val isDark = MaterialTheme.colorScheme.background.luminance() < 0.5f
    val containerColor = when (state) {
        OptionVisualState.Idle -> MaterialTheme.colorScheme.surfaceVariant
        OptionVisualState.Selected -> MaterialTheme.colorScheme.primary.copy(alpha = 0.2f)
        OptionVisualState.Correct -> Forest.copy(alpha = if (isDark) 0.3f else 0.15f)
        OptionVisualState.Wrong -> MaterialTheme.colorScheme.error.copy(alpha = if (isDark) 0.3f else 0.1f)
    }

    val borderColor = when (state) {
        OptionVisualState.Idle -> MaterialTheme.colorScheme.outline.copy(alpha = 0.2f)
        OptionVisualState.Selected -> MaterialTheme.colorScheme.primary
        OptionVisualState.Correct -> MaterialTheme.colorScheme.secondary
        OptionVisualState.Wrong -> MaterialTheme.colorScheme.error
    }

    val contentColor = when (state) {
        OptionVisualState.Idle -> MaterialTheme.colorScheme.onSurface
        OptionVisualState.Selected -> MaterialTheme.colorScheme.primary
        OptionVisualState.Correct -> if (isDark) MaterialTheme.colorScheme.secondary else ForestMid
        OptionVisualState.Wrong -> MaterialTheme.colorScheme.error
    }

    val animatedColor = animateColorAsState(targetValue = containerColor, label = "cardColor")
    val animatedBorderColor = animateColorAsState(targetValue = borderColor, label = "borderColor")

    val scale = remember { Animatable(1f) }
    val offsetY = remember { Animatable(0f) }
    val offsetX = remember { Animatable(0f) }
    val flashAlpha = remember { Animatable(0f) }

    LaunchedEffect(state) {
        when (state) {
            OptionVisualState.Selected, OptionVisualState.Correct, OptionVisualState.Wrong -> {
                scale.snapTo(1f)
                offsetY.snapTo(0f)

                launch {
                    scale.animateTo(1.04f, spring(dampingRatio = Spring.DampingRatioLowBouncy, stiffness = Spring.StiffnessLow))
                }

                launch {
                    offsetY.animateTo(-8f, spring(dampingRatio = Spring.DampingRatioLowBouncy, stiffness = Spring.StiffnessLow))
                    offsetY.animateTo(0f, spring(dampingRatio = Spring.DampingRatioLowBouncy, stiffness = Spring.StiffnessMedium))
                }

                if (state == OptionVisualState.Wrong) {
                    offsetX.snapTo(0f)
                    launch {
                        offsetX.animateTo(0f, keyframes {
                            durationMillis = 300
                            0f at 0
                            8f at 50
                            -8f at 100
                            5f at 150
                            -5f at 200
                            0f at 300
                        })
                    }
                }
            }
            else -> {
                launch { scale.animateTo(1f) }
                launch { offsetX.animateTo(0f) }
                launch { offsetY.animateTo(0f) }
            }
        }
    }

    Card(
        modifier = modifier
            .fillMaxWidth()
            .scale(scale.value)
            .offset { IntOffset(offsetX.value.roundToInt(), offsetY.value.roundToInt()) }
            .padding(vertical = 4.dp)
            .let {
                if (enabled) {
                    it.clickable(
                        interactionSource = remember { MutableInteractionSource() },
                        indication = null
                    ) { onClick() }
                } else it
            },
        colors = CardDefaults.cardColors(containerColor = animatedColor.value),
        shape = RoundedCornerShape(16.dp),
        border = BorderStroke(1.5.dp, animatedBorderColor.value),
        elevation = CardDefaults.cardElevation(defaultElevation = 0.dp)
    ) {
        Box(
            modifier = Modifier.padding(18.dp),
            contentAlignment = Alignment.CenterStart
        ) {
            Text(
                text = text,
                style = MaterialTheme.typography.bodyLarge,
                color = contentColor,
                fontWeight = if (state != OptionVisualState.Idle) FontWeight.Bold else FontWeight.Normal,
                textAlign = TextAlign.Start,
                modifier = Modifier.fillMaxWidth()
            )
        }
    }
}

package com.aipoweredgita.app.util

import android.util.Log
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch

/**
 * Throttled batch database writer to reduce I/O pressure.
 * Instead of writing to database on every verse read, batches multiple reads
 * and writes them together.
 *
 * Benefits:
 * - Reduces database writes by 50-90%
 * - Prevents ANR from database locks
 * - Improves app responsiveness
 * - Maintains data consistency
 *
 * Usage:
 * throttledUpdater.trackVerseRead(chapter, verse)  // Called frequently
 */
class ThrottledDatabaseUpdater(
    private val batchSize: Int = 10,
    private val flushIntervalMs: Long = 5000L,  // 5 seconds
    private val onBatchWrite: suspend (List<VerseRead>) -> Unit
) {
    private val TAG = "ThrottledUpdater"
    private val batch = mutableListOf<VerseRead>()
    private val retryCount = mutableMapOf<String, Int>()
    private var flushJob: Job? = null
    private val scope = CoroutineScope(Dispatchers.IO)
    private val maxRetries = 3

    /**
     * Track a verse read - batched and throttled
     */
    fun trackVerseRead(chapter: Int, verse: Int) {
        synchronized(batch) {
            batch.add(VerseRead(chapter, verse))
            Log.d(TAG, "Queued: Ch$chapter:V$verse (batch size: ${batch.size}/$batchSize)")

            // Auto-flush if batch size exceeded
            if (batch.size >= batchSize) {
                Log.d(TAG, "Batch size limit reached, flushing immediately")
                flush()
            } else {
                // Schedule flush if not already scheduled
                if (flushJob?.isCompleted != false) {
                    scheduleFlush()
                }
            }
        }
    }

    /**
     * Force immediate flush of pending writes
     */
    fun flush() {
        synchronized(batch) {
            if (batch.isEmpty()) {
                Log.d(TAG, "No pending writes to flush")
                return
            }

            val toBatch = batch.toList()
            batch.clear()
            flushJob?.cancel()
            flushJob = null

            Log.d(TAG, "Flushing ${toBatch.size} verse reads to database")
            scope.launch {
                try {
                    onBatchWrite(toBatch)
                    // Clear retry counts on success
                    toBatch.forEach { retryCount.remove("${it.chapter}:${it.verse}") }
                    Log.d(TAG, "Successfully flushed ${toBatch.size} reads")
                } catch (e: Exception) {
                    Log.e(TAG, "Error flushing batch: ${e.message}")
                    // Re-queue on failure with retry limit
                    val eligible = toBatch.filter { verse ->
                        val key = "${verse.chapter}:${verse.verse}"
                        val count = retryCount.getOrDefault(key, 0)
                        if (count < maxRetries) {
                            retryCount[key] = count + 1
                            true
                        } else {
                            Log.e(TAG, "Dropping ${key} after $maxRetries retries")
                            retryCount.remove(key)
                            false
                        }
                    }
                    if (eligible.isNotEmpty()) {
                        synchronized(batch) {
                            batch.addAll(0, eligible)
                        }
                    }
                }
            }
        }
    }

    /**
     * Schedule a delayed flush if one isn't already scheduled
     */
    private fun scheduleFlush() {
        if (flushJob != null && !flushJob!!.isCompleted) {
            return  // Already scheduled
        }

        flushJob = scope.launch {
            delay(flushIntervalMs)
            flush()
        }
        Log.d(TAG, "Flush scheduled in ${flushIntervalMs}ms")
    }

    /**
     * Cleanup - flush all pending writes
     */
    fun cleanup() {
        Log.d(TAG, "Cleaning up - flushing pending writes")
        flush()
        scope.launch {
            delay(500)  // Give time for flush to complete
            scope.coroutineContext[Job]?.cancel()
        }
    }

    data class VerseRead(
        val chapter: Int,
        val verse: Int
    )
}

/**
 * Query-level caching for frequently accessed database records.
 * Caches recent reads to avoid redundant database queries.
 */
class DatabaseQueryCache(private val maxSize: Int = 1000) {
    private val TAG = "QueryCache"
    private val cache = object : android.util.LruCache<String, CachedRecord>(maxSize) {
        override fun sizeOf(key: String, value: CachedRecord): Int = 1  // Count by entries
    }

    fun get(key: String): Any? {
        val record = cache.get(key)
        return if (record != null && !record.isExpired()) {
            Log.d(TAG, "Cache hit: $key")
            record.value
        } else {
            Log.d(TAG, "Cache miss: $key")
            null
        }
    }

    fun put(key: String, value: Any, ttlMs: Long = 60000) {
        cache.put(key, CachedRecord(value, System.currentTimeMillis() + ttlMs))
        Log.d(TAG, "Cached: $key (TTL: ${ttlMs}ms)")
    }

    fun invalidate(key: String) {
        cache.remove(key)
        Log.d(TAG, "Cache invalidated: $key")
    }

    fun clear() {
        cache.evictAll()
        Log.d(TAG, "Cache cleared")
    }

    private data class CachedRecord(
        val value: Any,
        val expiresAt: Long
    ) {
        fun isExpired() = System.currentTimeMillis() > expiresAt
    }
}

package com.aipoweredgita.app.util

import android.util.Log

sealed class SafeResult<out T> {
    data class Success<T>(val data: T) : SafeResult<T>()
    data class Error(val message: String, val throwable: Throwable? = null) : SafeResult<Nothing>()
}

object SafeCall {
    suspend fun <T> run(
        tag: String = "SafeCall",
        operation: String = "",
        block: suspend () -> T
    ): SafeResult<T> {
        return try {
            SafeResult.Success(block())
        } catch (e: Exception) {
            Log.w(tag, "Failed${if (operation.isNotEmpty()) " [$operation]" else ""}: ${e.message}", e)
            SafeResult.Error(e.message ?: "Unknown error", e)
        }
    }
}

package com.aipoweredgita.app.util

object TimeUtils {
    fun formatTime(seconds: Long): String {
        val h = seconds / 3600
        val m = (seconds % 3600) / 60
        val s = seconds % 60
        return when {
            h > 0 -> "${h}h ${m}m"
            m > 0 -> "${m}m ${s}s"
            else -> "${s}s"
        }
    }

    fun formatTimeCompact(seconds: Long): String {
        val h = seconds / 3600
        val m = (seconds % 3600) / 60
        val s = seconds % 60
        return when {
            h > 0 -> "${h}h ${m}m"
            m > 0 -> "${m}m ${s}s"
            else -> "${s}s"
        }
    }
}

package com.aipoweredgita.app.util

object StringUtils {
    fun clean(s: String?): String? {
        if (s == null) return null
        var t = s
        val map = mapOf(
            "â€¢" to "•", "â€“" to "–", "â€”" to "—", "â€˜" to "‘", "â€™" to "’",
            "â€œ" to "“", "â€ " to "”", "â€¦" to "…", "Ã—" to "×", "Â" to "",
            "ðŸ" to "", "dY" to "", "" to ""
        )
        for ((k, v) in map) t = t?.replace(k, v)
        t = t?.replace(Regex("[\\u0000-\\u001F\\u007F]"), "")
        return t
    }
}

package com.aipoweredgita.app.util

import android.util.LruCache
import com.aipoweredgita.app.data.GitaVerse

/**
 * Bounded memory cache for verses using LRU eviction.
 * Prevents unbounded memory growth from accumulated verse objects.
 *
 * Automatically evicts oldest verses when memory limit is reached.
 * Max size: 5MB (approximately 10,000 verses)
 */
class VerseCacheManager(maxSizeKb: Int = 5000) {

    private val cache = object : LruCache<String, GitaVerse>(maxSizeKb) {
        override fun sizeOf(key: String, value: GitaVerse): Int {
            // Estimate verse size: verse text + translation + purport + metadata
            val verseSize = value.verse.length
            val translationSize = value.translation.length
            val purportSize = value.purport.sumOf { it.length }
            return verseSize + translationSize + purportSize + 200  // 200 bytes for metadata
        }
    }

    /**
     * Get verse from cache
     * Returns null if not cached or evicted
     */
    fun get(chapter: Int, verse: Int): GitaVerse? {
        return cache.get(makeKey(chapter, verse))
    }

    /**
     * Put verse in cache
     * Automatically evicts oldest verses if max size exceeded
     */
    fun put(chapter: Int, verse: Int, verseData: GitaVerse) {
        cache.put(makeKey(chapter, verse), verseData)
    }

    /**
     * Get from cache or fetch if missing
     */
    suspend fun getOrFetch(
        chapter: Int,
        verse: Int,
        fetch: suspend () -> GitaVerse?
    ): GitaVerse? {
        val cached = get(chapter, verse)
        if (cached != null) return cached

        val fetched = fetch()
        if (fetched != null) {
            put(chapter, verse, fetched)
        }
        return fetched
    }

    /**
     * Clear all cached verses
     * Called on ViewModel cleanup to guarantee memory release
     */
    fun clear() {
        cache.evictAll()
    }

    /**
     * Get cache statistics for debugging
     */
    fun getStats(): String {
        return "VerseCacheManager: size=${cache.size()}KB, max=${cache.maxSize()}KB"
    }

    private fun makeKey(chapter: Int, verse: Int) = "$chapter:$verse"
}

package com.aipoweredgita.app.util

import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch

class TimeTracker(
    private val scope: CoroutineScope,
    private val onTimeUpdate: suspend (seconds: Long) -> Unit
) {
    private var startTime: Long = 0
    private var totalSeconds: Long = 0
    private var trackingJob: Job? = null

    fun start() {
        if (trackingJob?.isActive == true) return

        startTime = System.currentTimeMillis()

        trackingJob = scope.launch {
            while (isActive) {
                delay(10000) // Update every 10 seconds
                val elapsed = (System.currentTimeMillis() - startTime) / 1000
                if (elapsed >= 10) {
                    totalSeconds += elapsed
                    onTimeUpdate(elapsed)
                    startTime = System.currentTimeMillis()
                }
            }
        }
    }

    fun stop() {
        trackingJob?.cancel()
        trackingJob = null

        // Save any remaining time
        val elapsed = (System.currentTimeMillis() - startTime) / 1000
        if (elapsed > 0) {
            totalSeconds += elapsed
            scope.launch {
                onTimeUpdate(elapsed)
            }
        }
    }

    fun getTotalSeconds(): Long = totalSeconds
}

