/**
 * Quiz ViewModel with UDF pattern
 * Uses constructor injection via Hilt
 */
@HiltViewModel
class QuizViewModel @Inject constructor(
    private val statsRepository: StatsRepository,
    private val quizRepository: QuizRepository,
    private val quizQuestionRepository: QuizQuestionRepository,
    private val offlineCacheRepository: OfflineCacheRepository,
    private val quizPreferences: QuizPreferences,
    private val application: Application
) : ViewModel() {

    // Single UI state
    private val _uiState = MutableStateFlow(QuizUiState())
    val uiState: StateFlow<QuizUiState> = _uiState.asStateFlow()

    // One-time side effects
    private val _sideEffect = MutableSharedFlow<QuizSideEffect>()
    val sideEffect: SharedFlow<QuizSideEffect> = _sideEffect.asSharedFlow()

    // Legacy quiz state for compatibility
    private val _quizState = MutableStateFlow(QuizState())
    val quizState: StateFlow<QuizState> = _quizState.asStateFlow()

    private val mlManager = HuggingFaceMLManager(application)
    private val difficultyEngine = AdaptiveDifficultyEngine()
    private var userState = AdaptiveDifficultyEngine.UserState()
    private val eloSystem = EloRatingSystem()
    private val irtEngine = ItemResponseTheoryEngine()
    private var studentEntity = ELOEntity(id = "student", type = EntityType.STUDENT)
    private var studentAbility = StudentAbility(studentId = "student")
    private var quizStartTime: Long = 0
    private var timerJob: kotlinx.coroutines.Job? = null
    // Track question IDs asked in the current quiz session to prevent repeats
    private val sessionAskedIds = mutableSetOf<Int>()

    init {
        viewModelScope.launch {
            _uiState.update { it.copy(isLoading = true) }
            val prefs = application.getSharedPreferences("quiz_prefs", android.content.Context.MODE_PRIVATE)
            userState = AdaptiveDifficultyEngine.loadState(prefs)
            studentEntity = ELOEntity(id = "student", rating = 1500.0 + (userState.skillLevel - 5) * 50.0, type = EntityType.STUDENT)
            studentAbility = StudentAbility(studentId = "student", theta = (userState.skillLevel - 5) * 0.5)
            val success = com.aipoweredgita.app.ml.TranslationManager().downloadModelsIfNeeded()
            if (!success) {
                _sideEffect.emit(QuizSideEffect.ShowError("Failed to download translation models"))
            }
            mlManager.initializeModels()
            _uiState.update { it.copy(isLoading = false) }
        }
    }

    /**
     * Handle events from the UI
     */
    fun onEvent(event: QuizEvent) {
        when (event) {
            is QuizEvent.SelectAnswer -> selectAnswer(event.answer)
            is QuizEvent.ConfirmAnswer -> confirmAnswer()
            is QuizEvent.NextQuestion -> loadNextQuestion()
            is QuizEvent.FinishQuiz -> finishQuiz()
            is QuizEvent.RestartQuiz -> restartQuiz()
            is QuizEvent.SetQuizConfig -> setQuizConfig(event.questionCount, event.language)
        }
    }

    /**
     * Set quiz configuration
     */
    private fun setQuizConfig(questionCount: Int, language: String) {
        _quizState.value = com.aipoweredgita.app.data.QuizState(maxQuestions = questionCount, language = language)
        _uiState.value = QuizUiState()
        quizStartTime = System.currentTimeMillis()
        sessionAskedIds.clear()
        viewModelScope.launch {
            quizPreferences.clearQuizState()
        }
    }

    /**
     * Load next question
     */
    fun loadNextQuestion() {
        viewModelScope.launch {
            // Guard: don't load if we've already reached maxQuestions
            val current = _quizState.value
            if (current.totalQuestions >= current.maxQuestions) {
                return@launch
            }
            _uiState.update { it.copy(isLoading = true, error = null) }
            _quizState.value = _quizState.value.copy(isLoading = true, error = null)

            try {
                // Fetch next question from DB using repository
                // Over-fetch to have a pool to filter session-asked questions
                val limit = 1
                val diff = userState.skillLevel
                val minDiff = (diff - 2).coerceAtLeast(1)
                val maxDiff = (diff + 2).coerceAtMost(10)
                val fetchLimit = maxOf(limit, 10)
                val candidates = quizQuestionRepository.getNextQuestions(minDiff, maxDiff, fetchLimit)

                // Filter out questions already asked in this quiz session
                val available = candidates.filter { it.id !in sessionAskedIds }

                if (available.isNotEmpty()) {
                    val q = available.first()
                    sessionAskedIds.add(q.id)
                    val options = listOf(q.optionA, q.optionB, q.optionC, q.optionD).filter { it.isNotBlank() }
                    val correctAnswerIndex = when (q.correctAnswer.trim().uppercase()) {
                        "A" -> 0
                        "B" -> 1
                        "C" -> 2
                        "D" -> 3
                        else -> options.indexOf(q.correctAnswer).takeIf { it >= 0 } ?: 0
                    }
                    val verseObj = GitaVerse(chapterNo = q.chapter, verseNo = q.verse)
                    val currentQuizQuestion = com.aipoweredgita.app.data.QuizQuestion(
                        verse = verseObj,
                        question = q.question,
                        options = options,
                        correctAnswerIndex = correctAnswerIndex,
                        explanation = q.explanation
                    )

                    // Mark question as asked so it won't be returned again soon
                    quizQuestionRepository.markAsAsked(q.id)

                    val newTotal = _quizState.value.totalQuestions + 1
                    _uiState.update { it.copy(isLoading = false, error = null, selectedAnswer = null, isAnswerRevealed = false) }
                    _quizState.value = _quizState.value.copy(
                        isLoading = false,
                        error = null,
                        currentQuestion = currentQuizQuestion,
                        selectedAnswerIndex = null,
                        showAnswer = false,
                        showCorrectAnswer = false,
                        totalQuestions = newTotal
                    )
                    startTimer()
                } else {
                    _uiState.update { it.copy(isLoading = false, error = "No questions available in the question bank.") }
                    _quizState.value = _quizState.value.copy(isLoading = false, error = "No questions available in the question bank.")
                }
            } catch (e: Exception) {
                _uiState.update { it.copy(isLoading = false, error = e.message) }
                _quizState.value = _quizState.value.copy(isLoading = false, error = e.message)
                _sideEffect.emit(QuizSideEffect.ShowError(e.message ?: "Failed to load question"))
            }
        }
    }

    /**
     * Select an answer
     */
    private fun selectAnswer(answer: String) {
        stopTimer()
        _uiState.update { it.copy(selectedAnswer = answer) }
        _quizState.value = _quizState.value.copy(selectedAnswerIndex = _quizState.value.currentQuestion?.options?.indexOf(answer))
    }

    /**
     * Confirm answer with known correctness (used by MCQ flow)
     */
    fun confirmAnswerResult(isCorrect: Boolean) {
        stopTimer()
        _uiState.update {
            it.copy(
                isAnswerRevealed = true,
                score = if (isCorrect) it.score + 1 else it.score
            )
        }

        _quizState.value = _quizState.value.copy(
            showAnswer = true,
            showCorrectAnswer = isCorrect,
            score = if (isCorrect) _quizState.value.score + 1 else _quizState.value.score
        )

        difficultyEngine.updateDifficulty(userState, isCorrect, 0L)

        // Update Elo ratings
        val questionEntity = ELOEntity(id = "q_${_quizState.value.totalQuestions}", type = EntityType.QUESTION)
        eloSystem.updateRatings(studentEntity, questionEntity, if (isCorrect) 1.0 else 0.0)

        // Update IRT ability
        val itemParams = ItemParameters(difficulty = (userState.skillLevel).toDouble(), discrimination = 1.0)
        studentAbility = irtEngine.updateAbility(studentAbility, listOf(itemParams to isCorrect))

        saveProgress()
    }

    /**
     * Confirm the selected answer
     */
    private fun confirmAnswer() {
        val currentQuestion = _quizState.value.currentQuestion ?: return
        val selectedAnswer = _uiState.value.selectedAnswer ?: return

        val isCorrect = selectedAnswer == currentQuestion.options?.getOrNull(currentQuestion.correctAnswerIndex)

        _uiState.update { 
            it.copy(
                isAnswerRevealed = true,
                score = if (isCorrect) it.score + 1 else it.score
            ) 
        }

        _quizState.value = _quizState.value.copy(
            showAnswer = true,
            showCorrectAnswer = isCorrect,
            score = if (isCorrect) _quizState.value.score + 1 else _quizState.value.score
        )

        // Update difficulty
        difficultyEngine.updateDifficulty(userState, isCorrect, 0L)

        // Update Elo ratings
        val questionEntity2 = ELOEntity(id = "q_${_quizState.value.totalQuestions}", type = EntityType.QUESTION)
        eloSystem.updateRatings(studentEntity, questionEntity2, if (isCorrect) 1.0 else 0.0)

        // Update IRT ability
        val itemParams2 = ItemParameters(difficulty = (userState.skillLevel).toDouble(), discrimination = 1.0)
        studentAbility = irtEngine.updateAbility(studentAbility, listOf(itemParams2 to isCorrect))

        saveProgress()
    }

    /**
     * Finish the quiz
     */
    private fun finishQuiz() {
        stopTimer()
        viewModelScope.launch {
            val currentState = _quizState.value
            val timeSpentSeconds = if (quizStartTime > 0) {
                (System.currentTimeMillis() - quizStartTime) / 1000
            } else 0L

            val quizAttempt = QuizAttempt(
                score = currentState.score,
                totalQuestions = currentState.totalQuestions,
                timeSpentSeconds = timeSpentSeconds,
                quizType = currentState.quizType
            )

            try {
                val result = quizRepository.saveQuizAttemptWithStats(
                    attempt = quizAttempt,
                    score = currentState.score,
                    totalQuestions = currentState.totalQuestions,
                    quizType = currentState.quizType
                )

                _uiState.update { it.copy(isQuizCompleted = true, coinsEarned = result.third) }
                _quizState.value = _quizState.value.copy(
                    isQuizComplete = true,
                    coinsEarned = result.third,
                    totalTimeSeconds = timeSpentSeconds
                )

                _sideEffect.emit(QuizSideEffect.QuizCompleted(
                    score = currentState.score,
                    total = currentState.totalQuestions,
                    coinsEarned = result.third
                ))

                if (result.first && result.second != null) {
                    val level = result.second ?: return@launch
                    com.aipoweredgita.app.notifications.YogaLevelUpNotificationManager.showLevelUpNotification(
                        application,
                        level
                    )
                }

                quizPreferences.clearQuizState()
            } catch (e: Exception) {
                _sideEffect.emit(QuizSideEffect.ShowError(e.message ?: "Failed to save quiz results"))
            }
        }
    }

    /**
     * Restart the quiz
     */
    fun restartQuiz() {
        val currentMaxQuestions = _quizState.value.maxQuestions
        val currentLanguage = _quizState.value.language
        _quizState.value = QuizState(maxQuestions = currentMaxQuestions, language = currentLanguage, isLoading = true)
        _uiState.value = QuizUiState(isLoading = true)
        quizStartTime = System.currentTimeMillis()
        sessionAskedIds.clear()

        viewModelScope.launch {
            quizPreferences.clearQuizState()
            loadNextQuestion()
        }
    }

    // Backward compatibility methods for existing UI code
    fun setQuizLimit(maxQuestions: Int) {
        val currentLanguage = _quizState.value.language
        _quizState.value = com.aipoweredgita.app.data.QuizState(maxQuestions = maxQuestions, language = currentLanguage)
        _uiState.value = QuizUiState()
        quizStartTime = System.currentTimeMillis()
        viewModelScope.launch {
            quizPreferences.clearQuizState()
        }
    }

    fun setQuizLanguage(quizLanguage: String) {
        _quizState.value = _quizState.value.copy(language = quizLanguage)
    }

    fun submitOpenEndedAnswer(text: String) {
        val currentQuestion = _quizState.value.currentQuestion ?: return
        _quizState.value = _quizState.value.copy(openEndedAnswer = text)
        val matched = currentQuestion.rubricKeywords.count { kw -> text.lowercase().contains(kw.lowercase()) }
        val passThreshold = maxOf(1, currentQuestion.rubricKeywords.size / 2)
        val isPass = matched >= passThreshold
        _quizState.value = _quizState.value.copy(showAnswer = true, showCorrectAnswer = isPass)
        if (isPass) {
            _quizState.value = _quizState.value.copy(score = _quizState.value.score + 1)
        }
    }

    fun selectAnswer(index: Int) {
        _quizState.value = _quizState.value.copy(selectedAnswerIndex = index)
    }

    fun revealAnswer() {
        _quizState.value = _quizState.value.copy(showCorrectAnswer = true)
    }

    fun loadNextQuestionLegacy() {
        loadNextQuestion()
    }

    fun resetQuiz() {
        val currentMaxQuestions = _quizState.value.maxQuestions
        val currentLanguage = _quizState.value.language
        _quizState.value = QuizState(maxQuestions = currentMaxQuestions, language = currentLanguage, isLoading = true)
        _uiState.value = QuizUiState(isLoading = true)
        quizStartTime = System.currentTimeMillis()
        viewModelScope.launch {
            quizPreferences.clearQuizState()
            loadNextQuestion()
        }
    }

    fun exitQuiz() {
        val currentState = _quizState.value
        if (currentState.score > 0 && currentState.totalQuestions > 0) {
            viewModelScope.launch {
                try {
                    val timeSpentSeconds = if (quizStartTime > 0) {
                        (System.currentTimeMillis() - quizStartTime) / 1000
                    } else 0L
                    val quizAttempt = QuizAttempt(
                        score = currentState.score,
                        totalQuestions = currentState.totalQuestions,
                        timeSpentSeconds = timeSpentSeconds,
                        quizType = currentState.quizType
                    )
                    quizRepository.saveQuizAttemptWithStats(
                        attempt = quizAttempt,
                        score = currentState.score,
                        totalQuestions = currentState.totalQuestions,
                        quizType = currentState.quizType
                    )
                } catch (e: Exception) {
                    _sideEffect.emit(QuizSideEffect.ShowError(e.message ?: "Failed to save quiz"))
                }
            }
        }
        viewModelScope.launch { quizPreferences.clearQuizState() }
    }

    private fun saveProgress() {
        val state = _quizState.value
        viewModelScope.launch {
            try {
                val usedQuestions = sessionAskedIds.map { it.toString() }.toSet()
                quizPreferences.saveQuizState(
                    score = state.score,
                    totalQuestions = state.totalQuestions,
                    maxQuestions = state.maxQuestions,
                    startTime = quizStartTime,
                    usedQuestions = usedQuestions
                )
            } catch (_: Exception) { }
        }
    }

    fun setLanguage(lang: String) {
        setQuizLanguage(lang)
    }

    // Backward compatibility - events flow for existing UI
    private val _events = MutableSharedFlow<String>()
    val events: SharedFlow<String> = _events.asSharedFlow()

    fun setError(message: String) {
        _quizState.value = _quizState.value.copy(isLoading = false, error = message)
    }

    fun recordQuestionFeedback(questionId: Int, rating: Float, wasSkipped: Boolean = false, changedAnswer: Boolean = false) {
        // Stub for backward compatibility
    }

    override fun onCleared() {
        super.onCleared()
        val prefs = application.getSharedPreferences("quiz_prefs", android.content.Context.MODE_PRIVATE)
        AdaptiveDifficultyEngine.saveState(userState, prefs)
        mlManager.close()
    }

    private fun startTimer() {
        timerJob?.cancel()
        // Give more time for open-ended questions
        val question = _quizState.value.currentQuestion
        val isOpenEnded = question?.type == com.aipoweredgita.app.data.QuestionType.ESSAY ||
                question?.type == com.aipoweredgita.app.data.QuestionType.APPLICATION
        val timeLimit = if (isOpenEnded) 60 else 30
        _quizState.value = _quizState.value.copy(questionTimeLeftSeconds = timeLimit, isTimerRunning = true)
        timerJob = viewModelScope.launch {
            while (_quizState.value.questionTimeLeftSeconds > 0) {
                kotlinx.coroutines.delay(1000)
                val current = _quizState.value.questionTimeLeftSeconds
                if (current > 0) {
                    _quizState.value = _quizState.value.copy(questionTimeLeftSeconds = current - 1)
                }
            }
            // Time ran out — mark answer as revealed (wrong since no selection)
            stopTimer()
            val state = _quizState.value
            if (!state.showAnswer) {
                _uiState.update { it.copy(isAnswerRevealed = true) }
                _quizState.value = state.copy(showAnswer = true, showCorrectAnswer = false)
            }
        }
    }

    private fun stopTimer() {
        timerJob?.cancel()
        _quizState.value = _quizState.value.copy(isTimerRunning = false)
    }
}

package com.aipoweredgita.app.viewmodel

import android.app.Application
import android.util.Log
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.aipoweredgita.app.data.GitaVerse
import com.aipoweredgita.app.database.GitaDatabase
import com.aipoweredgita.app.domain.model.NormalModeEvent
import com.aipoweredgita.app.domain.model.NormalModeSideEffect
import com.aipoweredgita.app.domain.model.NormalModeUiState
import com.aipoweredgita.app.repository.GitaRepository
import com.aipoweredgita.app.repository.StatsRepository
import com.aipoweredgita.app.repository.FavoriteRepository
import com.aipoweredgita.app.repository.OfflineCacheRepository
import com.aipoweredgita.app.repository.YogaProgressionRepository
import com.aipoweredgita.app.util.TimeTracker
import com.aipoweredgita.app.util.GitaConstants
import com.aipoweredgita.app.util.ThrottledDatabaseUpdater
import com.aipoweredgita.app.repository.ModeType
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import kotlinx.coroutines.Dispatchers
import javax.inject.Inject

@HiltViewModel
class NormalModeViewModel @Inject constructor(
    private val statsRepository: StatsRepository,
    private val favoriteRepository: FavoriteRepository,
    private val offlineCacheRepository: OfflineCacheRepository,
    private val yogaProgressionRepository: YogaProgressionRepository,
    private val application: Application
) : ViewModel() {
    private val TAG = "NormalModeViewModel"
    private val _uiState = MutableStateFlow(NormalModeUiState())
    val uiState: StateFlow<NormalModeUiState> = _uiState.asStateFlow()

    private val _sideEffect = MutableSharedFlow<NormalModeSideEffect>()
    val sideEffect: SharedFlow<NormalModeSideEffect> = _sideEffect.asSharedFlow()

    // Backward compatibility for existing UI
    val state: StateFlow<NormalModeUiState> = uiState
    val events: SharedFlow<String> = MutableSharedFlow<String>() // Stub for backward compatibility if needed

    private val database = GitaDatabase.getDatabase(application)
    private val readVerseDao = database.readVerseDao()
    private val language = GitaConstants.DEFAULT_LANGUAGE
    private val gitaRepository = GitaRepository()
    private var lastRequestedChapter: Int = 1
    private var lastRequestedVerse: Int = 1

    // Chapter verse counts (18 chapters)
    private val chapterVerseCounts = GitaConstants.CHAPTER_VERSE_COUNTS

    // Throttled database updater - batches verse reads to reduce I/O
    private val throttledUpdater = ThrottledDatabaseUpdater(
        batchSize = 10,
        flushIntervalMs = 5000L
    ) { batch ->
        try {
            val today = java.time.LocalDate.now().toString()
            batch.forEach { verseRead ->
                readVerseDao.insert(
                    com.aipoweredgita.app.database.ReadVerse(
                        chapterNo = verseRead.chapter,
                        verseNo = verseRead.verse,
                        date = today
                    )
                )
            }
            val distinct = readVerseDao.distinctVersePairs()
            database.userStatsDao().updateDistinctVersesRead(distinct)
            val dailyDao = database.dailyActivityDao()
            dailyDao.insertIfAbsent(com.aipoweredgita.app.database.DailyActivity(date = today))
            dailyDao.addVerses(today, batch.size)
            Log.d(TAG, "Batch write completed: ${batch.size} verses")
        } catch (e: Exception) {
            Log.e(TAG, "Error in batch write: ${e.message}")
            throw e
        }
    }

    // Time tracker — uses viewModelScope to prevent coroutine leaks
    private val timeTracker = TimeTracker(scope = viewModelScope) { seconds ->
        viewModelScope.launch(Dispatchers.IO) {
            statsRepository.trackModeTime(seconds, ModeType.NORMAL)
            try {
                val today = java.time.LocalDate.now().toString()
                val dailyDao = database.dailyActivityDao()
                dailyDao.insertIfAbsent(com.aipoweredgita.app.database.DailyActivity(date = today))
                dailyDao.addNormalSeconds(today, seconds)
            } catch (e: Exception) {
                Log.w(TAG, "Failed to update daily normal seconds", e)
            }
        }
    }

    init {
        timeTracker.start()
        viewModelScope.launch {
            com.aipoweredgita.app.utils.NetworkUtils.networkStatusFlow(application)
                .collect { online ->
                    if (online && _uiState.value.error?.contains("Offline", ignoreCase = true) == true) {
                        loadVerse(lastRequestedChapter, lastRequestedVerse)
                    }
                }
        }
        loadVerse(1, 1)
    }

    private fun computeChapterCombinedGroups(chapter: Int) {
        // DISABLED: We want all verses to be separate, so don't compute combined groups
        // This function was causing navigation issues by marking verses as combined
        // when they should be treated as individual verses

        // Always set combinedGroups to empty list
        viewModelScope.launch {
            _uiState.update { it.copy(combinedGroups = emptyList()) }
        }
    }

    fun onEvent(event: NormalModeEvent) {
        when (event) {
            is NormalModeEvent.LoadVerse -> loadVerse(event.chapter, event.verse, event.retryCount, event.autoSkipCombined)
            is NormalModeEvent.NextVerse -> nextVerse()
            is NormalModeEvent.PreviousVerse -> previousVerse()
            is NormalModeEvent.GoToChapter -> goToChapter(event.chapter)
            is NormalModeEvent.ToggleFavorite -> toggleFavorite()
            is NormalModeEvent.TrackShare -> trackShare()
        }
    }

    fun loadVerse(chapter: Int, verse: Int, retryCount: Int = 0, autoSkipCombined: Boolean = false) {
        viewModelScope.launch {
            lastRequestedChapter = chapter
            lastRequestedVerse = verse
            _uiState.update {
                it.copy(
                    isLoading = true,
                    error = null,
                    currentChapter = chapter,
                    currentVerse = verse,
                    // Clear any previous combined group during loading to prevent stale UI
                    combinedVerseNos = emptyList()
                )
            }

            try {
                Log.d(TAG, "Loading Chapter $chapter, Verse $verse (Attempt ${retryCount + 1})")

                // Try cache first
                val verseData = offlineCacheRepository.getVerse(chapter, verse)

                if (verseData != null) {
                    Log.d(TAG, "Loaded from cache: ${verseData.verse.take(50)}")

                    // Check if this verse was separated from a combined group
                    val note = if (verseData.wasSeparated && verseData.originalCombinedGroup.isNotEmpty()) {
                        val verseRange = "${verseData.originalCombinedGroup.first()}-${verseData.originalCombinedGroup.last()}"
                        "ℹ️ Note: Verses $verseRange were originally combined. We separated them for convenience, but the sloka summary is the same for all verses in this group."
                    } else null

                    // All verses are treated as separate - no combined verse detection
                    _uiState.update {
                        it.copy(
                            verse = verseData,
                            isLoading = false,
                            error = null,
                            combinedVerseNos = emptyList(),  // Always empty - all verses are separate
                            separatedVerseNote = note
                        )
                    }
                    // Don't compute combined groups - all verses are separate
                    computeChapterCombinedGroups(chapter)
                    // Check favorite status
                    checkFavoriteStatus(chapter, verse)
                    // Track verse read
                    trackVerseRead()
                } else {
                    // Fallback to API if not cached
                    val online = com.aipoweredgita.app.utils.NetworkUtils.isNetworkAvailable(application)
                    if (!online) {
                        _uiState.update {
                            it.copy(
                                isLoading = false,
                                error = "Offline: verse not downloaded. Use Offline mode or reconnect."
                            )
                        }
                        return@launch
                    }
                    Log.d(TAG, "Cache miss, fetching from API...")
                    val apiVerse = gitaRepository.getVerse(language, chapter, verse)
                    Log.d(TAG, "Successfully loaded from API: ${apiVerse.verse.take(50)}")

                    // Check if this verse was separated from a combined group
                    val note = if (apiVerse.wasSeparated && apiVerse.originalCombinedGroup.isNotEmpty()) {
                        val verseRange = "${apiVerse.originalCombinedGroup.first()}-${apiVerse.originalCombinedGroup.last()}"
                        "ℹ️ Note: Verses $verseRange were originally combined. We separated them for convenience, but the sloka summary is the same for all verses in this group."
                    } else null

                    // All verses are treated as separate - no combined verse detection
                    _uiState.update {
                        it.copy(
                            verse = apiVerse,
                            isLoading = false,
                            error = null,
                            combinedVerseNos = emptyList(),  // Always empty - all verses are separate
                            separatedVerseNote = note
                        )
                    }
                    computeChapterCombinedGroups(chapter)
                    // Check favorite status
                    checkFavoriteStatus(chapter, verse)
                    // Track verse read
                    trackVerseRead()
                }
            } catch (e: Exception) {
                Log.e(TAG, "Error loading verse - ${e::class.simpleName}: ${e.message}", e)

                // Retry logic for transient errors (network, timeout)
                val isTransientError = e.message?.let {
                    it.contains("timeout", ignoreCase = true) ||
                    it.contains("Unable to resolve host", ignoreCase = true) ||
                    it.contains("SocketTimeoutException", ignoreCase = true)
                } ?: false

                if (isTransientError && retryCount < 2) {
                    Log.d(TAG, "Retrying... (Attempt ${retryCount + 2})")
                    kotlinx.coroutines.delay(1000) // Wait 1 second before retry
                    loadVerse(chapter, verse, retryCount + 1)
                    return@launch
                }

                val errorMsg = when {
                    // Network errors
                    e.message?.contains("Unable to resolve host", ignoreCase = true) == true ||
                    e.message?.contains("UnknownHostException", ignoreCase = true) == true ||
                    e.message?.contains("No address associated", ignoreCase = true) == true ->
                        "❌ No Internet Connection\n\nPlease check:\n• WiFi or mobile data is enabled\n• Internet is working"

                    // Timeout errors
                    e.message?.contains("timeout", ignoreCase = true) == true ||
                    e.message?.contains("SocketTimeoutException", ignoreCase = true) == true ->
                        "⏱️ Connection Timeout\n\nThe server took too long to respond.\nPlease try again."

                    // API errors
                    e.message?.contains("404") == true ||
                    e.message?.contains("HTTP 404") == true ->
                        "❌ Verse Not Found\n\nChapter $chapter, Verse $verse may not exist.\nTry a different verse."

                    e.message?.contains("500") == true ||
                    e.message?.contains("HTTP 5") == true ->
                        "⚠️ Server Error\n\nThe API server is having issues.\nPlease try again later."

                    // JSON parsing errors
                    e.message?.contains("JsonSyntaxException", ignoreCase = true) == true ||
                    e.message?.contains("MalformedJsonException", ignoreCase = true) == true ->
                        "⚠️ Data Format Error\n\nReceived invalid data from server.\nPlease try again or try a different verse."

                    // Empty or null response
                    e.message?.contains("Expected", ignoreCase = true) == true &&
                    e.message?.contains("but was", ignoreCase = true) == true ->
                        "⚠️ Incomplete Data\n\nReceived incomplete verse data.\nPlease try another verse."

                    // Generic error with helpful info
                    else -> {
                        val errorType = e::class.simpleName ?: "Unknown"
                        "❌ Failed to Load Verse\n\nError: $errorType\n\nPossible solutions:\n• Check internet connection\n• Try again in a moment\n• Try a different verse\n\nDetails: ${e.message?.take(100) ?: "No details"}"
                    }
                }

                _uiState.update {
                    it.copy(
                        isLoading = false,
                        error = errorMsg
                    )
                }
            }
        }
    }

    fun nextVerse() {
        viewModelScope.launch {
            val current = _uiState.value
            val currentVerse = current.verse ?: return@launch
            val currentChapter = currentVerse.chapterNo
            val maxVersesInChapter = chapterVerseCounts[currentChapter] ?: 47

            // Simple increment - always go to next verse number
            val nextCandidate = currentVerse.verseNo + 1

            if (nextCandidate <= maxVersesInChapter) {
                loadVerse(currentChapter, nextCandidate)
            } else if (currentChapter < GitaConstants.MAX_CHAPTERS) {
                loadVerse(currentChapter + 1, 1)
            }
        }
    }


    fun previousVerse() {
        viewModelScope.launch {
            val current = _uiState.value
            val currentVerse = current.verse ?: return@launch
            val currentChapter = currentVerse.chapterNo
            val currentNo = currentVerse.verseNo

            // Simple decrement - always go to previous verse number
            val prevCandidate = currentNo - 1

            if (prevCandidate >= 1) {
                loadVerse(currentChapter, prevCandidate)
            } else if (currentChapter > 1) {
                val prevChapter = currentChapter - 1
                val lastVerseInPrevChapter = chapterVerseCounts[prevChapter] ?: 47
                loadVerse(prevChapter, lastVerseInPrevChapter)
            }
        }
    }


    fun goToChapter(chapter: Int) {
        if (chapter in 1..GitaConstants.MAX_CHAPTERS) {
            loadVerse(chapter, 1)
        }
    }

    // Track the current favorite status collector job so we can cancel it on verse change
    private var favoriteJob: kotlinx.coroutines.Job? = null

    private fun checkFavoriteStatus(chapter: Int, verse: Int) {
        favoriteJob?.cancel()
        favoriteJob = viewModelScope.launch {
            favoriteRepository.isFavorite(chapter, verse).collect { isFav ->
                _uiState.update { it.copy(isFavorite = isFav) }
            }
        }
    }

    fun toggleFavorite() {
        val verse = _uiState.value.verse ?: return

        viewModelScope.launch {
            val result = if (_uiState.value.isFavorite) {
                favoriteRepository.removeFavorite(verse.chapterNo, verse.verseNo)
            } else {
                favoriteRepository.addFavorite(verse)
            }

            result.onSuccess { message ->
                _uiState.update {
                    it.copy(
                        favoriteMessage = message,
                        isFavorite = !it.isFavorite
                    )
                }
                // Clear message after delay
                kotlinx.coroutines.delay(2000)
                _uiState.update { it.copy(favoriteMessage = null) }
            }.onFailure { error ->
                _uiState.update {
                    it.copy(
                        favoriteMessage = error.message ?: "Operation failed"
                    )
                }
                kotlinx.coroutines.delay(2000)
                _uiState.update { it.copy(favoriteMessage = null) }
            }
        }
    }

    private fun trackVerseRead() {
        viewModelScope.launch {
            val verse = _uiState.value.verse ?: return@launch
            // Track stats
            statsRepository.trackVerseRead()

            // Update yoga progression and check for level up
            val (didLevelUp, newLevel) = yogaProgressionRepository.updateProgressionAndCheckLevelUp()
            if (didLevelUp && newLevel != null) {
                // Show level-up notification
                com.aipoweredgita.app.notifications.YogaLevelUpNotificationManager.showLevelUpNotification(
                    application,
                    newLevel
                )
            }

            // Track distinct verses read (throttled to reduce DB writes)
            val vNo = verse.verseNo

            // Check for chapter completion — flush throttled writes first to get accurate count
            throttledUpdater.flush()
            kotlinx.coroutines.delay(200) // Brief pause for flush to complete
            val currentReadCount = readVerseDao.getReadVersesCountByChapter(verse.chapterNo)
            val totalVersesInChapter = chapterVerseCounts[verse.chapterNo] ?: 47

            if (currentReadCount >= totalVersesInChapter) {
                // Potential chapter completion.
                val prefs = application.getSharedPreferences("chapter_stats", android.content.Context.MODE_PRIVATE)
                val isCompleted = prefs.getBoolean("chapter_${verse.chapterNo}_completed", false)
                if (!isCompleted) {
                    statsRepository.trackChapterCompleted(verse.chapterNo)
                    prefs.edit().putBoolean("chapter_${verse.chapterNo}_completed", true).apply()
                    _sideEffect.emit(NormalModeSideEffect.ShowMessage("Chapter ${verse.chapterNo} Completed! \uD83E\uDE99 Sacred Coins awarded."))
                }
            }

            throttledUpdater.trackVerseRead(verse.chapterNo, verse.verseNo)
        }
    }

    override fun onCleared() {
        super.onCleared()
        // Stop time tracking when ViewModel is cleared
        timeTracker.stop()
        // Flush any pending verse reads to database
        throttledUpdater.flush()
        Log.d(TAG, "NormalModeViewModel cleared - throttled updater flushed")
    }

    private fun trackShare() {
        viewModelScope.launch {
            val verse = _uiState.value.verse
            statsRepository.trackSlokaShared(
                chapter = verse?.chapterNo,
                verse = verse?.verseNo
            )
        }
    }
}

