@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun NotesScreen(
    onBack: () -> Unit = {},
    onVerseClick: (chapter: Int, verse: Int) -> Unit = { _, _ -> }
) {
    val context = LocalContext.current
    val db = remember { GitaDatabase.getDatabase(context) }
    val noteDao = remember { db.verseNoteDao() }
    val notes by noteDao.getAllNotes().collectAsState(initial = emptyList())
    val scope = rememberCoroutineScope()
    var showAddDialog by remember { mutableStateOf(false) }
    val authPrefs = remember { AuthPreferences.getInstance(context) }

    LaunchedEffect(Unit) {
        if (!authPrefs.isGuestUser && !authPrefs.userId.isNullOrEmpty()) {
            try {
                val serverNotes = CoinApi.retrofitService.getNotes(authPrefs.userId!!)
                for (sn in serverNotes) {
                    val existing = noteDao.getNote(sn.chapter_no, sn.verse_no)
                    if (existing == null) {
                        noteDao.insertNote(VerseNote(chapterNo = sn.chapter_no, verseNo = sn.verse_no, note = sn.note))
                    }
                }
            } catch (_: Exception) {}
        }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("My Notes") },
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back")
                    }
                }
            )
        },
        floatingActionButton = {
            FloatingActionButton(
                onClick = { showAddDialog = true },
                containerColor = MaterialTheme.colorScheme.primary
            ) {
                Icon(Icons.Default.Add, "Add Note")
            }
        }
    ) { padding ->
        if (notes.isEmpty()) {
            Box(modifier = Modifier.fillMaxSize().padding(padding)) {
                Column(modifier = Modifier.align(Alignment.Center), horizontalAlignment = Alignment.CenterHorizontally) {
                    Text("\uD83D\uDCDD", style = MaterialTheme.typography.displayLarge)
                    Spacer(Modifier.height(16.dp))
                    Text("No notes yet", style = MaterialTheme.typography.titleMedium)
                    Spacer(Modifier.height(8.dp))
                    Text(
                        "Tap + to add a note to any verse",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f)
                    )
                }
            }
        } else {
            LazyColumn(modifier = Modifier.fillMaxSize().padding(padding)) {
                items(notes) { note ->
                    NoteCard(note, onVerseClick, onDelete = {
                        scope.launch {
                            noteDao.deleteNote(note.id)
                            if (!authPrefs.isGuestUser && !authPrefs.userId.isNullOrEmpty()) {
                                try {
                                    CoinApi.retrofitService.deleteNote(NoteDeleteRequest(authPrefs.userId!!, note.chapterNo, note.verseNo))
                                } catch (_: Exception) {}
                            }
                        }
                    })
                }
            }
        }
    }

    if (showAddDialog) {
        AddNoteDialog(
            onDismiss = { showAddDialog = false },
            onSave = { chapter, verse, text ->
                scope.launch {
                    noteDao.insertNote(
                        VerseNote(
                            chapterNo = chapter,
                            verseNo = verse,
                            note = text
                        )
                    )
                    if (!authPrefs.isGuestUser && !authPrefs.userId.isNullOrEmpty()) {
                        try {
                            CoinApi.retrofitService.syncNotes(
                                NotesSyncRequest(authPrefs.userId!!, listOf(NoteSyncItem(chapter, verse, text)))
                            )
                        } catch (_: Exception) {}
                    }
                }
                showAddDialog = false
            }
        )
    }
}

@Composable
private fun NoteCard(note: VerseNote, onVerseClick: (Int, Int) -> Unit, onDelete: () -> Unit) {
    Card(
        modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 4.dp)
            .clickable { onVerseClick(note.chapterNo, note.verseNo) },
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f))
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        "Chapter ${note.chapterNo}, Verse ${note.verseNo}",
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.primary,
                        fontWeight = FontWeight.Bold
                    )
                    Text(
                        java.text.SimpleDateFormat("MMM dd, yyyy", java.util.Locale.getDefault())
                            .format(java.util.Date(note.updatedAt)),
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f)
                    )
                }
                IconButton(onClick = onDelete, modifier = Modifier.size(32.dp)) {
                    Icon(Icons.Default.Delete, "Delete", tint = MaterialTheme.colorScheme.error, modifier = Modifier.size(18.dp))
                }
            }
            Spacer(Modifier.height(8.dp))
            Text(note.note, style = MaterialTheme.typography.bodyMedium, maxLines = 5)
        }
    }
}

@Composable
fun AddNoteDialog(
    onDismiss: () -> Unit,
    onSave: (chapter: Int, verse: Int, text: String) -> Unit
) {
    var chapter by remember { mutableStateOf("") }
    var verse by remember { mutableStateOf("") }
    var noteText by remember { mutableStateOf("") }
    var chapterError by remember { mutableStateOf(false) }
    var verseError by remember { mutableStateOf(false) }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text("Add Note") },
        text = {
            Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                    OutlinedTextField(
                        value = chapter,
                        onValueChange = { chapter = it.filter { c -> c.isDigit() }; chapterError = false },
                        label = { Text("Chapter") },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                        isError = chapterError,
                        modifier = Modifier.weight(1f),
                        singleLine = true
                    )
                    OutlinedTextField(
                        value = verse,
                        onValueChange = { verse = it.filter { c -> c.isDigit() }; verseError = false },
                        label = { Text("Verse") },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                        isError = verseError,
                        modifier = Modifier.weight(1f),
                        singleLine = true
                    )
                }
                OutlinedTextField(
                    value = noteText,
                    onValueChange = { noteText = it },
                    label = { Text("Your note") },
                    modifier = Modifier.fillMaxWidth().heightIn(min = 100.dp),
                    maxLines = 6
                )
            }
        },
        confirmButton = {
            TextButton(
                onClick = {
                    val ch = chapter.toIntOrNull()
                    val vs = verse.toIntOrNull()
                    chapterError = ch == null || ch < 1 || ch > 18
                    verseError = vs == null || vs < 1
                    if (!chapterError && !verseError && noteText.isNotBlank()) {
                        onSave(ch!!, vs!!, noteText)
                    }
                }
            ) { Text("Save") }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text("Cancel") }
        }
    )
}

@Composable
fun NoteEditorDialog(
    chapterNo: Int,
    verseNo: Int,
    existingNote: String = "",
    onSave: (String) -> Unit,
    onDismiss: () -> Unit
) {
    var text by remember { mutableStateOf(existingNote) }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text("Note for $chapterNo:$verseNo") },
        text = {
            OutlinedTextField(
                value = text,
                onValueChange = { text = it },
                modifier = Modifier.fillMaxWidth().heightIn(min = 120.dp),
                placeholder = { Text("Write your reflection...") },
                maxLines = 8
            )
        },
        confirmButton = {
            TextButton(onClick = { if (text.isNotBlank()) onSave(text) }) {
                Text("Save")
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text("Cancel") }
        }
    )
}

