object SanskritAudioPlayer {
    private var mediaPlayer: MediaPlayer? = null
    private var currentUrl: String? = null

    fun play(url: String, onCompletion: () -> Unit = {}) {
        stop()
        try {
            mediaPlayer = MediaPlayer().apply {
                setDataSource(url)
                setOnPreparedListener { start() }
                setOnCompletionListener {
                    onCompletion()
                    currentUrl = null
                }
                setOnErrorListener { _, _, _ ->
                    currentUrl = null
                    true
                }
                prepareAsync()
            }
            currentUrl = url
        } catch (e: Exception) {
            currentUrl = null
        }
    }

    fun stop() {
        try {
            mediaPlayer?.release()
        } catch (_: Exception) {}
        mediaPlayer = null
        currentUrl = null
    }

    fun isPlaying(url: String): Boolean = currentUrl == url && mediaPlayer?.isPlaying == true
}

@Composable
fun AudioPronunciationButton(
    chapterNo: Int,
    verseNo: Int,
    modifier: Modifier = Modifier
) {
    var isPlaying by remember { mutableStateOf(false) }
    var isLoading by remember { mutableStateOf(false) }
    val audioUrl = "https://audio.example.com/gita/${chapterNo}_${verseNo}.mp3" // Placeholder URL

    DisposableEffect(Unit) {
        onDispose { SanskritAudioPlayer.stop() }
    }

    IconButton(
        onClick = {
            if (isPlaying) {
                SanskritAudioPlayer.stop()
                isPlaying = false
            } else {
                isLoading = true
                SanskritAudioPlayer.play(audioUrl) {
                    isPlaying = false
                    isLoading = false
                }
                isPlaying = true
                isLoading = false
            }
        },
        modifier = modifier,
        enabled = !isLoading
    ) {
        if (isLoading) {
            CircularProgressIndicator(modifier = Modifier.size(20.dp), strokeWidth = 2.dp)
        } else {
            Icon(
                if (isPlaying) Icons.Default.Stop else Icons.Default.PlayArrow,
                contentDescription = if (isPlaying) "Stop" else "Play pronunciation",
                tint = MaterialTheme.colorScheme.primary
            )
        }
    }
}

