                    // Remember me checkbox
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 8.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Checkbox(
                            checked = rememberMe,
                            onCheckedChange = { 
                                rememberMe = it
                                authPrefs.rememberMe = it
                            },
                            colors = CheckboxDefaults.colors(
                                checkedColor = GoldPrimary,
                                uncheckedColor = GoldSubtle,
                                checkmarkColor = DeepBrown
                            )
                        )
                        Text(
                            text = "Remember me",
                            fontSize = 12.sp,
                            color = GoldSubtle,
                            modifier = Modifier.clickable { 
                                rememberMe = !rememberMe
                                authPrefs.rememberMe = rememberMe
                            }
                        )
                    }

                    // OR divider
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 4.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        Box(
                            modifier = Modifier
                                .weight(1f)
                                .height(0.5.dp)
                                .background(GoldPrimary.copy(alpha = 0.2f))
                        )
                        Text(
                            text = "OR",
                            fontSize = 10.sp,
                            color = GoldSubtle,
                            letterSpacing = 2.sp
                        )
                        Box(
                            modifier = Modifier
                                .weight(1f)
                                .height(0.5.dp)
                                .background(GoldPrimary.copy(alpha = 0.2f))
                        )
                    }

                    Spacer(modifier = Modifier.height(12.dp))

                    // Guest button
                    OutlinedButton(
                        onClick = {
                            isLoading = true
                            errorMessage = null
                            scope.launch {
                                // Guest login is instant and performed locally without server round-trip latency
                                val guestId = "guest_${java.util.UUID.randomUUID()}"
                                authPrefs.saveGuestState(guestId)

                                // Update Room DB with guest user info so user stats and viewmodels work correctly
                                try {
                                    val db = com.aipoweredgita.app.database.GitaDatabase.getDatabase(context)
                                    db.userStatsDao().updateUserId(guestId)
                                    db.userStatsDao().updateProfile(name = "Guest User", dob = "")

                                    // Award 50 coin welcome bonus to new guests (once only)
                                    if (!authPrefs.guestWelcomeAwarded) {
                                        db.userStatsDao().updateKrishnaCoins(50)
                                        authPrefs.guestWelcomeAwarded = true
                                        com.aipoweredgita.app.coin.CoinTransactionLogger.log(context, 50, "Welcome bonus (guest)")
                                    }
                                } catch (e: Exception) {
                                    android.util.Log.e("LoginScreen", "Failed to update Room database for guest", e)
                                }
                                isLoading = false
                                onGuestLogin()
                            }
                        },
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(10.dp),
                        colors = ButtonDefaults.outlinedButtonColors(
                            contentColor = GoldAccent
                        ),
                        border = ButtonDefaults.outlinedButtonBorder.copy(
                            brush = Brush.linearGradient(
                                colors = listOf(GoldPrimary.copy(alpha = 0.35f), GoldPrimary.copy(alpha = 0.35f))
                            )
                        )
                    ) {
                        Icon(
                            imageVector = Icons.Default.Person,
                            contentDescription = null,
                            modifier = Modifier.size(15.dp),
                            tint = GoldAccent
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            text = "Enter as Guest Seeker",
                            fontSize = 12.sp,
                            letterSpacing = 0.5.sp
                        )
                    }
                }
            }

            // Footer
            Column(
                modifier = Modifier.padding(horizontal = 24.dp, vertical = 20.dp),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Text(
                    text = "By continuing, you accept our",
                    fontSize = 10.sp,
                    color = GoldDim,
                    textAlign = TextAlign.Center,
                    lineHeight = 17.sp
                )
                Row(
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Text(
                        text = "Terms of Dharma",
                        fontSize = 10.sp,
                        color = GoldAccent,
                        modifier = Modifier.clickable { }

package com.aipoweredgita.app.ui

import androidx.compose.foundation.layout.*
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.filled.Translate
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp

object TeluguTransliterator {

    private val vowelMap = mapOf(
        "a" to "అ", "aa" to "ఆ", "i" to "ఇ", "ee" to "ఈ",
        "u" to "ఉ", "oo" to "ఊ", "e" to "ఏ", "ai" to "ఐ",
        "o" to "ఓ", "au" to "ఔ", "am" to "అం", "ah" to "అః"
    )

    private val consonantMap = mapOf(
        "ka" to "క", "kha" to "ఖ", "ga" to "గ", "gha" to "ఘ", "nga" to "ఙ",
        "cha" to "చ", "chha" to "ఛ", "ja" to "జ", "jha" to "ఝ", "nja" to "ఞ",
        "ta" to "ట", "tha" to "ఠ", "da" to "డ", "dha" to "ఢ", "na" to "ణ",
        "tha" to "త", "thha" to "థ", "da" to "ద", "dhha" to "ధ", "na" to "న",
        "pa" to "ప", "pha" to "ఫ", "ba" to "బ", "bha" to "భ", "ma" to "మ",
        "ya" to "య", "ra" to "ర", "la" to "ల", "va" to "వ",
        "sha" to "శ", "shha" to "ష", "sa" to "స", "ha" to "హ",
        "ksha" to "క్ష", "trna" to "ట్ర"
    )

    private val matraMap = mapOf(
        "aa" to "ా", "i" to "ి", "ee" to "ీ", "u" to "ు",
        "oo" to "ూ", "e" to "ే", "ai" to "ై", "o" to "ో",
        "au" to "ౌ", "am" to "ం", "ah" to "ః"
    )

    private val halant = "్"
    private val digitMap = mapOf(
        "0" to "౦", "1" to "౧", "2" to "౨", "3" to "౩", "4" to "౪",
        "5" to "౫", "6" to "౬", "7" to "౭", "8" to "౮", "9" to "౯"
    )

    fun transliterate(input: String): String {
        if (input.isBlank()) return input

        val result = StringBuilder()
        var i = 0
        val lower = input.lowercase()

        while (i < lower.length) {
            var matched = false

            // Try longest match first
            for (len in 6 downTo 1) {
                if (i + len <= lower.length) {
                    val chunk = lower.substring(i, i + len)
                    if (vowelMap.containsKey(chunk)) {
                        result.append(vowelMap[chunk])
                        i += len
                        matched = true
                        break
                    }
                    if (consonantMap.containsKey(chunk)) {
                        result.append(consonantMap[chunk])
                        i += len
                        matched = true
                        break
                    }
                }
            }

            if (!matched) {
                val ch = lower[i]
                when {
                    ch == ' ' -> result.append(' ')
                    ch.isDigit() -> result.append(digitMap[ch.toString()] ?: ch)
                    ch == '.' || ch == ',' || ch == '!' || ch == '?' -> result.append(ch)
                    else -> result.append(ch)
                }
                i++
            }
        }

        return result.toString()
    }
}

@Composable
fun TransliterateTextField(
    value: String,
    onValueChange: (String) -> Unit,
    modifier: Modifier = Modifier,
    label: String = "Type in English",
    placeholder: String = "e.g. nenu krishnudu",
    enabled: Boolean = true
) {
    var isTransliterateMode by remember { mutableStateOf(false) }
    var englishInput by remember { mutableStateOf(value) }

    Column(modifier = modifier) {
        Row(verticalAlignment = androidx.compose.ui.Alignment.CenterVertically) {
            OutlinedTextField(
                value = if (isTransliterateMode) englishInput else value,
                onValueChange = { newValue ->
                    if (isTransliterateMode) {
                        englishInput = newValue
                        onValueChange(TeluguTransliterator.transliterate(newValue))
                    } else {
                        onValueChange(newValue)
                    }
                },
                modifier = Modifier.weight(1f),
                label = { Text(label) },
                placeholder = { Text(placeholder) },
                enabled = enabled
            )
            Spacer(Modifier.width(8.dp))
            IconButton(onClick = { isTransliterateMode = !isTransliterateMode }) {
                Icon(
                    Icons.Default.Translate,
                    contentDescription = "Toggle transliteration",
                    tint = if (isTransliterateMode) MaterialTheme.colorScheme.primary
                           else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f)
                )
            }
        }
        if (isTransliterateMode) {
            Text(
                "Telugu transliteration ON — type phonetically in English",
                style = MaterialTheme.typography.labelSmall,
                color = MaterialTheme.colorScheme.primary,
                modifier = Modifier.padding(start = 16.dp, top = 4.dp)
            )
        }
    }
}

