// ─── MandalaBadge (rotating aura ring matching HTML mandala2 canvas) ─────────

@Composable
private fun MandalaBadge(
    intensity : Float,
    modifier  : Modifier = Modifier
) {
    val infinite = rememberInfiniteTransition(label = "mandala")
    val rot by infinite.animateFloat(
        initialValue  = 0f,
