                }

                var baseDownloaded = computeAlreadyDownloaded(targets)

                targets.forEach { model ->
                    val outFile = File(modelsDir, model.fileName)
                    if (!modelExists(model.fileName)) {
                        val url = manifest.urls[model.fileName]
                        if (url.isNullOrBlank()) {
                            Log.w(TAG, "No URL for ${model.fileName} in manifest; skipping download")
                            onProgress(DownloadProgress(model.fileName, model.name, 0, 0,
                                overallPercent(baseDownloaded, expectedTotal), "missing_url"))
                        } else {
                            val ok = tryDownload(url, outFile) { bytes, total ->
                                if (total > 0) measuredSizes[model.fileName] = total
                                onProgress(DownloadProgress(model.fileName, model.name, bytes, total,
                                    overallPercent(baseDownloaded + bytes, expectedTotal), "downloading"))
                            }
                            val written = if (outFile.exists()) outFile.length() else 0L
                            val target = measuredSizes[model.fileName] ?: model.expectedBytes
                            baseDownloaded = (baseDownloaded + minOf(written, target)).coerceAtMost(expectedTotal)
                            onProgress(DownloadProgress(model.fileName, model.name, written, written,
                                overallPercent(baseDownloaded, expectedTotal), if (ok) "completed" else "failed"))
                        }
                    } else {
                        // FIX 4: Update baseDownloaded for already-existing files too
                        val target = measuredSizes[model.fileName] ?: model.expectedBytes
                        val completed = minOf(outFile.length(), target)
                        baseDownloaded = (baseDownloaded + completed).coerceAtMost(expectedTotal)
                        onProgress(DownloadProgress(model.fileName, model.name, completed, completed,
                            overallPercent(baseDownloaded, expectedTotal), "exists"))
                    }
                }

                val allReady = areAllModelsDownloaded()
                Log.d(TAG, "Model verification complete. ready=$allReady")
                allReady
            } catch (e: Exception) {
                Log.e(TAG, "Fatal error during model download", e)
                false
            }
        }
    }


    // ─── Private Helpers ──────────────────────────────────────────────────────

    private fun overallPercent(downloaded: Long, total: Long): Int =
        if (total > 0) (downloaded.coerceAtLeast(0) * 100 / total).toInt().coerceIn(0, 100) else 0

    private fun computeAlreadyDownloaded(targetModels: List<ModelInfo>): Long {
        return targetModels.sumOf { model ->
            val file = File(modelsDir, model.fileName)
            if (file.exists() && file.length() > 0) {
                val target = measuredSizes[model.fileName] ?: model.expectedBytes
                minOf(file.length(), target)
            } else 0L
        }
    }

    private fun probeModelSizes(manifest: Manifest) {
        models.forEach { model ->
            if (!measuredSizes.containsKey(model.fileName)) {
                val url = manifest.urls[model.fileName] ?: return@forEach
                val length = contentLengthOf(normalizeHuggingFaceUrl(url, model.fileName))
                if (length > 0) measuredSizes[model.fileName] = length
            }
        }
    }

    private fun contentLengthOf(urlStr: String): Long {
        return try {
            val url = java.net.URL(urlStr)
            val conn = url.openConnection() as java.net.HttpURLConnection
            conn.requestMethod = "HEAD"
            conn.connectTimeout = 15000
            conn.readTimeout = 15000
            conn.setRequestProperty("User-Agent", "Mozilla/5.0 (Android) GitaLearningApp")
            conn.setRequestProperty("Accept", "application/octet-stream, */*")
            conn.connect()
            val len = conn.contentLengthLong
            conn.disconnect()
            if (len > 0) len else {
                val c = url.openConnection() as java.net.HttpURLConnection
                c.requestMethod = "GET"
                c.connectTimeout = 15000
                c.readTimeout = 15000
                c.setRequestProperty("Range", "bytes=0-0")
                c.setRequestProperty("User-Agent", "Mozilla/5.0 (Android) GitaLearningApp")
                c.setRequestProperty("Accept", "application/octet-stream, */*")
                c.connect()
                val l = c.contentLengthLong
                c.disconnect()
                if (l > 0) l else -1
            }
        } catch (e: Exception) {
            Log.w(TAG, "Failed to probe content length: ${e.message}")
            -1
        }
    }

    private fun loadManifest(): Manifest {
        return try {
            val input = context.assets.open("ml_models/download_manifest.json")
            InputStreamReader(input).use { reader ->
                Gson().fromJson(reader, Manifest::class.java)
            }
        } catch (e: Exception) {
            Log.w(TAG, "No manifest found in assets; using empty map")
            Manifest(urls = emptyMap())
        }
    }

    /** FIX 5: Uses singleton httpClient instead of creating one per call */
    private fun tryDownload(urlStr: String, outFile: File, onProgress: (Long, Long) -> Unit): Boolean {
        val normalizedUrlStr = normalizeHuggingFaceUrl(urlStr, outFile.name)
        val tempFile = File(outFile.absolutePath + ".part")

        var attempt = 0
        val maxAttempts = 3
        while (attempt < maxAttempts) {
            attempt++
            try {
                val existingBytes = if (tempFile.exists()) tempFile.length() else 0L

                val request = okhttp3.Request.Builder()
                    .url(normalizedUrlStr)
                    .addHeader("Range", "bytes=$existingBytes-")
                    .addHeader("User-Agent", "GitaApp/1.0")
                    .build()

                httpClient.newCall(request).execute().use { response ->
                    val isSuccess = response.code in 200..299
                    val isRangeSuccess = response.code == 206

                    if (!isSuccess && !isRangeSuccess) {
                        Log.w(TAG, "HTTP ${response.code} for $normalizedUrlStr (attempt $attempt)")
                        return@use
                    }

                    val body = response.body ?: run {
                        Log.w(TAG, "Empty response body (attempt $attempt)")
                        return@use
                    }

                    val contentLength = body.contentLength()
                    val total = if (contentLength > 0) {
                        if (isRangeSuccess) contentLength + existingBytes else contentLength
                    } else {
                        measuredSizes[outFile.name] ?: outFile.length().coerceAtLeast(0L)
                    }

                    java.io.FileOutputStream(tempFile, existingBytes > 0 && isRangeSuccess).use { output ->
                        body.byteStream().use { input ->
                            val buffer = ByteArray(8192)
                            var downloaded = if (isRangeSuccess) existingBytes else 0L
                            var read: Int
                            while (input.read(buffer).also { read = it } != -1) {
                                output.write(buffer, 0, read)
                                downloaded += read
                                onProgress(downloaded, total)
                            }
                        }
                    }

                    if (tempFile.exists() && tempFile.length() > 0) {
                        // Validate file size before renaming if we have a total
                        if (total > 0 && tempFile.length() < total * 0.98) {
                            Log.w(TAG, "Download finished but size mismatch: ${tempFile.length()} vs $total")
                        } else {
                            if (outFile.exists()) outFile.delete()
                            if (tempFile.renameTo(outFile)) {
                                return true
                            }
                        }
                    }
                }
            } catch (e: Exception) {
                Log.w(TAG, "Download attempt $attempt failed: ${e.message}")
            }
        }
        return false
    }

    private fun normalizeHuggingFaceUrl(original: String, expectedFileName: String): String {
        return try {
            if (!original.contains("huggingface.co")) return original
            val uri = java.net.URI(original)
            var path = uri.path ?: ""

            if (path.contains("/resolve/")) {
                val query = if (uri.query.isNullOrBlank()) "download=true" else uri.query
                return java.net.URI(uri.scheme, uri.authority, uri.path, query, uri.fragment).toString()
            }

            val trimmed = path.trim('/')
            val parts = trimmed.split('/')
            if (parts.size >= 2) {
                val user = parts[0]
                val repo = parts[1]
                val fileName = if (repo.endsWith(".tflite") || repo.endsWith(".litertlm")) repo else expectedFileName
                val newPath = "/$user/$repo/resolve/main/$fileName"
                val query = if (uri.query.isNullOrBlank()) "download=true" else uri.query
                java.net.URI(uri.scheme, uri.authority, newPath, query, uri.fragment).toString()
            } else {
                original
            }
        } catch (_: Exception) {
            original
        }
    }

    private fun modelExists(fileName: String): Boolean {
        val modelTarget = models.find { it.fileName == fileName } ?: return false
        val expectedTarget = measuredSizes[fileName] ?: modelTarget.expectedBytes

        val file = File(modelsDir, fileName)
        if (file.exists() && file.length() > 0 && file.length() >= expectedTarget * 0.99f) return true

        return try {
            val afd = context.assets.openFd("ml_models/$fileName")
            afd.length > 0 && afd.length >= expectedTarget * 0.99f
        } catch (_: Exception) {
            false
        }
    }

    // ─── Public Utility Functions ─────────────────────────────────────────────

    fun getModelDirPath(): String = modelsDir.absolutePath

    suspend fun getTotalDownloadedSize(): Long = withContext(Dispatchers.IO) {
        models.sumOf { model ->
            val file = File(modelsDir, model.fileName)
            if (file.exists()) file.length() else 0L
        }
    }

    fun getExpectedTotalSizeBytes(): Long {
        val dynamicTotal = models.sumOf { measuredSizes[it.fileName] ?: 0L }
        return if (dynamicTotal > 0) dynamicTotal else models.sumOf { it.expectedBytes }
    }

    suspend fun getMeasuredTotalSizeBytes(): Long = withContext(Dispatchers.IO) {
        try {
            if (measuredSizes.isEmpty()) probeModelSizes(loadManifest())
            models.sumOf { measuredSizes[it.fileName] ?: 0L }
        } catch (_: Exception) {
            0L
        }
    }

    suspend fun getRemainingDownloadSizeBytes(): Long = withContext(Dispatchers.IO) {
        models.sumOf { model ->
            val file = File(modelsDir, model.fileName)
            if (file.exists() && file.length() > 0) 0L
            else measuredSizes[model.fileName] ?: model.expectedBytes
        }
    }

    suspend fun clearAllModels(): Boolean = withContext(Dispatchers.IO) {
        try {
            if (modelsDir.exists()) {
                modelsDir.deleteRecursively()
                modelsDir.mkdirs()
                Log.d(TAG, "All models cleared")
                true
            } else false
        } catch (e: Exception) {
            Log.e(TAG, "Error clearing models: ${e.message}")
            false
        }
    }

    fun getModelInfo(name: String): ModelInfo? {
        return allModels.find { it.name == name }
    }

    suspend fun getModelsStatus(): List<ModelStatus> = withContext(Dispatchers.IO) {
        models.map { model ->
            val file = File(modelsDir, model.fileName)
            val expectedTarget = measuredSizes[model.fileName] ?: model.expectedBytes
            val actualSize = if (file.exists()) file.length() else 0L
            val isFullyDownloaded = actualSize > 0 && actualSize >= expectedTarget * 0.9f
            ModelStatus(
                name = model.name,
                size = model.size,
                isDownloaded = isFullyDownloaded,
                actualSizeBytes = actualSize,
                path = file.absolutePath
            )
        }
    }

    data class ModelStatus(
        val name: String,
        val size: String,
        val isDownloaded: Boolean,
        val actualSizeBytes: Long,
        val path: String
    )

    companion object {
        fun getBestTextModelPath(context: Context): String? {
            val modelsDir = File(context.filesDir, "ml_models")
            val qwenFile = File(modelsDir, "qwen3-0.6b-int4.litertlm")
            if (qwenFile.exists() && qwenFile.length() > 500_000_000L) return qwenFile.absolutePath
            val gemma4File = File(modelsDir, "gemma-4-E2B-it.litertlm")
            if (gemma4File.exists() && gemma4File.length() > 2_500_000_000L) return gemma4File.absolutePath
            return null
        }

        /** @deprecated Use {@link #getBestTextModelPath(Context)} */
        @Deprecated("Use getBestTextModelPath", ReplaceWith("getBestTextModelPath(context)"))
        fun getBestGemmaModelPath(context: Context): String? = getBestTextModelPath(context)
    }
}

package com.aipoweredgita.app.ml

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import com.aipoweredgita.app.data.SegmentWeightageSystem
import com.aipoweredgita.app.data.LearningSegment
import java.util.Calendar

data class UserBadge(
    val id: String,
    val name: String,
    val description: String,
    val icon: String,
    val level: Int,
    val unlockedAt: String,
    val category: BadgeCategory
)

enum class BadgeCategory {
    KNOWLEDGE, DEDICATION, ACHIEVEMENT, WISDOM, SPIRITUAL
}

data class UserLevel(
    val level: Int,
    val title: String,
    val description: String,
    val icon: String,
    val experiencePoints: Int,
    val nextLevelXP: Int,
    val category: String
)

class AIBadgeSystem {

    // Get AI-decided badges based on user stats
    suspend fun generateBadges(
        versesRead: Int,
        quizzesTaken: Int,
        score: Int,
        totalQuestions: Int,
        timeSpent: Long,
        currentStreak: Int,
        favoriteCount: Int
    ): List<UserBadge> {
        return withContext(Dispatchers.Default) {
            val badges = mutableListOf<UserBadge>()

            // Knowledge Seeker - Read X verses
            if (versesRead >= 10) {
                badges.add(UserBadge(
                    id = "knowledge_seeker",
                    name = "Knowledge Seeker",
                    description = "Read 10+ verses from the Gita",
                    icon = "📖",
                    level = (versesRead / 10).coerceAtMost(5),
                    unlockedAt = getCurrentDate(),
                    category = BadgeCategory.KNOWLEDGE
                ))
            }

            // Quiz Master - Take X quizzes
            if (quizzesTaken >= 5) {
                val quizLevel = when {
                    quizzesTaken >= 100 -> 5
                    quizzesTaken >= 50 -> 4
                    quizzesTaken >= 20 -> 3
                    quizzesTaken >= 10 -> 2
                    else -> 1
                }
                badges.add(UserBadge(
                    id = "quiz_master",
                    name = "Quiz Master",
                    description = "Complete $quizzesTaken quizzes",
                    icon = "🎯",
                    level = quizLevel,
                    unlockedAt = getCurrentDate(),
                    category = BadgeCategory.ACHIEVEMENT
                ))
            }

            // Brilliant Mind - High quiz score
            if (totalQuestions > 0) {
                val accuracy = (score * 100) / totalQuestions
                if (accuracy >= 80) {
                    val brilliantLevel = when {
                        accuracy >= 95 -> 5
                        accuracy >= 90 -> 4
                        accuracy >= 85 -> 3
                        else -> 2
                    }
                    badges.add(UserBadge(
                        id = "brilliant_mind",
                        name = "Brilliant Mind",
                        description = "$accuracy% Quiz Accuracy",
                        icon = "🧠",
                        level = brilliantLevel,
                        unlockedAt = getCurrentDate(),
                        category = BadgeCategory.WISDOM
                    ))
                }
            }

            // Dedicated Learner - Consistent study
            if (currentStreak >= 7) {
                val streakLevel = when {
                    currentStreak >= 100 -> 5
                    currentStreak >= 50 -> 4
                    currentStreak >= 30 -> 3
                    currentStreak >= 14 -> 2
                    else -> 1
                }
                badges.add(UserBadge(
                    id = "dedicated_learner",
                    name = "Dedicated Learner",
                    description = "$currentStreak day streak",
                    icon = "🔥",
                    level = streakLevel,
                    unlockedAt = getCurrentDate(),
                    category = BadgeCategory.DEDICATION
                ))
            }

            // Verse Enthusiast - Many favorites
            if (favoriteCount >= 5) {
                val favLevel = when {
                    favoriteCount >= 100 -> 5
                    favoriteCount >= 50 -> 4
                    favoriteCount >= 25 -> 3
                    favoriteCount >= 10 -> 2
                    else -> 1
                }
                badges.add(UserBadge(
                    id = "verse_enthusiast",
                    name = "Verse Enthusiast",
                    description = "$favoriteCount favorite verses",
                    icon = "❤️",
                    level = favLevel,
                    unlockedAt = getCurrentDate(),
                    category = BadgeCategory.SPIRITUAL
                ))
            }

            // Time Master - Long study sessions
            val hoursSpent = timeSpent / 3600
            if (hoursSpent >= 1) {
                val timeLevel = when {
                    hoursSpent >= 1000 -> 5
                    hoursSpent >= 500 -> 4
                    hoursSpent >= 100 -> 3
                    hoursSpent >= 24 -> 2
                    else -> 1
                }
                badges.add(UserBadge(
                    id = "time_master",
                    name = "Time Master",
                    description = "$hoursSpent+ hours studying",
                    icon = "⏱️",
                    level = timeLevel,
                    unlockedAt = getCurrentDate(),
                    category = BadgeCategory.DEDICATION
                ))
            }

            // Spiritual Warrior - Balanced learning
            val balanceScore = calculateBalance(versesRead, quizzesTaken, currentStreak)
            if (balanceScore >= 70) {
                val spiritualLevel = when {
                    balanceScore >= 95 -> 5
                    balanceScore >= 90 -> 4
                    balanceScore >= 85 -> 3
                    balanceScore >= 75 -> 2
                    else -> 1
                }
                badges.add(UserBadge(
                    id = "spiritual_warrior",
                    name = "Spiritual Warrior",
                    description = "Balanced spiritual journey",
                    icon = "⚔️",
                    level = spiritualLevel,
                    unlockedAt = getCurrentDate(),
                    category = BadgeCategory.SPIRITUAL
                ))
            }

            // Elite Scholar - All-rounder
            if (versesRead >= 50 && quizzesTaken >= 20 && currentStreak >= 30) {
                badges.add(UserBadge(
                    id = "elite_scholar",
                    name = "Elite Scholar",
                    description = "Master of all learning modes",
                    icon = "👑",
                    level = 5,
                    unlockedAt = getCurrentDate(),
                    category = BadgeCategory.WISDOM
                ))
            }

            badges
        }
    }

    // Calculate user level based on experience (5 Yoga Levels + 19 Steps)
    suspend fun calculateLevel(
        versesRead: Int,
        quizzesTaken: Int,
        score: Int,
        totalQuestions: Int,
        timeSpent: Long,
        currentStreak: Int,
        favoriteCount: Int,
        segmentSystem: SegmentWeightageSystem? = null
    ): UserLevel {
        return withContext(Dispatchers.Default) {
            // Calculate XP
            val verseXP = versesRead * 10
            val quizXP = quizzesTaken * 25
            val scoreXP = if (totalQuestions > 0) (score * 50) / totalQuestions else 0
            val timeXP = (timeSpent / 3600).toInt() * 5 // 5 XP per hour
            val streakXP = currentStreak * 15
            val favoriteXP = favoriteCount * 8

            // Calculate segment mastery bonus
            val segmentMasteryXP = segmentSystem?.let { system ->
                val totalSegments = LearningSegment.values().size
                val masteredSegments = system.segments.values.count { it.accuracy >= 80f }

                // Bonus XP for balanced mastery across segments
                val balanceBonus = if (masteredSegments > 0) {
                    (masteredSegments * 20) + (system.overallAccuracy.toInt() / 10)
                } else {
                    0
                }

                balanceBonus
            } ?: 0

            val totalXP = verseXP + quizXP + scoreXP + timeXP + streakXP + favoriteXP + segmentMasteryXP

            // Map XP to 5 Yoga Levels and 19 Steps
            // Level 1 (Karma Yoga): Steps 1-3 (0-375 XP)
            // Level 2 (Bhakti Yoga): Steps 4-7 (375-750 XP)
            // Level 3 (Jnana Yoga): Steps 8-11 (750-1125 XP)
            // Level 4 (Dhyana Yoga): Steps 12-15 (1125-1500 XP)
            // Level 5 (Moksha/Sanyasa): Steps 16-19 (1500+ XP)

            val level = when {
                totalXP < 375 -> 1
                totalXP < 750 -> 2
                totalXP < 1125 -> 3
                totalXP < 1500 -> 4
                else -> 5
            }

            val step = when {
                totalXP < 125 -> 1
                totalXP < 250 -> 2
                totalXP < 375 -> 3
                totalXP < 500 -> 4
                totalXP < 625 -> 5
                totalXP < 750 -> 6
                totalXP < 875 -> 7
                totalXP < 1000 -> 8
                totalXP < 1125 -> 9
                totalXP < 1250 -> 10
                totalXP < 1375 -> 11
                totalXP < 1500 -> 12
                totalXP < 1625 -> 13
                totalXP < 1750 -> 14
                totalXP < 1875 -> 15
                totalXP < 2000 -> 16
                totalXP < 2125 -> 17
                totalXP < 2250 -> 18
                else -> 19
            }

            val (title, description, icon) = getLevelInfo(level, step)

            UserLevel(
                level = level,
                title = title,
                description = description,
                icon = icon,
                experiencePoints = totalXP,
                nextLevelXP = getNextLevelXP(level, step),
                category = getLevelCategory(level)
            )
        }
    }

    private fun getLevelInfo(level: Int, step: Int): Triple<String, String, String> {
        return when (level) {
            1 -> Triple(
                "Karma Yoga",
                "Action without Attachment - Step $step of 19",
                "🌿"
            )
            2 -> Triple(
                "Bhakti Yoga",
                "Devotion and Love for God - Step $step of 19",
                "🔥"
            )
            3 -> Triple(
                "Jnana Yoga",
                "Knowledge and Wisdom - Step $step of 19",
                "🧠"
            )
            4 -> Triple(
                "Dhyana Yoga",
                "Meditation and Mind Control - Step $step of 19",
                "🌬️"
            )
            5 -> Triple(
                "Moksha/Sanyasa",
                "Liberation and Freedom - Step $step of 19",
                "🌺"
            )
            else -> Triple("Yoga Path", "Spiritual Journey - Step $step of 19", "✨")
        }
    }

    private fun getLevelCategory(level: Int): String {
        return when (level) {
            1 -> "Karma Yoga"
            2 -> "Bhakti Yoga"
            3 -> "Jnana Yoga"
            4 -> "Dhyana Yoga"
            5 -> "Moksha/Sanyasa"
            else -> "Unknown"
        }
    }

    private fun getNextLevelXP(level: Int, step: Int): Int {
        return when {
            // Level 1 (Karma Yoga) - Steps 1-3
            level == 1 && step == 1 -> 125
            level == 1 && step == 2 -> 250
            level == 1 && step == 3 -> 375
            // Level 2 (Bhakti Yoga) - Steps 4-7
            level == 2 && step == 4 -> 500
            level == 2 && step == 5 -> 625
            level == 2 && step == 6 -> 750
            level == 2 && step == 7 -> 875
            // Level 3 (Jnana Yoga) - Steps 8-11
            level == 3 && step == 8 -> 1000
            level == 3 && step == 9 -> 1125
            level == 3 && step == 10 -> 1250
            level == 3 && step == 11 -> 1375
            // Level 4 (Dhyana Yoga) - Steps 12-15
            level == 4 && step == 12 -> 1500
            level == 4 && step == 13 -> 1625
            level == 4 && step == 14 -> 1750
            level == 4 && step == 15 -> 1875
            // Level 5 (Moksha/Sanyasa) - Steps 16-19
            level == 5 && step == 16 -> 2000
            level == 5 && step == 17 -> 2125
            level == 5 && step == 18 -> 2250
            else -> 2500 // Final step max XP
        }
    }

    private fun calculateBalance(versesRead: Int, quizzesTaken: Int, streak: Int): Int {
        // Balance score: how evenly distributed are activities
        val verseScore = (versesRead * 20).coerceAtMost(100)
        val quizScore = (quizzesTaken * 20).coerceAtMost(100)
        val streakScore = (streak * 2).coerceAtMost(100)

        return (verseScore + quizScore + streakScore) / 3
    }

    private fun getCurrentDate(): String {
        val calendar = Calendar.getInstance()
        val year = calendar.get(Calendar.YEAR)
        val month = calendar.get(Calendar.MONTH) + 1
        val day = calendar.get(Calendar.DAY_OF_MONTH)
        return String.format("%d-%02d-%02d", year, month, day)
    }
}

package com.aipoweredgita.app.ml

import android.content.Context
import androidx.lifecycle.LiveData
import androidx.work.WorkInfo
import androidx.work.WorkManager

/**
 * Singleton that provides shared download progress state across all screens.
 * Tracks Gemma (GemmaDownloadWorker) which is now the primary WorkManager-managed model.
 */
object ModelDownloadStateManager {
    private var gemmaWorkInfoLiveData: LiveData<List<WorkInfo>>? = null

    /**
     * Get the LiveData for Gemma download work info.
     */
    fun getGemmaWorkInfoLiveData(context: Context): LiveData<List<WorkInfo>> {
        if (gemmaWorkInfoLiveData == null) {
            gemmaWorkInfoLiveData = WorkManager.getInstance(context.applicationContext)
                .getWorkInfosForUniqueWorkLiveData("gemma_download")
        }
        return gemmaWorkInfoLiveData!!
    }

    /**
     * Get the LiveData for immediate download work info.
     */
    fun getWorkInfoLiveData(context: Context): LiveData<List<WorkInfo>> {
        return getGemmaWorkInfoLiveData(context)
    }

    /**
     * Check if ANY download is currently running.
     */
    fun isDownloading(context: Context): Boolean {
        return isGemmaDownloading(context)
    }

    /**
     * Check if Gemma specifically is downloading.
     */
    fun isGemmaDownloading(context: Context): Boolean {
        return getGemmaWorkInfoLiveData(context).value?.any {
            it.state == WorkInfo.State.RUNNING || it.state == WorkInfo.State.ENQUEUED
        } == true
    }

    /**
     * Get overall download progress percentage (0-100).
     */
    fun getOverallProgress(context: Context): Int {
        return getGemmaWorkInfoLiveData(context).value?.firstOrNull()?.progress?.getInt("overallProgress", 0) ?: 0
    }

    /**
     * Get the current model being downloaded.
     */
    fun getCurrentModel(context: Context): String {
        return getGemmaWorkInfoLiveData(context).value?.firstOrNull()?.progress?.getString("currentModel") ?: ""
    }

    /**
     * Check if Gemma 4 model file exists and is valid (required for voice features).
     */
    fun isGemmaDownloaded(context: Context): Boolean {
        return com.aipoweredgita.app.ml.ModelAvailability.getInstance(context).getGemma4Path() != null
    }

    /**
     * Schedule an immediate Gemma 4 2B download via WorkManager.
     * This survives screen changes and app closure.
     */
    fun startDownload(context: Context) {
        com.aipoweredgita.app.services.GemmaDownloadWorker.scheduleImmediateDownload(context)
    }

    /**
     * Cancel any ongoing download.
     */
    fun cancelDownload(context: Context) {
        WorkManager.getInstance(context.applicationContext)
            .cancelUniqueWork("gemma_download")
    }
}

