package com.aipoweredgita.app.ml

import android.content.Context
import android.util.Log
import com.aipoweredgita.app.database.QuizQuestionBank
import com.aipoweredgita.app.database.QuizQuestionBankDao
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

/**
 * PRODUCTION INGESTION PIPELINE for the Bhagavad Gita QA dataset.
 * 
 * Raw CSV format: chapter_no, verse_no, question, answer (open-ended source)
 * 
 * Pipeline stages:
 * 1. Download CSV from HuggingFace
 * 2. Parse rows
 * 3. Convert Raw Data → MCQ format (generate 3 distractors from answer context)
 * 4. Normalize text (remove quotes, fix encoding)
 * 5. Deduplicate (by question hash)
 * 6. Assign difficulty based on verse complexity
 * 7. Batch insert to DB
 * 
 * Result: Clean, production-ready MCQ questions ready for quiz use.
 */
class DatasetIngestionPipeline(
    private val context: Context,
    private val questionBankDao: QuizQuestionBankDao
) {
    private val TAG = "DatasetIngestion"

    private val DATASET_URLS = mapOf(
        "english" to "https://huggingface.co/datasets/JDhruv14/Bhagavad-Gita-QA/resolve/main/English/english.csv",
        "hindi" to "https://huggingface.co/datasets/JDhruv14/Bhagavad-Gita-QA/resolve/main/Hindi/hindi.csv",
        "gujarati" to "https://huggingface.co/datasets/JDhruv14/Bhagavad-Gita-QA/resolve/main/Gujarati/gujarati.csv"
    )

    // Cooldown period: don't re-ask same question within 24 hours
    private val COOLDOWN_MS = 24 * 60 * 60 * 1000L

    /**
     * Full pipeline: download → convert → dedup → normalize → store.
     */
    suspend fun ingestDataset(
        language: String = "english",
        batchSize: Int = 500,
        onProgress: (imported: Int, total: Int) -> Unit = { _, _ -> }
    ): Int = withContext(Dispatchers.IO) {
        var totalImported = 0

        val languages = if (language == "all") DATASET_URLS.keys else listOf(language)

        for (lang in languages) {
            val url = DATASET_URLS[lang] ?: continue
            Log.d(TAG, "Downloading $lang dataset from $url...")

            try {
                val csvContent = downloadCsv(url)
                val rawQuestions = parseCsv(csvContent, lang)
                Log.d(TAG, "Parsed ${rawQuestions.size} raw questions from $lang")

                // STAGE 3: Convert Raw Data → MCQ
                val mcqQuestions = convertToMCQ(rawQuestions)
                Log.d(TAG, "Converted ${mcqQuestions.size} questions to MCQ format")

                // STAGE 4: Normalize
                val normalized = mcqQuestions.map { normalizeQuestion(it) }

                // STAGE 5: Deduplicate (skip if hash already in DB)
                val dedupedQuestions = mutableListOf<QuizQuestionBank>()
                val existingHashes = mutableSetOf<String>()

                for (question in normalized) {
                    if (!existingHashes.contains(question.questionHash)) {
                        val count = questionBankDao.countByHash(question.questionHash)
                        if (count == 0) {
                            dedupedQuestions.add(question)
                            existingHashes.add(question.questionHash)
                        }
                    }
                }

                Log.d(TAG, "Deduplicated: ${rawQuestions.size} → ${dedupedQuestions.size} unique questions")

                // STAGE 7: Batch insert
                var batchStart = 0
                while (batchStart < dedupedQuestions.size) {
                    val batchEnd = minOf(batchStart + batchSize, dedupedQuestions.size)
                    val batch = dedupedQuestions.subList(batchStart, batchEnd)

                    questionBankDao.insertAll(batch)

                    totalImported += batch.size
                    onProgress(totalImported, dedupedQuestions.size)

                    batchStart = batchEnd
                }

                Log.d(TAG, "✓ Successfully imported ${dedupedQuestions.size} clean $lang questions")
            } catch (e: Exception) {
                Log.e(TAG, "Failed to ingest $lang dataset: ${e.message}", e)
            }
        }

        // FIX ISSUE 5: Deactivate low-quality questions instead of deleting them
        try {
            questionBankDao.deactivateLowQualityQuestions()
        } catch (_: Exception) { }

        // FIX ISSUE 6: Apply daily quality decay
        try {
            questionBankDao.applyQualityDecay()
        } catch (_: Exception) { }

        totalImported
    }

    private fun downloadCsv(url: String): String {
        val conn = java.net.URL(url).openConnection() as java.net.HttpURLConnection
        conn.connectTimeout = 30_000   // 30 s connect
        conn.readTimeout    = 120_000  // 2 min read (large CSV)
        conn.setRequestProperty("User-Agent", "GitaApp/1.0 (Android)")
        conn.connect()
        if (conn.responseCode !in 200..299) {
            conn.disconnect()
            throw Exception("HTTP ${conn.responseCode} downloading $url")
        }
        return try {
            conn.inputStream.bufferedReader().use { it.readText() }
        } finally {
            conn.disconnect()
        }
    }

    private fun parseCsv(csvContent: String, language: String): List<RawQuestion> {
        val questions = mutableListOf<RawQuestion>()
        val lines = csvContent.split("\n").filter { it.trim().isNotEmpty() }

        val dataLines = if (lines.firstOrNull()?.contains("chapter_no", ignoreCase = true) == true) {
            lines.drop(1)
        } else {
            lines
        }

        for (line in dataLines) {
            try {
                val fields = parseCsvLine(line)
                if (fields.size < 4) continue

                val chapterNo = fields[0].trim().toIntOrNull() ?: continue
                val verseNo = fields[1].trim().toIntOrNull() ?: continue
                val question = fields[2].trim().removeSurrounding("\"").trim()
                val answer = fields[3].trim().removeSurrounding("\"").trim()

                if (question.isBlank() || answer.isBlank()) continue

                questions.add(RawQuestion(chapterNo, verseNo, question, answer))
            } catch (e: Exception) {
                Log.w(TAG, "Failed to parse line: ${e.message}")
            }
        }

        return questions
    }

    private fun parseCsvLine(line: String): List<String> {
        val fields = mutableListOf<String>()
        val sb = StringBuilder()
        var inQuotes = false

        for (char in line) {
            when {
                char == '"' -> inQuotes = !inQuotes
                char == ',' && !inQuotes -> {
                    fields.add(sb.toString())
                    sb.clear()
                }
                else -> sb.append(char)
            }
        }
        fields.add(sb.toString())
        return fields
    }

    /**
     * STAGE 3: Convert open-ended raw data to MCQ format.
     * FIX ISSUE 6: Use topic-based distractors instead of negation.
     * Builds an index of topic → answers, then uses answers from same topic as distractors.
     */
    private fun convertToMCQ(rawQuestions: List<RawQuestion>): List<QuizQuestionBank> {
        // Build topic → answers index for realistic distractors
        val topicAnswers = mutableMapOf<String, MutableList<String>>()
        rawQuestions.forEach { q ->
            val topics = extractKeyConcepts(q.answer)
            topics.forEach { topic ->
                topicAnswers.getOrPut(topic) { mutableListOf() }.add(q.answer)
            }
        }

        return rawQuestions.map { raw ->
            val topics = extractKeyConcepts(raw.answer)

            // FIX ISSUE 6: Get distractors from same topic (realistic wrong answers)
            val distractors = getTopicBasedDistractors(raw.answer, topics, topicAnswers, count = 3)

            // Shuffle options so correct answer isn't always first
            val options = listOf(raw.answer) + distractors
            val shuffledOptions = options.shuffled()
            val correctIndex = shuffledOptions.indexOf(raw.answer)

            val difficulty = estimateDifficulty(raw.chapterNo, raw.verseNo)

            QuizQuestionBank(
                questionHash = "${raw.question.trim().lowercase().hashCode()}",
                questionType = "MCQ",
                difficulty = difficulty,
                question = raw.question,
                chapter = raw.chapterNo,
                verse = raw.verseNo,
                yogaLevel = 0,
                optionA = shuffledOptions.getOrNull(0) ?: "",
                optionB = shuffledOptions.getOrNull(1) ?: "",
                optionC = shuffledOptions.getOrNull(2) ?: "",
                optionD = shuffledOptions.getOrNull(3) ?: "",
                correctAnswer = listOf("A", "B", "C", "D").getOrElse(correctIndex) { "A" },
                explanation = raw.answer,
                keywords = topics.joinToString(","),
                topics = topics.joinToString(","),
                generatedBy = "Bhagavad-Gita-QA Dataset",
                generationMethod = "dataset_import",
                qualityScore = 80f,
                relevanceScore = 75f,
                isVerified = true,
                isApproved = true,
                usageCount = 0
            )
        }
    }

    /**
     * FIX ISSUE 6: Get realistic distractors from same topic.
     * Uses answers from other questions on the same topic as wrong options.
     */
    private fun getTopicBasedDistractors(
        correctAnswer: String,
        topics: List<String>,
        topicAnswers: Map<String, List<String>>,
        count: Int
    ): List<String> {
        val distractors = mutableSetOf<String>()

        // Collect answers from same topics
        topics.forEach { topic ->
            val answers = topicAnswers[topic] ?: emptyList()
            answers.filter { it != correctAnswer && it.length > 10 }.forEach { distractors.add(it) }
        }

        // If not enough topic-based distractors, add general Gita distractors
        val generalDistractors = listOf(
            "By performing rituals and ceremonies",
            "By accumulating wealth and power",
            "By avoiding all worldly duties",
            "By seeking personal glory and fame",
            "By following blind tradition without understanding",
            "By relying solely on intellectual knowledge",
            "By isolating oneself from society"
        )

        for (d in generalDistractors) {
            if (distractors.size >= count) break
            if (!distractors.contains(d)) {
                distractors.add(d)
            }
        }

        return distractors.take(count).toList()
    }

    /**
     * Extract key concepts from answer text.
     */
    private fun extractKeyConcepts(answer: String): List<String> {
        val concepts = mutableListOf<String>()
        val lower = answer.lowercase()

        val conceptMap = mapOf(
            "dharma" to listOf("dharma", "duty", "righteous", "moral"),
            "karma" to listOf("karma", "action", "work", "deed"),
            "devotion" to listOf("devotion", "bhakti", "love", "worship"),
            "knowledge" to listOf("knowledge", "wisdom", "understand"),
            "soul" to listOf("soul", "atman", "self", "eternal"),
            "detachment" to listOf("detachment", "desireless", "renounce"),
            "meditation" to listOf("meditation", "concentrate", "focus", "mind"),
            "peace" to listOf("peace", "calm", "equanimity", "joy"),
            "liberation" to listOf("liberation", "moksha", "freedom"),
            "anger" to listOf("anger", "lust", "greed", "passion"),
        )

        conceptMap.forEach { (concept, keywords) ->
            if (keywords.any { lower.contains(it) }) {
                concepts.add(concept)
            }
        }

        return concepts
    }

    /**
     * STAGE 4: Normalize text (remove artifacts, fix encoding).
     */
    private fun normalizeQuestion(question: QuizQuestionBank): QuizQuestionBank {
        fun clean(text: String) = text
            .replace(Regex("\\s+"), " ")
            .replace("\\n", " ")
            .replace("\\r", " ")
            .replace(Regex("[\\u0000-\\u001F\\u007F]"), "")
            .trim()

        return question.copy(
            question = clean(question.question),
            optionA = clean(question.optionA),
            optionB = clean(question.optionB),
            optionC = clean(question.optionC),
            optionD = clean(question.optionD),
            explanation = clean(question.explanation),
            correctAnswer = clean(question.correctAnswer)
        )
    }

    /**
     * Estimate difficulty based on chapter/verse (early chapters = easier).
     */
    private fun estimateDifficulty(chapter: Int, verse: Int): Int {
        return when {
            chapter <= 6 -> (3 + chapter / 2).coerceIn(1, 10)
            chapter <= 12 -> (5 + chapter / 3).coerceIn(1, 10)
            else -> (7 + chapter / 4).coerceIn(1, 10)
        }
    }

    /**
     * Check if questions have already been imported.
     */
    suspend fun hasQuestions(): Boolean = withContext(Dispatchers.IO) {
        try {
            val count = questionBankDao.getQuestionsBySource("dataset_import")
            count > 100
        } catch (e: Exception) {
            false
        }
    }

    private data class RawQuestion(
        val chapterNo: Int,
        val verseNo: Int,
        val question: String,
        val answer: String
    )
}

package com.aipoweredgita.app.ml

import android.util.Log
import com.aipoweredgita.app.database.QuizQuestionBank
import com.google.gson.Gson
import com.google.gson.JsonSyntaxException

/**
 * PRODUCTION VALIDATION PIPELINE for LLM-generated quiz questions.
 * 
 * Validation stages:
 * 1. JSON Parse (strict) — reject malformed output
 * 2. Structure Check — verify all required fields exist
 * 3. Logic Check — 4 options, correct answer in options, non-empty question
 * 4. Duplicate Check — same hash already in DB?
 * 5. Quality Score — initial score based on content analysis
 * 
 * Returns ValidationResult with either valid QuizQuestionBank or detailed error.
 */
object QuestionValidator {
    private const val TAG = "QuestionValidator"
    private val gson = Gson()

    data class ValidationResult(
        val isValid: Boolean,
        val question: QuizQuestionBank? = null,
        val error: String? = null,
        val qualityScore: Float = 0f
    )

    /**
     * Full validation pipeline for LLM-generated JSON.
     */
    fun validateLLMOutput(
        rawOutput: String,
        chapter: Int,
        verseNum: Int,
        difficulty: Int,
        existingQuestions: List<String> = emptyList()  // FIX ISSUE 3: Semantic dedup
    ): ValidationResult {
        // STAGE 1: JSON Parse (strict)
        val parsedData = tryParseJson(rawOutput)
            ?: return ValidationResult(false, error = "Failed to parse JSON: ${rawOutput.take(100)}")

        // STAGE 2: Structure Check
        val structureError = checkStructure(parsedData)
        if (structureError != null) {
            return ValidationResult(false, error = structureError)
        }

        // STAGE 3: Logic Check
        val logicError = checkLogic(parsedData)
        if (logicError != null) {
            return ValidationResult(false, error = logicError)
        }

        // STAGE 4: FIX ISSUE 3 — Semantic dedup (normalized text comparison)
        val normalizedNew = normalizeQuestionText(parsedData.question)
        val isDuplicate = existingQuestions.any { existing ->
            normalizedNew == normalizeQuestionText(existing)
        }
        if (isDuplicate) {
            return ValidationResult(false, error = "Duplicate question (semantic match)")
        }

        // STAGE 5: Quality Score
        val qualityScore = calculateQualityScore(parsedData, difficulty)

        // All checks passed — convert to DB format
        val questionHash = "${chapter}:${verseNum}:${parsedData.question.hashCode()}"
        val question = QuizQuestionBank(
            questionHash = questionHash,
            questionType = "MCQ",
            difficulty = difficulty.coerceIn(1, 10),
            question = parsedData.question.trim(),
            chapter = chapter,
            verse = verseNum,
            yogaLevel = 0,
            optionA = parsedData.options.getOrNull(0) ?: "",
            optionB = parsedData.options.getOrNull(1) ?: "",
            optionC = parsedData.options.getOrNull(2) ?: "",
            optionD = parsedData.options.getOrNull(3) ?: "",
            correctAnswer = parsedData.options.getOrNull(parsedData.correctOptionIndex) ?: "",
            explanation = parsedData.explanation ?: "",
            keywords = parsedData.rubricKeywords?.joinToString(",") ?: "",
            topics = parsedData.theme ?: "",
            generatedBy = "LLM",
            generationMethod = "AI_generated",
            qualityScore = qualityScore,
            relevanceScore = 70f,
            isVerified = false,
            isApproved = true,
            usageCount = 0
        )

        return ValidationResult(true, question = question, qualityScore = qualityScore)
    }

    /**
     * FIX ISSUE 1: Better semantic normalization for dedup.
     * Lowercase → remove punctuation → filter words > 3 chars → sort → join.
     * This catches most paraphrases cheaply without heavy ML.
     */
    private fun normalizeQuestionText(text: String): String {
        return text
            .lowercase()
            .replace(Regex("[^a-z ]"), "")        // Remove punctuation/special chars
            .split(" ")
            .filter { it.length > 3 }             // Remove weak words (the, is, a, etc.)
            .sorted()                             // Sort to catch paraphrases
            .joinToString(" ")                    // Join back
    }

    /**
     * Stage 1: Try to parse JSON from raw LLM output.
     * Handles: raw JSON, markdown code blocks, embedded JSON.
     */
    private fun tryParseJson(raw: String): ParsedQuestion? {
        val trimmed = raw.trim()

        // Attempt 1: Direct JSON parse
        try {
            return gson.fromJson(trimmed, ParsedQuestion::class.java)
        } catch (_: JsonSyntaxException) { }

        // Attempt 2: Extract from markdown code block
        val codeBlockMatch = Regex("```(?:json)?\\s*([\\s\\S]*?)```").find(raw)
        if (codeBlockMatch != null) {
            try {
                return gson.fromJson(codeBlockMatch.groupValues[1].trim(), ParsedQuestion::class.java)
            } catch (_: JsonSyntaxException) { }
        }

        // Attempt 3: Find embedded JSON object
        val jsonMatch = Regex("\\{[^{}]*\"question\"[^{}]*\"options\"[^{}]*\\}").find(raw)
        if (jsonMatch != null) {
            try {
                return gson.fromJson(jsonMatch.value, ParsedQuestion::class.java)
            } catch (_: JsonSyntaxException) { }
        }

        // Attempt 4: Try to find ANY JSON-like structure
        val looseMatch = Regex("\\{[^{}]*\"[^\"]*\"[^{}]*\\}").find(raw)
        if (looseMatch != null) {
            try {
                return gson.fromJson(looseMatch.value, ParsedQuestion::class.java)
            } catch (_: JsonSyntaxException) { }
        }

        return null
    }

    /**
     * Stage 2: Check that all required fields exist and are non-empty.
     */
    private fun checkStructure(data: ParsedQuestion): String? {
        if (data.question.isBlank()) return "Question text is empty"
        if (data.options.isEmpty()) return "Options list is empty"
        if (data.correctOptionIndex < 0 || data.correctOptionIndex > 3) {
            return "Invalid correctOptionIndex: ${data.correctOptionIndex} (must be 0-3)"
        }
        return null
    }

    /**
     * Stage 3: Logic validation — 4 options, correct answer exists, no duplicates.
     */
    private fun checkLogic(data: ParsedQuestion): String? {
        val nonEmptyOptions = data.options.filter { it.isNotBlank() }
        if (nonEmptyOptions.size < 2) return "Need at least 2 non-empty options (got ${nonEmptyOptions.size})"

        val correctAnswer = data.options.getOrNull(data.correctOptionIndex)?.trim()
        if (correctAnswer.isNullOrBlank()) return "Correct answer (index ${data.correctOptionIndex}) is empty"

        // Check for duplicate options
        val uniqueOptions = data.options.map { it.lowercase().trim() }.toSet()
        if (uniqueOptions.size < data.options.size) return "Duplicate options detected"

        return null
    }

    /**
     * Stage 5: Calculate initial quality score (0-100).
     */
    private fun calculateQualityScore(data: ParsedQuestion, difficulty: Int): Float {
        var score = 50f  // Base score

        // Length bonuses
        if (data.question.length > 20) score += 10f
        if (data.question.length > 50) score += 10f
        if (data.explanation?.length ?: 0 > 20) score += 5f

        // Option quality
        val optionLengths = data.options.map { it.length }
        if (optionLengths.all { it > 5 }) score += 10f
        if (optionLengths.all { it > 15 }) score += 5f

        // Penalize very short questions
        if (data.question.length < 10) score -= 20f

        return score.coerceIn(0f, 100f)
    }

    /**
     * Intermediate data structure for validation.
     */
    private data class ParsedQuestion(
        val question: String = "",
        val options: List<String> = emptyList(),
        val correctOptionIndex: Int = 0,
        val explanation: String? = null,
        val type: String? = null,
        val rubricKeywords: List<String>? = null,
        val theme: String? = null
    )
}

package com.aipoweredgita.app.ml

/**
 * Adaptive difficulty engine for quizzes.
 * Adjusts question difficulty based on accuracy and response time.
 * Keeps user in the "optimal challenge zone" — not too easy, not too hard.
 */
class AdaptiveDifficultyEngine {

    // User state — persisted across sessions if needed
    data class UserState(
        var skillLevel: Int = 5,       // Dynamic 1-10 (starts at medium)
        var accuracy: Double = 0.0,    // Correct / Total
        var totalAnswered: Int = 0,
        var correctCount: Int = 0,
        var streak: Int = 0,           // Consecutive correct/wrong
        var averageResponseTime: Long = 0 // Milliseconds
    )

    /**
     * Update difficulty based on answer correctness and response time.
     * 
     * Advanced version: factors in speed.
     * Fast correct = +2 levels (user clearly knows this)
     * Slow correct = +1 level (user knows but hesitated)
     * Wrong = -1 level (user needs easier questions)
     */
    fun updateDifficulty(
        user: UserState,
        isCorrect: Boolean,
        responseTimeMs: Long = 0
    ): Int {
        user.totalAnswered++

        // Calculate response speed threshold (5 seconds = fast)
        val fast = responseTimeMs > 0 && responseTimeMs < 5000

        when {
            isCorrect && fast -> {
                user.skillLevel += 2  // Fast correct — push harder
                user.streak = if (user.streak > 0) user.streak + 1 else 1
            }
            isCorrect -> {
                user.skillLevel += 1  // Correct but slow — gentle push
                user.streak = if (user.streak > 0) user.streak + 1 else 1
            }
            else -> {
                user.skillLevel -= 1  // Wrong — ease up
                user.streak = if (user.streak < 0) user.streak - 1 else -1
                user.correctCount = user.correctCount.coerceAtLeast(0)
            }
        }

        if (isCorrect) user.correctCount++

        // Clamp between 1-10
        user.skillLevel = user.skillLevel.coerceIn(1, 10)

        // Update accuracy
        user.accuracy = if (user.totalAnswered > 0) {
            user.correctCount.toDouble() / user.totalAnswered
        } else 0.0

        // Track rolling average response time
        if (responseTimeMs > 0) {
            user.averageResponseTime = if (user.averageResponseTime == 0L) {
                responseTimeMs
            } else {
                (user.averageResponseTime * 0.7 + responseTimeMs * 0.3).toLong()
            }
        }

        return user.skillLevel
    }

    /**
     * Simple version — just correct/wrong, no timing.
     */
    fun updateDifficultySimple(user: UserState, isCorrect: Boolean): Int {
        return updateDifficulty(user, isCorrect, responseTimeMs = 0)
    }

    /**
     * Select next question from pool based on current skill level.
     * Filters to skillLevel ± 1 range, picks random.
     * Falls back to wider range if pool is empty.
     */
    fun <T> selectNextQuestion(
        questions: List<T>,
        user: UserState,
        difficultySelector: (T) -> Int
    ): T? {
        val targetDifficulty = user.skillLevel

        // Try exact range first (±1)
        var pool = questions.filter { q ->
            val d = difficultySelector(q)
            d in (targetDifficulty - 1)..(targetDifficulty + 1)
        }

        // Widen range if no questions available
        if (pool.isEmpty()) {
            pool = questions.filter { q ->
                val d = difficultySelector(q)
                d in (targetDifficulty - 2)..(targetDifficulty + 2)
            }
        }

        // Last resort: any question
        if (pool.isEmpty()) {
            pool = questions
        }

        return pool.randomOrNull()
    }

    /**
     * Generate an LLM prompt for a question at the given difficulty.
     * FIX ISSUE 3: Hard constraint prompt — enforces strict JSON output.
     */
    fun generateLLMPrompt(difficulty: Int, chapter: Int, verseNum: Int, translation: String, user: UserState? = null): String {
        val difficultyLabel = when (difficulty) {
            1, 2 -> "Very Easy (basic recall)"
            3, 4 -> "Easy (simple understanding)"
            5, 6 -> "Medium (apply knowledge)"
            7, 8 -> "Hard (analyze and reason)"
            else -> "Very Hard (deep philosophical reasoning)"
        }

        val performanceContext = if (user != null) {
            """
            User Performance Context:
            - Current Accuracy: ${String.format("%.0f%%", user.accuracy * 100)}
            - Current Streak: ${user.streak} (Positive = correct, Negative = wrong)
            - Current Skill Level: ${user.skillLevel}/10

            Instruction: Adjust the complexity and 'trickiness' of the wrong options based on this performance.
            """.trimIndent()
        } else ""

        return """
            You are generating a quiz question for the Bhagavad Gita.

            Verse: Chapter $chapter, Verse $verseNum
            Translation: $translation
            Difficulty: $difficulty/10 ($difficultyLabel)

            $performanceContext

            Rules:
            - Return STRICT JSON ONLY. No text before or after JSON.
            - The "answer" MUST be exactly one of the 4 options.
            - All 4 options must be similar in length and style.
            - No explanation outside JSON.

            Output format:
            {"question":"...","options":["A","B","C","D"],"correctOptionIndex":0,"explanation":"..."}

            Respond with ONLY the JSON object.
        """.trimIndent()
    }

    companion object {
        private const val PREF_SKILL_LEVEL = "quiz_skill_level"
        private const val PREF_ACCURACY = "quiz_accuracy"
        private const val PREF_TOTAL_ANSWERED = "quiz_total_answered"
        private const val PREF_CORRECT_COUNT = "quiz_correct_count"
        private const val PREF_STREAK = "quiz_streak"
        private const val PREF_AVG_TIME = "quiz_avg_time"

        fun saveState(state: UserState, prefs: android.content.SharedPreferences) {
            prefs.edit().apply {
                putInt(PREF_SKILL_LEVEL, state.skillLevel)
                putFloat(PREF_ACCURACY, state.accuracy.toFloat())
                putInt(PREF_TOTAL_ANSWERED, state.totalAnswered)
                putInt(PREF_CORRECT_COUNT, state.correctCount)
                putInt(PREF_STREAK, state.streak)
                putLong(PREF_AVG_TIME, state.averageResponseTime)
                apply()
            }
        }

        fun loadState(prefs: android.content.SharedPreferences): UserState {
            return UserState(
                skillLevel = prefs.getInt(PREF_SKILL_LEVEL, 5),
                accuracy = prefs.getFloat(PREF_ACCURACY, 0f).toDouble(),
                totalAnswered = prefs.getInt(PREF_TOTAL_ANSWERED, 0),
                correctCount = prefs.getInt(PREF_CORRECT_COUNT, 0),
                streak = prefs.getInt(PREF_STREAK, 0),
                averageResponseTime = prefs.getLong(PREF_AVG_TIME, 0L)
            )
        }
    }
}

package com.aipoweredgita.app.ml

import android.content.Context
import android.content.SharedPreferences
import android.util.Log
import com.aipoweredgita.app.R
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import java.io.File

/**
 * Features that depend on AI models.
 */
enum class AppFeature { VOICE, QUIZ }

data class ModelRuntimeDecision(
    val feature: AppFeature,
    val selectedPreference: String,
    val tierLabel: String,
    val useProxy: Boolean,
    val modelPath: String?,
    val displayName: String
)

/**
 * Manages model availability for different features.
 *
 * Model Strategy:
 * - **Qwen3 0.6B (~614MB)** → Primary text model (Quiz + Studio, fast, multilingual)
 * - **Gemma 4 2B (~2.58GB)** → Voice Studio + Studio Quiz (flagship performance)
 *
 * Features gracefully degrade:
 * - If Gemma 4 is missing → falls back to Qwen3
 */
class ModelAvailability(appContext: Context) {

    private val TAG = "ModelAvailability"
    private val context = appContext.applicationContext
    private val modelsDir = File(context.filesDir, "ml_models")
    private val prefs = context.getSharedPreferences("app_prefs", Context.MODE_PRIVATE)

    private val _selectedModel = MutableStateFlow(prefs.getString("selected_ai_model", "Auto (Recommended)") ?: "Auto (Recommended)")
    val selectedModel: StateFlow<String> = _selectedModel.asStateFlow()

    private val preferenceListener = SharedPreferences.OnSharedPreferenceChangeListener { sharedPreferences, key ->
        if (key == "selected_ai_model") {
            val newVal = sharedPreferences.getString(key, "Auto (Recommended)") ?: "Auto (Recommended)"
            Log.d(TAG, "Model preference changed: $newVal")
            _selectedModel.value = newVal
        }
    }

    init {
        prefs.registerOnSharedPreferenceChangeListener(preferenceListener)
    }

    // Model size thresholds for integrity validation
    private val qwen3MinSize = 300_000_000L    // ~300MB floor for 0.6B
    private val gemma4MinSize = 1_000_000_000L // ~1GB floor for 2B models (handles various quantizations)

    fun isQwen3Available(): Boolean = getQwen3Path() != null
    fun isGemma4Available(): Boolean = getGemma4Path() != null

    fun getQwen3Path(): String? = validatedPath("qwen3-0.6b-int4.litertlm", qwen3MinSize)
    fun getGemma4Path(): String? = validatedPath("gemma-4-E2B-it.litertlm", gemma4MinSize)

    private fun resolveModelPath(feature: AppFeature, selected: String): String? {
        val qwen3Path = getQwen3Path()
        val gemma4Path = getGemma4Path()
        val qwen3Exists = qwen3Path != null
        val gemma4Exists = gemma4Path != null

        val resolved = when {
            selected.contains("NVIDIA", ignoreCase = true) -> null
            selected.contains("Groq", ignoreCase = true) -> null
            selected.contains("Qwen3") && qwen3Exists -> {
                if (feature == AppFeature.QUIZ) qwen3Path else null
            }
            selected.contains("Gemma 4") && gemma4Exists -> gemma4Path
            else -> {
                if (feature == AppFeature.QUIZ) {
                    qwen3Path ?: gemma4Path
                } else {
                    // VOICE uses only Gemma; Qwen removed from chat path.
                    // null → ViewModel falls back to cloud proxy gracefully.
                    gemma4Path
                }
            }
        }

        return resolved
    }

    fun getRuntimeDecision(feature: AppFeature): ModelRuntimeDecision {
        val selected = _selectedModel.value
        val tier = com.aipoweredgita.app.utils.DeviceTierDetector.detect(context)
        val useProxy = when {
            selected.contains("NVIDIA", ignoreCase = true) -> true
            selected.contains("Groq", ignoreCase = true) -> true
            feature == AppFeature.VOICE &&
                (tier == com.aipoweredgita.app.utils.DeviceTier.LOW || tier == com.aipoweredgita.app.utils.DeviceTier.LOW_MID) -> true
            else -> false
        }
        val modelPath = if (useProxy) null else resolveModelPath(feature, selected)
        val displayName = when {
            useProxy && selected.contains("NVIDIA", ignoreCase = true) -> "NVIDIA 70B (Cloud)"
            useProxy && selected.contains("Groq", ignoreCase = true) -> "Groq (Cloud)"
            useProxy -> "Cloud Proxy"
            modelPath == null -> "No local model"
            modelPath.contains("qwen3", ignoreCase = true) -> "Qwen3 0.6B"
            modelPath.contains("gemma", ignoreCase = true) -> "Gemma 4 2B (Advanced)"
            else -> File(modelPath).name
        }

        Log.d(
            TAG,
            "Runtime decision for $feature: display=$displayName useProxy=$useProxy " +
                "selected=$selected tier=${tier.label} path=${modelPath?.let { File(it).name } ?: "NONE"}"
        )

        return ModelRuntimeDecision(
            feature = feature,
            selectedPreference = selected,
            tierLabel = tier.label,
            useProxy = useProxy,
            modelPath = modelPath,
            displayName = displayName
        )
    }

    /**
     * Resolve the best model path for a feature based on current user preference and availability.
     */
    fun getResolvedModelPath(feature: AppFeature): String? {
        return getRuntimeDecision(feature).modelPath
    }

    fun isGemmaRunning(feature: AppFeature): Boolean {
        val path = getRuntimeDecision(feature).modelPath
        return path != null && path.contains("gemma", ignoreCase = true)
    }

    /**
     * Get the best model for TEXT features (quiz, Studio) respecting user preference.
     */
    fun getResolvedTextModelPath(selectedPreference: String): String? {
        return resolveModelPath(AppFeature.QUIZ, selectedPreference)
    }

    /**
     * Get the best model for TEXT features (quiz, Studio) based on availability fallback.
     * Priority: Qwen3 0.6B → Gemma 4 2B
     */
    fun getBestTextModelPath(): String? {
        return getQwen3Path()
            ?: getGemma4Path().also {
                if (it != null) Log.w(TAG, "Using Gemma 4 as text fallback — smaller models not available")
            }
    }

    /**
     * Get the best model for VOICE features (Voice Studio, Studio Quiz).
     */
    fun getBestVoiceModelPath(): String? {
        return getResolvedModelPath(AppFeature.VOICE)
    }

    fun areVoiceFeaturesAvailable(): Boolean {
        return isGemma4Available() || isQwen3Available()
    }

    fun updateSelectedModel(newModel: String) {
        prefs.edit().putString("selected_ai_model", newModel).apply()
        _selectedModel.value = newModel
    }

    /**
     * Get a user-friendly message about what's missing.
     */
    fun getMissingModelMessage(feature: AppFeature): String {
        return when (feature) {
            AppFeature.VOICE -> context.getString(R.string.model_missing_voice)
            AppFeature.QUIZ -> context.getString(R.string.model_missing_quiz)
        }
    }

    private fun validatedPath(fileName: String, minSize: Long): String? {
        val file = File(modelsDir, fileName)
        return if (file.exists() && file.length() > minSize) file.absolutePath else null
    }

    companion object {
        @Volatile
        private var instance: ModelAvailability? = null

        fun getInstance(context: Context): ModelAvailability {
            return instance ?: synchronized(this) {
                instance ?: ModelAvailability(context.applicationContext).also { instance = it }
            }
        }
    }
}

package com.aipoweredgita.app.ml

import android.content.Context
import android.util.Log
import com.google.ai.edge.litertlm.Engine
import com.google.ai.edge.litertlm.EngineConfig
import com.google.ai.edge.litertlm.SamplerConfig
import com.google.ai.edge.litertlm.ConversationConfig
import com.google.ai.edge.litertlm.Conversation
import com.google.ai.edge.litertlm.Backend
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.cancel
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.launch
import kotlinx.coroutines.runBlocking
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.withContext
import kotlinx.coroutines.withTimeoutOrNull

/**
 * PRODUCTION SAFE LiteRT-LM Voice Chat Engine.
 * Supports both Gemma and Qwen models with model-aware formatting and cleaning.
 */
class LiteRtLmVoiceChatEngine(private val context: Context) {

    private val engineMutex = Mutex()
    private var engine: Engine? = null
    private var conversation: Conversation? = null
    private var cleanerScope = CoroutineScope(Dispatchers.Default + Job())

    private var isInitialized = false
    private var modelPath: String? = null
    private var currentSystemInstruction: String? = null

    // ─── Adaptive device config ───────────────────────────────────────────────
    private var timeoutMs     : Long = 240_000L
    private var currentSampler: com.google.ai.edge.litertlm.SamplerConfig = SAMPLER

    companion object {
        private const val TAG = "LiteRtLmVoiceChat"
        private const val MAX_TOKENS = 2048  // Qwen3 0.6B works better with smaller window
        private const val MAX_PROMPT_CHARS = 800  // keep prompt short, leave room for output

        private val SAMPLER = SamplerConfig(
            topK        = 40,   // wider sampling
            topP        = 0.95,
            temperature = 0.7   // higher = less early stopping
        )

        private const val DEFAULT_INSTRUCTION =
            "You are Krishna from the Bhagavad Gita. Answer clearly."
    }

    // ─── Init ─────────────────────────────────────────────────────────────────

    suspend fun initialize(
        path      : String,
        maxTokens : Int  = MAX_TOKENS,
        timeoutMs : Long = 240_000L,
        sampler   : com.google.ai.edge.litertlm.SamplerConfig = SAMPLER
    ): Boolean = engineMutex.withLock {
            return@withLock try {
                closeInternal()
                cleanerScope       = CoroutineScope(Dispatchers.Default + Job())
                this.timeoutMs     = timeoutMs
                this.currentSampler = sampler

                val newEngine = Engine(
                    EngineConfig(
                        modelPath    = path,
                        maxNumTokens = maxTokens,
                        backend      = Backend.CPU()
                    )
                )
                newEngine.initialize()

                engine       = newEngine
                conversation = newEngine.createConversation(ConversationConfig(samplerConfig = sampler))
                isInitialized = true
                modelPath     = path
                Log.d(TAG, "LiteRT-LM initialized ($maxTokens tokens, timeout=${timeoutMs}ms)")
                true
            } catch (e: Exception) {
                Log.e(TAG, "LiteRT-LM init failed", e)
                false
            }
        }

    // ─── Send Message ─────────────────────────────────────────────────────────

    suspend fun sendMessage(
        prompt: String,
        onPartial: ((String) -> Unit)? = null,
        onCleaned: ((String) -> Unit)? = null
    ): String = engineMutex.withLock {

        if (!isInitialized || conversation == null) {
            return@withLock "Error: Engine not initialized"
        }

        val systemInstruction = currentSystemInstruction ?: DEFAULT_INSTRUCTION

        val isQwen = modelPath?.contains("qwen", ignoreCase = true) == true
        val formattedPrompt = buildString {
            if (isQwen) {
                append("<|im_start|>system\n")
                append(systemInstruction.trim())
                append("<|im_end|>\n")
                append("<|im_start|>user\n")
                append(prompt.trim().take(MAX_PROMPT_CHARS))
                append("<|im_end|>\n")
                append("<|im_start|>assistant\n")
            } else {
                // Gemma 4 chat template
                append("<start_of_turn>system\n")
                append(systemInstruction.trim())
                append("<end_of_turn>\n")
                append("<start_of_turn>user\n")
                append(prompt.trim().take(MAX_PROMPT_CHARS))
                append("<end_of_turn>\n")
                append("<start_of_turn>model\n")
            }
        }

        val responseBuffer = StringBuilder()
        val answerBuffer   = StringBuilder()
        var inThinkingBlock = false
        var lastSentLength  = 0

        return@withLock try {
            val completed = withTimeoutOrNull(timeoutMs) {
                conversation!!.sendMessageAsync(formattedPrompt)
                    .catch { throw it }
                    .collect { message ->
                        val chunk = message.toString()
                        if (chunk.isEmpty()) return@collect

                        Log.v(TAG, "Chunk: '$chunk'")
                        responseBuffer.append(chunk)

                        val hasThinkStart = chunk.contains("<think>") || chunk.contains("<|think")  || chunk.contains("<thought>")
                        val hasThinkEnd   = chunk.contains("</think>") || chunk.contains("<|think_end") || chunk.contains("</thought>")

                        when {
                            hasThinkEnd -> {
                                inThinkingBlock = false
                                val endTags = listOf("</think>", "</thought>", "<|think_end|>")
                                var endPos = -1
                                for (tag in endTags) {
                                    val idx = chunk.lastIndexOf(tag)
                                    if (idx != -1) endPos = maxOf(endPos, idx + tag.length)
                                }
                                val afterThink = if (endPos != -1) chunk.substring(endPos) else chunk
                                emitClean(afterThink, answerBuffer, onPartial, lastSentLength)
                                    .also { lastSentLength = it }
                            }
                            inThinkingBlock -> {
                                // skip — inside thinking block
                            }
                            hasThinkStart -> {
                                inThinkingBlock = true
                                val startPos = listOf("<think>", "<|think", "<thought>")
                                    .mapNotNull { tag -> chunk.indexOf(tag).takeIf { it != -1 } }
                                    .minOrNull() ?: chunk.length
                                emitClean(chunk.substring(0, startPos), answerBuffer, onPartial, lastSentLength)
                                    .also { lastSentLength = it }
                            }
                            else -> {
                                emitClean(chunk, answerBuffer, onPartial, lastSentLength)
                                    .also { lastSentLength = it }
                            }
                        }
                    }
            }

            if (completed == null) {
                Log.w(TAG, "Generation timed out")
                stopResponse()
                onPartial?.invoke(" (response was cut short)")
            }

            val rawFinal = responseBuffer.toString()
            Log.d(TAG, "RAW:\n$rawFinal")

            // Extract answer after last thinking marker
            val markers = listOf("</think>", "</thought>", "<turn|>", "<|turn>", "<end_of_turn>", "<start_of_turn>")
            var lastMarker = -1
            for (m in markers) {
                val idx = rawFinal.lastIndexOf(m)
                if (idx != -1) lastMarker = maxOf(lastMarker, idx + m.length)
            }

            val extracted = when {
                lastMarker != -1          -> rawFinal.substring(lastMarker)
                answerBuffer.isNotEmpty() -> answerBuffer.toString()
                else                      -> rawFinal
            }

            val basicCleaned = com.aipoweredgita.app.util.TextUtils.cleanLlmOutput(extracted)
            Log.d(TAG, "CLEANED:\n$basicCleaned")

            // Deep clean on background thread, callback on Main
            cleanerScope.launch {
                try {
                    val deepCleaned = com.aipoweredgita.app.util.TextUtils.deepClean(basicCleaned)
                    withContext(Dispatchers.Main) {
                        onCleaned?.invoke(deepCleaned)
                    }
                } catch (e: Exception) {
                    Log.e(TAG, "Deep clean failed", e)
                    withContext(Dispatchers.Main) {
                        onCleaned?.invoke(basicCleaned) // fallback to basic
                    }
                }
            }

            basicCleaned
        } catch (e: Exception) {
            Log.e(TAG, "Inference failed, recovering", e)
            recoverModel()
            "Error: ${e.message}"
        }
    }

    /** Cleans a chunk and emits via onPartial. Returns updated lastSentLength. */
    private fun emitClean(
        chunk: String,
        buffer: StringBuilder,
        onPartial: ((String) -> Unit)?,
        lastSentLength: Int
    ): Int {
        val cleaned = cleanChunk(chunk)
        if (cleaned.isEmpty()) return lastSentLength
        buffer.append(cleaned)
        val current = buffer.toString()
        return if (current.length > lastSentLength) {
            onPartial?.invoke(current)
            current.length
        } else lastSentLength
    }

    private fun cleanChunk(chunk: String): String = chunk
        .replace(Regex("<think>.*?</think>",    RegexOption.DOT_MATCHES_ALL), "")
        .replace(Regex("<thought>.*?</thought>", RegexOption.DOT_MATCHES_ALL), "")
        .replace("<think>", "").replace("</think>", "")
        .replace("<thought>", "").replace("</thought>", "")
        .replace("<start_of_turn>", "").replace("<end_of_turn>", "")
        .replace("<|turn>", "").replace("<turn|>", "")
        .replace("<|im_start|>", "").replace("<|im_end|>", "")
        .replace("system\n", "").replace("assistant\n", "")
        .replace("model\n", "").replace("user\n", "")
        .replace(Regex("[\\u200B\\u200C\\u200D\\uFEFF\\u00AD]"), "")
        .replace(Regex("[ \t]{2,}"), " ")
        .replace(Regex("\n{3,}"), "\n\n")

    // ─── Controls ─────────────────────────────────────────────────────────────

    suspend fun updateSampler(sampler: com.google.ai.edge.litertlm.SamplerConfig) {
        engineMutex.withLock {
            currentSampler = sampler
            try {
                conversation?.close()
                conversation = engine?.createConversation(ConversationConfig(samplerConfig = sampler))
                Log.d(TAG, "Sampler updated: topK=${sampler.topK} temp=${sampler.temperature}")
            } catch (_: Exception) {}
        }
    }

    fun stopResponse() {
        try { conversation?.cancelProcess() } catch (_: Exception) {}
    }

    suspend fun updateSystemInstruction(instruction: String) {
        currentSystemInstruction = instruction
    }

    suspend fun resetConversation() {
        engineMutex.withLock {
            try {
                conversation?.close()
                conversation = engine?.createConversation(ConversationConfig(samplerConfig = currentSampler))
            } catch (_: Exception) {}
        }
    }

    private suspend fun recoverModel() {
        Log.w(TAG, "Recovering model...")
        modelPath?.let { initialize(it) }
    }

    /**
     * Non-blocking close — dispatches cleanup to engine scope.
     * Caller must NOT rely on immediate completion; use [closeBlocking] if needed.
     */
    fun close() {
        cleanerScope.launch {
            engineMutex.withLock { closeInternal() }
        }
    }

    /** Blocking close for lifecycle-critical paths only (e.g. onCleared on IO thread). */
    fun closeBlocking() {
        runBlocking { engineMutex.withLock { closeInternal() } }
    }

    private fun closeInternal() {
        try { cleanerScope.cancel() } catch (_: Exception) {}
        try { conversation?.close() } catch (_: Exception) {}
        try { engine?.close() } catch (_: Exception) {}
        conversation  = null
        engine        = null
        isInitialized = false
    }
}

package com.aipoweredgita.app.ml

import kotlin.math.exp
import kotlin.math.ln
import kotlin.math.sqrt

/**
 * Item Response Theory (IRT) - Gold Standard for Adaptive Testing
 *
 * Models the probability of answering a question correctly based on:
 * - Student ability (theta)
 * - Item difficulty (b)
 * - Item discrimination (a)
 * - Guessing parameter (c)
 */
data class ItemParameters(
    val difficulty: Double,      // b parameter: -3 (easy) to +3 (hard)
    val discrimination: Double,  // a parameter: 0-2 (how well it discriminates)
    val guessing: Double = 0.2   // c parameter: 0-0.3 (chance of guessing)
)

data class StudentAbility(
    val studentId: String,
    var theta: Double = 0.0,     // Ability estimate: -4 to +4
    val standardError: Double = 1.0,
    val questionHistory: MutableList<QuestionResponse> = mutableListOf()
)

data class QuestionResponse(
    val questionId: String,
    val isCorrect: Boolean,
    val thetaBefore: Double,
    val thetaAfter: Double,
    val timestamp: Long
)

class ItemResponseTheoryEngine {

    companion object {
        private const val MAX_ITERATIONS = 10
        private const val CONVERGENCE_THRESHOLD = 0.001
    }

    /**
     * Calculate probability of correct response using 3-Parameter Logistic Model
     * P(θ) = c + (1 - c) / (1 + exp(-1.7 * a * (θ - b)))
     */
    fun probabilityCorrect(
        ability: Double,
        item: ItemParameters
    ): Double {
        val a = item.discrimination
        val b = item.difficulty
        val c = item.guessing

        val exponent = -1.7 * a * (ability - b)
        val probability = c + (1 - c) / (1 + exp(exponent))

        return probability.coerceIn(0.0, 1.0)
    }

    /**
     * Update student ability using Maximum Likelihood Estimation
     * Implements Newton-Raphson method for parameter estimation
     */
    fun updateAbility(
        student: StudentAbility,
        responses: List<Pair<ItemParameters, Boolean>>
    ): StudentAbility {
        var theta = student.theta
        var iterations = 0

        while (iterations < MAX_ITERATIONS) {
            val (firstDerivative, secondDerivative) = calculateDerivatives(theta, responses)

            if (abs(firstDerivative) < CONVERGENCE_THRESHOLD) break

            val deltaTheta = firstDerivative / secondDerivative
            theta -= deltaTheta

            // Constrain theta to reasonable range
            theta = theta.coerceIn(-4.0, 4.0)

            iterations++
        }

        // Calculate standard error (Fisher Information)
        val fisherInfo = calculateFisherInformation(theta, responses)
        val standardError = if (fisherInfo > 0) 1.0 / sqrt(fisherInfo) else 1.0

        return student.copy(
            theta = theta,
            standardError = standardError
        )
    }

    /**
     * Estimate item difficulty from student responses
     * When student gets 50% correct, that's the difficulty level
     */
    fun estimateItemDifficulty(
        studentAbility: Double,
        correctCount: Int,
        totalCount: Int
    ): Double {
        if (totalCount == 0) return 0.0

        val successRate = correctCount.toDouble() / totalCount

        // Use logistic function to estimate difficulty
        // If successRate = 0.5, difficulty = studentAbility
        return when {
            successRate <= 0.01 -> studentAbility - 2.5
            successRate >= 0.99 -> studentAbility + 2.5
            else -> {
                val p = successRate.coerceIn(0.01, 0.99)
                studentAbility + (ln((1 - p) / p) / 1.7)
            }
        }
    }

    /**
     * Get recommended question difficulty for a student
     * Aim for 70% success rate (optimal learning zone)
     */
    fun getRecommendedDifficulty(
        student: StudentAbility,
        targetSuccessRate: Double = 0.7
    ): Double {
        val targetP = targetSuccessRate.coerceIn(0.1, 0.9)

        // Solve for difficulty: P(θ) = 0.7
        // Assume discrimination = 1.0 (average), guessing = 0.2
        val a = 1.0
        val c = 0.2

        return student.theta + (ln((1 - c) / (targetP - c)) / (1.7 * a))
    }

    private fun calculateDerivatives(
        theta: Double,
        responses: List<Pair<ItemParameters, Boolean>>
    ): Pair<Double, Double> {
        var firstDerivative = 0.0
        var secondDerivative = 0.0

        for ((item, isCorrect) in responses) {
            val a = item.discrimination
            val c = item.guessing

            val p = probabilityCorrect(theta, item)
            val q = 1.0 - p

            // First derivative: d log L / dθ (with guessing correction)
            val dL = if (isCorrect) {
                a * (p - c) * q / (p * (1.0 - c))
            } else {
                -a * (p - c) / (1.0 - c)
            }
            firstDerivative += dL

            // Second derivative: d² log L / dθ² (with guessing correction)
            val d2L = -a * a * (p - c) * (1.0 - p) * (c * (1.0 - p) + (p - c) * q) / (p * p * (1.0 - c) * (1.0 - c))
            secondDerivative += d2L
        }

        return Pair(firstDerivative, secondDerivative)
    }

    private fun calculateFisherInformation(
        theta: Double,
        responses: List<Pair<ItemParameters, Boolean>>
    ): Double {
        var fisherInfo = 0.0

        for ((item, _) in responses) {
            val p = probabilityCorrect(theta, item)
            val q = 1.0 - p
            val a = item.discrimination

            fisherInfo += a * a * p * q
        }

        return fisherInfo
    }

    private fun abs(value: Double): Double = kotlin.math.abs(value)
}

/**
 * SimplifiedIRT for faster computation
 * Less accurate but much faster for real-time use
 */
class SimplifiedIRT {

    /**
     * Update ability using simple proportional control
     * Faster but less accurate than full IRT
     */
    fun updateAbilitySimple(
        currentAbility: Double,
        isCorrect: Boolean,
        expectedDifficulty: Double
    ): Double {
        val targetP = 0.7 // 70% success rate
        val actualP = if (isCorrect) 1.0 else 0.0
        val error = actualP - targetP

        // Learning rate decreases as error gets smaller
        val learningRate = 0.3

        // Adjust ability towards the difficulty where we'd expect 70% success
        val targetAbility = expectedDifficulty

        // Update ability with learning rate and error signal
        val deltaAbility = learningRate * error * 0.5
        val newAbility = currentAbility + (targetAbility - currentAbility) * 0.1 + deltaAbility

        return newAbility.coerceIn(-4.0, 4.0)
    }
}

package com.aipoweredgita.app.coin

/** Single coin transaction entry for history display. */
data class CoinEntry(
    val amount: Int,
    val description: String,
    val timestamp: Long,
    val type: CoinTxType
)

enum class CoinTxType { EARN, SPEND }

package com.aipoweredgita.app.coin

import android.content.Context
import android.util.Log
import org.json.JSONArray
import org.json.JSONException
import org.json.JSONObject

/**
 * Persists coin transaction history in SharedPreferences.
 * Thread-safe via synchronized. Handles JSON corruption gracefully — silently
 * resets to empty rather than crashing.
 */
object CoinTransactionLogger {
    private const val PREFS_NAME = "coin_tracker"
    private const val KEY = "transactions"
    private const val MAX = 200
    private const val TAG = "CoinTxLogger"

    fun log(context: Context, amount: Int, description: String) {
        if (amount == 0) return
        val safeDesc = description.take(120)
        synchronized(this) {
            val prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
            val arr = readJson(prefs)
            val entry = JSONObject().apply {
                put("amount", amount)
                put("description", safeDesc)
                put("timestamp", System.currentTimeMillis())
                put("type", if (amount > 0) CoinTxType.EARN.name else CoinTxType.SPEND.name)
            }
            arr.put(entry)
            while (arr.length() > MAX) arr.remove(0)
            prefs.edit().putString(KEY, arr.toString()).apply()
        }
    }

    fun syncFromServer(context: Context, serverHistory: List<com.aipoweredgita.app.network.CoinHistoryEntry>) {
        synchronized(this) {
            val prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
            // Server stores timestamps in UTC ("yyyy-MM-dd HH:mm:ss" without timezone suffix).
            // We MUST parse with UTC or Java will interpret them as device local time, which
            // shifts timestamps by the device's UTC offset (e.g. IST = +5:30 → 5.5 hr error).
            val fmt = java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss", java.util.Locale.US).apply {
                timeZone = java.util.TimeZone.getTimeZone("UTC")
            }

            // Parse server entries (oldest first — server comes newest-first so reverse)
            val serverEntries = serverHistory.reversed().takeLast(MAX)

            // Find the oldest timestamp in the server data
            val oldestServerTs = serverEntries.minOfOrNull { entry ->
                try { fmt.parse(entry.created_at)?.time ?: Long.MAX_VALUE }
                catch (_: Exception) { Long.MAX_VALUE }
            } ?: Long.MAX_VALUE

            // Read existing local entries and keep only those OLDER than the oldest server entry
            // (avoids duplicates while preserving history the server no longer returns)
            val existing = readJson(prefs)
            val preservedLocal = mutableListOf<JSONObject>()
            for (i in 0 until existing.length()) {
                try {
                    val obj = existing.getJSONObject(i)
                    val ts = obj.optLong("timestamp", Long.MAX_VALUE)
                    if (ts < oldestServerTs) preservedLocal.add(obj)
                } catch (_: Exception) { /* skip corrupted */ }
            }

            // Build merged array: old local entries first, then server entries
            val arr = JSONArray()
            preservedLocal.forEach { arr.put(it) }
            serverEntries.forEach { entry ->
                val obj = JSONObject().apply {
                    put("amount", entry.amount)
                    put("description", entry.description.take(120))
                    val ts = try { fmt.parse(entry.created_at)?.time ?: System.currentTimeMillis() }
                             catch (_: Exception) { System.currentTimeMillis() }
                    put("timestamp", ts)
                    put("type", entry.type)
                }
                arr.put(obj)
            }

            // Trim to MAX keeping the newest
            while (arr.length() > MAX) arr.remove(0)
            prefs.edit().putString(KEY, arr.toString()).apply()
        }
    }

    fun getHistory(context: Context): List<CoinEntry> {
        val prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        val arr = readJson(prefs)
        val result = mutableListOf<CoinEntry>()
        for (i in 0 until arr.length()) {
            try {
                val obj = arr.getJSONObject(i)
                result.add(CoinEntry(
                    amount = obj.optInt("amount", 0),
                    description = obj.optString("description", ""),
                    timestamp = obj.optLong("timestamp", System.currentTimeMillis()),
                    type = try { CoinTxType.valueOf(obj.optString("type", CoinTxType.EARN.name)) }
                        catch (_: IllegalArgumentException) { CoinTxType.EARN }
                ))
            } catch (_: JSONException) {
                // skip corrupted entry
            }
        }
        return result.reversed()
    }

    fun clear(context: Context) {
        synchronized(this) {
            context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
                .edit().remove(KEY).apply()
        }
    }

    private fun readJson(prefs: android.content.SharedPreferences): JSONArray {
        val raw = prefs.getString(KEY, null) ?: return JSONArray()
        return try { JSONArray(raw) }
        catch (e: JSONException) {
            Log.w(TAG, "Corrupted transaction log, resetting: ${e.message}")
            prefs.edit().remove(KEY).apply()
            JSONArray()
        }
    }
}

package com.aipoweredgita.app.coin

/**
 * Central coin reward algorithm for quiz completions.
 * Pure calculation — no side effects, no dependencies.
 *
 * All inputs are clamped to valid ranges internally so callers
 * can pass raw values without pre-validation.
 */
object CoinRewardEngine {

    data class Input(
        val score: Int,
        val totalQuestions: Int,
        val segmentCorrectMap: Map<String, Int> = emptyMap(),
        val currentStreakDays: Int = 0,
        val dailyCheckinDay: Int = 0,     // 1..7 from DailyRewardsTracker
        val yogaLevel: Int = 1,
        val yogaMultiplier: Float = 1f,
    ) {
        /** Validates and normalises all values, returning a clean copy. */
        fun sanitised(): Input {
            val clampedStreak = currentStreakDays.coerceAtLeast(0)
            val clampedCheckin = dailyCheckinDay.coerceIn(0, 7)
            val clampedMultiplier = yogaMultiplier.coerceAtLeast(0f)
            val safeScore = score.coerceAtLeast(0)
            val safeTotal = totalQuestions.coerceAtLeast(0)
            val safeSegments = segmentCorrectMap.mapValues { it.value.coerceAtLeast(0) }
                .filter { it.value > 0 }
            return if (clampedStreak == currentStreakDays && clampedCheckin == dailyCheckinDay
                && clampedMultiplier == yogaMultiplier && safeScore == score
                && safeTotal == totalQuestions && safeSegments == segmentCorrectMap) this
            else copy(score = safeScore, totalQuestions = safeTotal,
                segmentCorrectMap = safeSegments, currentStreakDays = clampedStreak,
                dailyCheckinDay = clampedCheckin, yogaMultiplier = clampedMultiplier)
        }
    }

    data class Result(
        val baseCoins: Int,
        val accuracyBonus: Int,
        val streakBonus: Int,
        val checkinBonus: Int,
        val totalCoins: Int,
        val segmentCoins: Map<String, Int>,
        val breakdown: String,
    )

    fun calculate(input: Input): Result {
        val safe = input.sanitised()

        val accuracy = if (safe.totalQuestions > 0) {
            (safe.score.toFloat() / safe.totalQuestions).coerceIn(0f, 1f)
        } else 0f

        val base = 4
        val accuracyBonus = (accuracy * accuracy * 6f).toInt().coerceIn(0, 6)
        val streakBonus = (safe.currentStreakDays / 5).coerceAtMost(3)
        val checkinBonus = when (safe.dailyCheckinDay) {
            7 -> 3
            5, 6 -> 2
            in 2..4 -> 1
            else -> 0
        }

        val preMultiplier = base + accuracyBonus + streakBonus + checkinBonus
        val total = (preMultiplier * safe.yogaMultiplier).toInt().coerceAtLeast(0)

        val segCoins = if (safe.segmentCorrectMap.isNotEmpty()) {
            val totalCorrect = safe.segmentCorrectMap.values.sum().coerceAtLeast(1)
            safe.segmentCorrectMap.entries.associate { (seg, correct) ->
                val ratio = correct.toFloat() / totalCorrect
                val coins = ((accuracyBonus + streakBonus + checkinBonus) * safe.yogaMultiplier * ratio)
                    .toInt().coerceAtLeast(0)
                seg to coins
            }.filter { it.value > 0 }
        } else emptyMap()

        val breakdown = buildString {
            append("${base}base")
            if (accuracyBonus > 0) append("+${accuracyBonus}accuracy")
            if (streakBonus > 0) append("+${streakBonus}streak")
            if (checkinBonus > 0) append("+${checkinBonus}checkin")
            if (safe.yogaMultiplier != 1f) append("×${safe.yogaMultiplier}multiplier")
            append("=${total}")
        }

        return Result(base, accuracyBonus, streakBonus, checkinBonus, total, segCoins, breakdown)
    }
}

package com.aipoweredgita.app.coin

import android.content.Context
import java.time.LocalDate

/**
 * Daily check-in, weekly bonus, and share reward tracking.
 * All state persisted in SharedPreferences — no Room needed.
 *
 * Thread-safe: all write methods synchronize.
 * Corrupt dates: silently default rather than crash.
 */
class DailyRewardsTracker(private val prefs: android.content.SharedPreferences) {

    companion object {
        // Check-in keys
        private const val KEY_DAY = "reward_day"
        private const val KEY_DATE = "reward_last_date"
        private const val KEY_PROTECTION = "reward_protection"
        private const val KEY_WEEK = "reward_week"

        // Daily share keys
        private const val KEY_SHARE_DAY = "share_reward_day"
        private const val KEY_SHARE_DATE = "share_reward_last_date"
        private const val KEY_SHARE_PROTECTION = "share_reward_protection"
        private const val KEY_SHARE_WEEK = "share_reward_week"

        // Same-week completion tracking (ISO week-based year + week number)
        private const val KEY_CHECKIN_COMPLETED_WEEK = "checkin_completed_week"
        private const val KEY_SHARE_COMPLETED_WEEK = "share_completed_week"
        // Whether protection was already granted for a completed week
        private const val KEY_CHECKIN_PROT_GRANTED = "checkin_protection_granted"
        private const val KEY_SHARE_PROT_GRANTED = "share_protection_granted"

        fun getInstance(context: Context): DailyRewardsTracker {
            val p = context.getSharedPreferences("daily_rewards", Context.MODE_PRIVATE)
            return DailyRewardsTracker(p)
        }
    }

    var isCheckinSynced: Boolean
        get() {
            val today = now()
            val lastDate = prefs.getString(KEY_DATE, "") ?: ""
            if (lastDate != today) return false
            return prefs.getBoolean("checkin_synced", false)
        }
        set(value) {
            prefs.edit().putBoolean("checkin_synced", value).apply()
        }

    var isShareSynced: Boolean
        get() {
            val today = now()
            val lastDate = prefs.getString(KEY_SHARE_DATE, "") ?: ""
            if (lastDate != today) return false
            return prefs.getBoolean("share_synced", false)
        }
        set(value) {
            prefs.edit().putBoolean("share_synced", value).apply()
        }

    fun syncWithServer(serverDay: Int, serverWeek: Int, lastCheckin: String? = null) {
        if (serverDay in 1..7) {
            synchronized(this) {
                val currentDay = prefs.getInt(KEY_DAY, 1)
                val currentWeek = prefs.getInt(KEY_WEEK, 1)

                // Map server state to client semantics:
                // Server day=7 with week=N means "Week N-1 complete, transitioning to Week N"
                // Client uses KEY_DAY=0 to mean "between weeks" and KEY_WEEK as the completed week
                // Handles wrap: server week=1 after day=7 means completed week 4
                val effectiveDay = if (serverDay == 7) 0 else serverDay
                val effectiveWeek = if (serverDay == 7) {
                    if (serverWeek == 1) 4 else serverWeek - 1
                } else serverWeek

                // Never downgrade: server must be equal or more advanced
                if (effectiveWeek < currentWeek) return
                if (effectiveWeek == currentWeek) {
                    val localComplete = currentDay == 0
                    val serverComplete = effectiveDay == 0
                    // Local week complete but server says still in-progress — don't downgrade
                    if (localComplete && !serverComplete) return
                    // Both in-progress — don't downgrade day
                    if (!localComplete && !serverComplete && effectiveDay <= currentDay) return
                }

                prefs.edit().apply {
                    putInt(KEY_DAY, effectiveDay)
                    putInt(KEY_WEEK, effectiveWeek)
                    // Only overwrite local date if server date is more recent
                    if (lastCheckin != null) {
                        val currentDate = prefs.getString(KEY_DATE, "") ?: ""
                        if (currentDate.isEmpty() || lastCheckin > currentDate) {
                            putString(KEY_DATE, lastCheckin)
                        }
                    }
                }.commit()
            }
        }
    }

    fun syncShareWithServer(serverDay: Int, serverWeek: Int, lastShare: String? = null) {
        if (serverDay in 1..7) {
            synchronized(this) {
                val currentDay = prefs.getInt(KEY_SHARE_DAY, 1)
                val currentWeek = prefs.getInt(KEY_SHARE_WEEK, 1)

                // Map server state to client semantics (same as syncWithServer)
                val effectiveDay = if (serverDay == 7) 0 else serverDay
                val effectiveWeek = if (serverDay == 7) {
                    if (serverWeek == 1) 4 else serverWeek - 1
                } else serverWeek

                // Never downgrade: server must be equal or more advanced
                if (effectiveWeek < currentWeek) return
                if (effectiveWeek == currentWeek) {
                    val localComplete = currentDay == 0
                    val serverComplete = effectiveDay == 0
                    if (localComplete && !serverComplete) return
                    if (!localComplete && !serverComplete && effectiveDay <= currentDay) return
                }

                prefs.edit().apply {
                    putInt(KEY_SHARE_DAY, effectiveDay)
                    putInt(KEY_SHARE_WEEK, effectiveWeek)
                    // Only overwrite local date if server date is more recent
                    if (lastShare != null) {
                        val currentDate = prefs.getString(KEY_SHARE_DATE, "") ?: ""
                        if (currentDate.isEmpty() || lastShare > currentDate) {
                            putString(KEY_SHARE_DATE, lastShare)
                        }
                    }
                }.commit()
            }
        }
    }

    // ── Daily Check-in ───────────────────────────────────────────────────────

    data class DailyState(
        val day: Int, 
        val todayClaimed: Boolean, 
        val reward: Int,
        val hasProtection: Boolean, 
        val protectionWillAutoAdvance: Boolean, 
        val week: Int
    )

    fun getDailyState(): DailyState {
        val today = now()
        val yesterday = yesterdayStr(today)
        var lastDate = prefs.getString(KEY_DATE, "") ?: ""
        var week = prefs.getInt(KEY_WEEK, 1).coerceIn(1, 4)
        val protection = prefs.getInt(KEY_PROTECTION, 0).coerceAtLeast(0)
        var rawDay = prefs.getInt(KEY_DAY, 1).coerceIn(0, 7)

        // Migration: after claimDay7BonusIfEligible, KEY_DAY is set to 0.
        // If it's still 7 with lastDate==today and week>1, the old server sync overwrote it.
        // Fix: restore KEY_DAY=0, undo the premature week advance, and push KEY_DATE
        // to yesterday so getDailyState() falls into the "next day" branch (day 1 of next week).
        if (rawDay == 7 && lastDate == today && week > 1) {
            rawDay = 0
            week = if (week == 1) 4 else week - 1
            prefs.edit().apply {
                putInt(KEY_DAY, 0)
                putInt(KEY_WEEK, week)
                putString(KEY_DATE, yesterday)
            }.commit()
            lastDate = yesterday
        }

        if (lastDate == today) {
            return DailyState(
                day = if (rawDay == 0) 7 else rawDay,
                todayClaimed = true,
                reward = if (rawDay == 0) 7 else rawDay,
                hasProtection = protection > 0,
                protectionWillAutoAdvance = false,
                week = week
            )
        }

        if (lastDate.isEmpty()) {
            return DailyState(
                day = 1,
                todayClaimed = false,
                reward = 1,
                hasProtection = protection > 0,
                protectionWillAutoAdvance = false,
                week = 1
            )
        }

        if (lastDate == yesterday) {
            val nextDay = if (rawDay == 0 || rawDay == 7) 1 else rawDay + 1
            val nextWeek = if (rawDay == 0 || rawDay == 7) {
                if (week >= 4) 1 else week + 1
            } else week
            return DailyState(
                day = nextDay,
                todayClaimed = false,
                reward = nextDay,
                hasProtection = protection > 0,
                protectionWillAutoAdvance = false,
                week = nextWeek
            )
        }

        // Missed day(s)
        if (protection > 0) {
            val nextDay = if (rawDay == 0 || rawDay == 7) 1 else rawDay + 1
            val nextWeek = if (rawDay == 0 || rawDay == 7) {
                if (week >= 4) 1 else week + 1
            } else week
            return DailyState(
                day = nextDay,
                todayClaimed = false,
                reward = nextDay,
                hasProtection = true,
                protectionWillAutoAdvance = true,
                week = nextWeek
            )
        }

        // Reset to Week 1, Day 1 — persist so stale KEY_WEEK doesn't leak into next claim
        prefs.edit().apply {
            putInt(KEY_DAY, 1)
            putInt(KEY_WEEK, 1)
            putInt(KEY_PROTECTION, 0)
        }.commit()
        return DailyState(
            day = 1,
            todayClaimed = false,
            reward = 1,
            hasProtection = false,
            protectionWillAutoAdvance = false,
            week = 1
        )
    }

    fun claimDaily(): Int {
        val s = getDailyState()
        if (s.todayClaimed) return 0
        val today = now()
        synchronized(this) {
            if (prefs.getString(KEY_DATE, "") == today) return 0
            val editor = prefs.edit()
            if (s.protectionWillAutoAdvance) {
                val p = (prefs.getInt(KEY_PROTECTION, 0) - 1).coerceAtLeast(0)
                editor.putInt(KEY_PROTECTION, p)
            }
            editor.putInt(KEY_DAY, s.day)
            editor.putInt(KEY_WEEK, s.week)
            editor.putString(KEY_DATE, today)
            editor.putBoolean("checkin_synced", false)
            editor.commit()  // synchronous — prevents race with async reads
            return s.reward
        }
    }

    fun claimDay7BonusIfEligible(): Int = synchronized(this) {
        val day = prefs.getInt(KEY_DAY, 1)
        val last = prefs.getString(KEY_DATE, "") ?: ""
        val today = now()
        if (day == 7 && last == today) {
            // Mark check-in week as completed
            val calWeek = currentCalendarWeek()
            prefs.edit().apply {
                putInt(KEY_DAY, 0)
                putString(KEY_CHECKIN_COMPLETED_WEEK, calWeek)
                putBoolean(KEY_CHECKIN_PROT_GRANTED, false)
            }.commit()
            // If share also completed Day 7 this same week, grant protection to both
            grantBothProtectionsIfNeeded(calWeek)
            return 7
        }
        return 0
    }

    fun getCurrentCheckinDay(): Int = prefs.getInt(KEY_DAY, 1).coerceIn(1, 7)

    // ── Weekly Bonus (auto-claimed with Day 7) ──────────────────────────────

    data class WeeklyState(val week: Int, val reward: Int)

    fun getWeeklyState(): WeeklyState {
        val week = prefs.getInt(KEY_WEEK, 1).coerceIn(1, 4)
        return WeeklyState(week, if (week == 4) 20 else 10)
    }

    // ── Daily Share ──────────────────────────────────────────────────────────

    data class ShareState(
        val day: Int, 
        val todayClaimed: Boolean, 
        val reward: Int, 
        val hasProtection: Boolean,
        val protectionWillAutoAdvance: Boolean,
        val week: Int
    )

    fun getShareState(): ShareState {
        val today = now()
        val yesterday = yesterdayStr(today)
        var lastDate = prefs.getString(KEY_SHARE_DATE, "") ?: ""
        var week = prefs.getInt(KEY_SHARE_WEEK, 1).coerceIn(1, 4)
        val protection = prefs.getInt(KEY_SHARE_PROTECTION, 0).coerceAtLeast(0)
        var rawDay = prefs.getInt(KEY_SHARE_DAY, 1).coerceIn(0, 7)

        // Migration: same as getDailyState — fix corrupted KEY_SHARE_DAY=7 from old sync (week>1 only)
        if (rawDay == 7 && lastDate == today && week > 1) {
            rawDay = 0
            week = if (week == 1) 4 else week - 1
            prefs.edit().apply {
                putInt(KEY_SHARE_DAY, 0)
                putInt(KEY_SHARE_WEEK, week)
                putString(KEY_SHARE_DATE, yesterday)
            }.commit()
            lastDate = yesterday
        }

        if (lastDate == today) {
            return ShareState(
                day = if (rawDay == 0) 7 else rawDay,
                todayClaimed = true,
                reward = if (rawDay == 0) 7 else rawDay,
                hasProtection = protection > 0,
                protectionWillAutoAdvance = false,
                week = week
            )
        }

        if (lastDate.isEmpty()) {
            return ShareState(1, false, 1, protection > 0, false, 1)
        }

        if (lastDate == yesterday) {
            val nextDay = if (rawDay == 0 || rawDay == 7) 1 else rawDay + 1
            val nextWeek = if (rawDay == 0 || rawDay == 7) {
                if (week >= 4) 1 else week + 1
            } else week
            return ShareState(nextDay, false, nextDay, protection > 0, false, nextWeek)
        }

        if (protection > 0) {
            val nextDay = if (rawDay == 0 || rawDay == 7) 1 else rawDay + 1
            val nextWeek = if (rawDay == 0 || rawDay == 7) {
                if (week >= 4) 1 else week + 1
            } else week
            return ShareState(nextDay, false, nextDay, true, true, nextWeek)
        }

        // Reset to Week 1, Day 1 — persist so stale KEY_SHARE_WEEK doesn't leak into next claim
        prefs.edit().apply {
            putInt(KEY_SHARE_DAY, 1)
            putInt(KEY_SHARE_WEEK, 1)
            putInt(KEY_SHARE_PROTECTION, 0)
        }.commit()
        return ShareState(1, false, 1, false, false, 1)
    }

    fun claimShare(): Int {
        val s = getShareState()
        if (s.todayClaimed) return 0
        synchronized(this) {
            if (prefs.getString(KEY_SHARE_DATE, "") == now()) return 0
            val editor = prefs.edit()
            if (s.protectionWillAutoAdvance) {
                val p = (prefs.getInt(KEY_SHARE_PROTECTION, 0) - 1).coerceAtLeast(0)
                editor.putInt(KEY_SHARE_PROTECTION, p)
            }
            editor.putInt(KEY_SHARE_DAY, s.day)
            editor.putInt(KEY_SHARE_WEEK, s.week)
            editor.putString(KEY_SHARE_DATE, now())
            editor.putBoolean("share_synced", false)
            editor.commit()  // synchronous — prevents race with async reads
            return s.reward
        }
    }

    fun claimShareDay7BonusIfEligible(): Int = synchronized(this) {
        val day = prefs.getInt(KEY_SHARE_DAY, 1)
        val last = prefs.getString(KEY_SHARE_DATE, "") ?: ""
        val today = now()
        if (day == 7 && last == today) {
            // Mark share week as completed
            val calWeek = currentCalendarWeek()
            prefs.edit().apply {
                putInt(KEY_SHARE_DAY, 0)
                putString(KEY_SHARE_COMPLETED_WEEK, calWeek)
                putBoolean(KEY_SHARE_PROT_GRANTED, false)
            }.commit()
            // If check-in also completed Day 7 this same week, grant protection to both
            grantBothProtectionsIfNeeded(calWeek)
            return 7
        }
        return 0
    }

    fun getShareWeeklyState(): WeeklyState {
        val week = prefs.getInt(KEY_SHARE_WEEK, 1).coerceIn(1, 4)
        return WeeklyState(week, if (week == 4) 20 else 10)
    }

    // ── Fresh install detection ──────────────────────────────────────────────

    fun isFreshInstall(): Boolean {
        val checkinDate = prefs.getString(KEY_DATE, "") ?: ""
        val shareDate = prefs.getString(KEY_SHARE_DATE, "") ?: ""
        return checkinDate.isEmpty() && shareDate.isEmpty()
    }

    // ── Internal ─────────────────────────────────────────────────────────────

    private fun now() = LocalDate.now(java.time.ZoneId.systemDefault()).toString()

    fun nowLocal() = LocalDate.now(java.time.ZoneId.systemDefault()).toString()

    private fun yesterdayStr(date: String) = try {
        LocalDate.parse(date).minusDays(1).toString()
    } catch (_: Exception) {
        ""
    }

    /** ISO week-based year + week number, e.g. "2025-W23" */
    private fun currentCalendarWeek(): String {
        val date = LocalDate.now(java.time.ZoneId.systemDefault())
        val week = date.get(java.time.temporal.IsoFields.WEEK_OF_WEEK_BASED_YEAR)
        val year = date.get(java.time.temporal.IsoFields.WEEK_BASED_YEAR)
        return "${year}-W${week}"
    }

    /**
     * Called after either activity completes Day 7.
     * If BOTH check-in and share completed Day 7 in the same calendar week,
     * grant 1 protection token to each (once per week).
     */
    private fun grantBothProtectionsIfNeeded(calWeek: String) {
        val checkinWeek = prefs.getString(KEY_CHECKIN_COMPLETED_WEEK, "") ?: ""
        val shareWeek = prefs.getString(KEY_SHARE_COMPLETED_WEEK, "") ?: ""
        if (checkinWeek == calWeek && shareWeek == calWeek) {
            val editor = prefs.edit()
            if (!prefs.getBoolean(KEY_CHECKIN_PROT_GRANTED, false)) {
                editor.putInt(KEY_PROTECTION, prefs.getInt(KEY_PROTECTION, 0) + 1)
                editor.putBoolean(KEY_CHECKIN_PROT_GRANTED, true)
            }
            if (!prefs.getBoolean(KEY_SHARE_PROT_GRANTED, false)) {
                editor.putInt(KEY_SHARE_PROTECTION, prefs.getInt(KEY_SHARE_PROTECTION, 0) + 1)
                editor.putBoolean(KEY_SHARE_PROT_GRANTED, true)
            }
            editor.commit()
        }
    }
}

package com.aipoweredgita.app.repository

import androidx.room.withTransaction
import com.aipoweredgita.app.database.*

class QuizRepositoryImpl(
    private val database: GitaDatabase,
    private val quizAttemptDao: QuizAttemptDao,
    private val questionPerformanceDao: QuestionPerformanceDao,
    private val translationCacheDao: TranslationCacheDao,
    private val statsRepository: StatsRepository,
    private val yogaProgressionRepository: YogaProgressionRepository
) : QuizRepository {

    override suspend fun saveQuizAttemptWithStats(
        attempt: QuizAttempt,
        score: Int,
        totalQuestions: Int,
        segmentCorrectMap: Map<String, Int>,
        quizType: String
    ): Triple<Boolean, Int?, Int> {
        return database.withTransaction {
            val coinsEarned = statsRepository.trackQuizCompletion(score, totalQuestions, segmentCorrectMap, quizType, attempt.timeSpentSeconds)
            quizAttemptDao.insertAttempt(attempt.copy(coinsEarned = coinsEarned))
            val (didLevelUp, newLevel) = yogaProgressionRepository.updateFromQuiz(score, totalQuestions)
            Triple(didLevelUp, newLevel, coinsEarned)
        }
    }

    override suspend fun getCachedTranslation(originalText: String, languageCode: String): TranslationCache? {
        return translationCacheDao.getTranslation(originalText, languageCode)
    }

    override suspend fun saveTranslationToCache(translation: TranslationCache) {
        translationCacheDao.insertTranslation(translation)
    }

    override suspend fun updateQuestionPerformance(
        qId: String,
        theme: String,
        typeName: String,
        isCorrect: Boolean,
        difficultyLevel: Int
    ) {
        database.withTransaction {
            val existing = questionPerformanceDao.getPerformanceByQuestion(qId)
            val attempts = (existing?.timesAttempted ?: 0) + 1
            val corrects = (existing?.timesCorrect ?: 0) + if (isCorrect) 1 else 0
            val successRate = if (attempts > 0) (corrects.toFloat() * 100f / attempts) else 0f
            val perf = (existing ?: QuestionPerformance()).copy(
                questionId = qId,
                topicCategory = theme,
                questionType = typeName,
                timesAttempted = attempts,
                timesCorrect = corrects,
                successRate = successRate,
                perceivedDifficulty = difficultyLevel,
                lastAttempted = System.currentTimeMillis()
            )
            if (existing == null) {
                questionPerformanceDao.insert(perf)
            } else {
                questionPerformanceDao.update(perf)
            }
        }
    }

    override suspend fun getRecentlyAskedQuestions(limit: Int): List<QuestionPerformance> {
        return questionPerformanceDao.getRecentlyAskedQuestions(limit)
    }
}

package com.aipoweredgita.app.repository

import android.content.Context
import android.util.Log
import com.aipoweredgita.app.network.AuthLoginRequest
import com.aipoweredgita.app.network.AuthRegisterRequest
import com.aipoweredgita.app.network.CoinApi
import com.aipoweredgita.app.utils.AuthPreferences
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

/**
 * Manages authentication operations.
 */
class AuthManager(private val context: Context) {

    private val authPrefs = AuthPreferences.getInstance(context)
    private val guestSyncManager = GuestSyncManager.getInstance(context)

    companion object {
        private const val TAG = "AuthManager"

        @Volatile
        private var INSTANCE: AuthManager? = null

        fun getInstance(context: Context): AuthManager {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: AuthManager(context.applicationContext).also { INSTANCE = it }
            }
        }
    }

    /**
     * Register a new user
     */
    suspend fun register(
        userId: String,
        password: String,
        name: String = "",
        email: String = ""
    ): Result<AuthResult> = withContext(Dispatchers.IO) {
        try {
            val response = CoinApi.retrofitService.register(
                AuthRegisterRequest(userId, password, name, email)
            )

            if (response.success) {
                val wasGuest = authPrefs.isGuest || !authPrefs.isLoggedIn
                val db = com.aipoweredgita.app.database.GitaDatabase.getDatabase(context)
                val previousCoins = db.userStatsDao().getUserStatsOnce()?.krishnaCoins ?: 0

                // Save auth state
                authPrefs.saveLoginState(
                    userId = response.user_id,
                    name = name,
                    loginMethod = "password",
                    token = response.token,
                    email = email,
                    password = password
                )

                // Update Room DB with new user info
                db.userStatsDao().updateUserId(response.user_id)
                db.userStatsDao().updateProfile(name = name.ifEmpty { "Gita Seeker" }, dob = "")

                if (wasGuest) {
                    val guestConversionCoins = previousCoins + response.coins
                    db.userStatsDao().updateKrishnaCoins(guestConversionCoins)
                    com.aipoweredgita.app.coin.CoinTransactionLogger.log(context, response.coins, "Guest to User conversion bonus")
                } else {
                    db.userStatsDao().updateKrishnaCoins(response.coins.coerceAtLeast(0))
                }

                // Sync guest data if exists
                if (guestSyncManager.hasGuestDataToSync()) {
                    guestSyncManager.syncGuestData(response.user_id, name, email)
                }

                Log.d(TAG, "Registration successful: ${response.user_id}")
                return@withContext Result.success(
                    AuthResult(
                        userId = response.user_id,
                        token = response.token,
                        coins = response.coins
                    )
                )
            } else {
                Log.e(TAG, "Registration failed: ${response.error}")
                return@withContext Result.failure(Exception(response.error ?: "Registration failed"))
            }
        } catch (e: Exception) {
            Log.e(TAG, "Registration error: ${e.message}")
            return@withContext Result.failure(e)
        }
    }

    /**
     * Login with existing credentials
     */
    suspend fun login(
        userId: String,
        password: String
    ): Result<AuthResult> = withContext(Dispatchers.IO) {
        try {
            val response = CoinApi.retrofitService.login(
                AuthLoginRequest(userId, password)
            )

if (response.success) {
                val wasGuest = authPrefs.hasGuestSession()
                val db = com.aipoweredgita.app.database.GitaDatabase.getDatabase(context)
                val previousCoins = db.userStatsDao().getUserStatsOnce()?.krishnaCoins ?: 0

                // Extract a display name from email/username
                val displayName = userId.substringBefore("@").replaceFirstChar { it.uppercase() }

                // Save auth state
                authPrefs.saveLoginState(
                    userId = response.user_id,
                    name = displayName,
                    loginMethod = "password",
                    token = response.token,
                    email = userId,
                    password = password
                )

                // Update Room DB with new user info
                db.userStatsDao().updateUserId(response.user_id)

                val existingStats = db.userStatsDao().getUserStatsOnce()
                val currentName = existingStats?.userName ?: ""
                val newName = if (currentName.isEmpty() || currentName == "Gita Seeker" || currentName == "Arjuna") {
                    displayName
                } else {
                    currentName
                }
                db.userStatsDao().updateProfile(name = newName, dob = existingStats?.dateOfBirth ?: "")

                // Sync coins from server response (not hardcoded 200)
                // Server returns the user's actual balance including welcome bonus
                if (wasGuest) {
                    val guestConversionCoins = previousCoins + response.coins
                    db.userStatsDao().updateKrishnaCoins(guestConversionCoins)
                    com.aipoweredgita.app.coin.CoinTransactionLogger.log(context, response.coins, "Guest to User conversion bonus")
                } else {
                    db.userStatsDao().updateKrishnaCoins(response.coins.coerceAtLeast(0))
                }

                // Sync guest data if exists
                if (guestSyncManager.hasGuestDataToSync()) {
                    guestSyncManager.syncGuestData(response.user_id)
                }

                // Run auto-reconciliation after login to detect any discrepancies
                try {
                    val reconciliationManager = CoinReconciliationManager(context)
                    val result = reconciliationManager.autoReconcile()
                    when (result) {
                        is AutoReconciliationResult.Corrected -> {
                            Log.w(TAG, "Auto-reconciliation corrected after login: ${result.oldBalance} → ${result.newBalance}")
                        }
                        is AutoReconciliationResult.Error -> {
                            Log.e(TAG, "Auto-reconciliation failed after login: ${result.message}")
                        }
                        else -> { /* OK or Skip */ }
                    }
                } catch (e: Exception) {
                    Log.e(TAG, "Auto-reconciliation failed during login", e)
                }

                // Pull server state into local DB (streak, quizzes, verses, DailyRewardsTracker)
                try {
                    val dbInstance = com.aipoweredgita.app.database.GitaDatabase.getDatabase(context)
                    val statsRepo = com.aipoweredgita.app.repository.StatsRepository(
                        dbInstance.userStatsDao(),
                        dbInstance.dailyActivityDao(),
                        context
                    )
                    statsRepo.refreshUserState(response.user_id)
                    statsRepo.syncStatsToServer()
                } catch (e: Exception) {
                    Log.e(TAG, "Stats sync failed during login", e)
                }

                Log.d(TAG, "Login successful: ${response.user_id}")
                return@withContext Result.success(
                    AuthResult(
                        userId = response.user_id,
                        token = response.token,
                        coins = response.coins
                    )
                )
            } else {
                Log.e(TAG, "Login failed: ${response.error}")
                return@withContext Result.failure(Exception(response.error ?: "Login failed"))
            }
        } catch (e: Exception) {
            Log.e(TAG, "Login error: ${e.message}")
            return@withContext Result.failure(e)
        }
    }

    /**
     * Logout current user
     */
    suspend fun logout() = withContext(Dispatchers.IO) {
        val token = authPrefs.token
        if (token != null) {
            try {
                CoinApi.retrofitService.logout("Bearer $token")
            } catch (e: Exception) {
                Log.e(TAG, "Logout API error: ${e.message}")
            }
        }
        authPrefs.clearLoginState()
    }

    /**
     * Delete user account from server and clear all local data.
     * Returns true if server deletion succeeded (or was unreachable but local cleanup done).
     */
    suspend fun deleteAccount(): Result<Unit> = withContext(Dispatchers.IO) {
        val token = authPrefs.token
        if (token != null) {
            try {
                CoinApi.retrofitService.deleteAccount("Bearer $token")
                Log.d(TAG, "Account deleted from server")
            } catch (e: Exception) {
                Log.w(TAG, "Delete account API error (proceeding with local cleanup): ${e.message}")
            }
        }
        // Clear ALL local data including credentials
        authPrefs.clearAll()
        Result.success(Unit)
    }

    /**
     * Check if user is logged in
     */
    fun isLoggedIn(): Boolean {
        return authPrefs.isLoggedIn && authPrefs.token != null
    }

    /**
     * Get current user ID
     */
    fun getCurrentUserId(): String? {
        return authPrefs.userId
    }

    /**
     * Get current auth token
     */
    fun getToken(): String? {
        return authPrefs.token
    }
}

/**
 * Result of an authentication operation
 */
data class AuthResult(
    val userId: String,
    val token: String,
    val coins: Int
)

